// AUTO-GENERATED by scripts/merge.mjs. CompTIA Security+ SY0-701 twin-term drill bank.
// Do not edit by hand; edit the chunk sources in data/gen/ and re-run merge.
export const QUESTIONS = [
  {"id":"q001","domain":"D1","family":"control-categories","question":"A newly hired CISO's first two initiatives are establishing a quarterly risk assessment cycle and publishing a formal data classification policy that every department must follow. Which control category BEST describes these initiatives?","options":["technical","managerial","operational","physical"],"correctIndex":1,"explanation":"Managerial. Risk assessments and written policies are administrative decisions made by leadership, not anything enforced by technology or performed day to day by staff. The tell: technical = enforced in hardware/software, managerial = policy and risk decisions, operational = day-to-day human processes, physical = tangible barriers."},
  {"id":"q002","domain":"D1","family":"control-categories","question":"A security manager schedules monthly phishing-awareness training for all staff and requires SOC analysts to follow a documented incident-handling checklist on every shift. Which control category do these activities fall under?","options":["managerial","physical","operational","technical"],"correctIndex":2,"explanation":"Operational. Recurring training and analysts working a checklist are day-to-day processes carried out by people. Writing the policy would be managerial; these activities are its human execution. The tell: operational = human day-to-day processes, managerial = policy/risk decisions, physical = tangible barriers, technical = implemented in tech."},
  {"id":"q003","domain":"D1","family":"control-categories","question":"To reduce its attack surface, an engineering team deploys a next-generation firewall at the perimeter and enables full-disk encryption on every laptop. Which control category do these two measures fall under?","options":["managerial","operational","technical","physical"],"correctIndex":2,"explanation":"Technical. Firewalls and encryption enforce protection through hardware and software mechanisms rather than policy, people, or barriers. The tell: technical = implemented in tech/hardware/software, managerial = policy and risk decisions, operational = day-to-day human processes, physical = tangible barriers."},
  {"id":"q004","domain":"D1","family":"control-categories","question":"A colocation facility protects its server hall with cipher locks on every door, steel perimeter fencing, and a guard posted at the single entrance. Which control category do these protections belong to?","options":["physical","technical","operational","managerial"],"correctIndex":0,"explanation":"Physical. Locks, fences, and guards are tangible barriers that control real-world access to the space. The tell: physical = tangible barriers (locks, fences, guards), technical = enforced in hardware/software, operational = day-to-day human processes, managerial = policy and risk decisions."},
  {"id":"q005","domain":"D1","family":"control-types","question":"After several after-hours break-in attempts, a facilities team installs high-intensity lighting around a parking garage and posts signs stating the area is patrolled and recorded. No new barriers or alarm systems are added. Which control type BEST describes these measures?","options":["preventive","deterrent","detective","corrective"],"correctIndex":1,"explanation":"Deterrent. Lighting and warning signs discourage an intruder from trying but cannot physically stop or even record anyone, so nothing is prevented or detected. The tell: deterrent = discourages the attempt, preventive = actually stops it, detective = finds it after, corrective = restores after."},
  {"id":"q006","domain":"D1","family":"control-types","question":"A hospital runs a legacy imaging server whose vendor no longer releases patches. Because the known vulnerabilities cannot be fixed, the security team places the server behind stricter firewall rules and adds continuous network monitoring until it is replaced. Which control type do the added measures represent?","options":["deterrent","corrective","directive","compensating"],"correctIndex":3,"explanation":"Compensating. The primary control, patching, is not feasible, so alternate safeguards stand in to reduce the same risk. The tell: compensating = alternate when the primary control is not possible, corrective = restores after an event, directive = mandates behavior, deterrent = discourages."},
  {"id":"q007","domain":"D1","family":"control-types","question":"A SOC receives an IDS alert about a completed intrusion, and a guard reviewing last night's camera footage spots the same event. Neither tool stopped the attack. Which control type do the IDS and the footage review represent?","options":["corrective","preventive","detective","directive"],"correctIndex":2,"explanation":"Detective. Both the IDS alert and the footage review identify and record an incident only after it happened. The tell: detective = finds it after, corrective = fixes/restores after, preventive = stops it before, directive = mandates behavior."},
  {"id":"q008","domain":"D1","family":"control-types","question":"Before receiving network credentials, every new employee must read and sign an acceptable use policy spelling out exactly how company systems may and may not be used. Which control type is the policy itself?","options":["directive","preventive","deterrent","compensating"],"correctIndex":0,"explanation":"Directive. An acceptable use policy mandates required behavior; it instructs rather than blocks, discourages, or substitutes. The tell: directive = mandates behavior, preventive = stops it before it happens, deterrent = discourages, compensating = alternate when the primary control is not feasible."},
  {"id":"q009","domain":"D1","family":"control-types","question":"A security architect points out that a door lock and a firewall access rule share the same purpose: each stops an unauthorized party from getting in before any damage can occur. Which control type describes both?","options":["detective","preventive","corrective","deterrent"],"correctIndex":1,"explanation":"Preventive. Both controls physically or logically block the attempt before it succeeds, regardless of one being physical and the other technical. The tell: preventive = stops it before it happens, deterrent = only discourages, detective = finds it after, corrective = restores after."},
  {"id":"q010","domain":"D1","family":"control-types","question":"Ransomware encrypts a file server overnight. The next day the team restores the data from the previous night's backup and applies the patch that closed the exploited vulnerability. Which control type does the backup restore represent?","options":["corrective","preventive","compensating","detective"],"correctIndex":0,"explanation":"Corrective. Restoring from backup fixes the damage and returns operations to normal after the incident already happened. The tell: corrective = fixes/restores after the event, preventive = stops it before, compensating = alternate control when the primary is not feasible, detective = finds it after."},
  {"id":"q011","domain":"D1","family":"control-types","question":"Each morning a SIEM correlates the previous night's collected logs and surfaces a suspicious 2:00 a.m. admin login that has already taken place. Which control type is the SIEM acting as?","options":["deterrent","directive","detective","corrective"],"correctIndex":2,"explanation":"Detective. The SIEM identifies an event after the fact; it neither blocked it nor fixed anything. The tell: detective = finds it after (logs, IDS, reviewed footage), deterrent = discourages, directive = mandates behavior, corrective = restores after."},
  {"id":"q012","domain":"D1","family":"cia-nonrepudiation","question":"A legal department requires that every outbound contract be digitally signed so that an executive cannot later claim they never approved the document. Which security principle does the signature requirement provide?","options":["integrity","availability","non-repudiation","confidentiality"],"correctIndex":2,"explanation":"Non-repudiation. The goal stated is preventing denial of an action, which is exactly what a digital signature provides. It also gives integrity, but the scenario's requirement is the inability to deny approval. The tell: non-repudiation = cannot deny you did it, integrity = unaltered, confidentiality = secrecy, availability = uptime."},
  {"id":"q013","domain":"D1","family":"cia-nonrepudiation","question":"A backup administrator configures the backup platform to store a SHA-256 hash of every file it writes. During restore tests, hashes are recomputed and compared to detect any alteration. Which principle is being protected?","options":["integrity","confidentiality","availability","non-repudiation"],"correctIndex":0,"explanation":"Integrity. Hashing detects whether data changed; it does not hide data or keep systems up. The tell: integrity = unaltered (hashing, checksums), confidentiality = secrecy (encryption), availability = uptime (redundancy), non-repudiation = cannot deny you did it (signatures)."},
  {"id":"q014","domain":"D1","family":"cia-nonrepudiation","question":"An e-commerce company deploys clustered web servers, a standby database replica, and regularly tested backups so the storefront stays reachable even when a component fails. Which CIA triad principle is this design serving?","options":["confidentiality","availability","integrity","non-repudiation"],"correctIndex":1,"explanation":"Availability. Redundancy, replicas, and tested backups all exist to keep the service up. The tell: availability = uptime (redundancy, backups), confidentiality = secrecy, integrity = unaltered, non-repudiation = cannot deny you did it."},
  {"id":"q015","domain":"D1","family":"cia-nonrepudiation","question":"A hospital encrypts patient records at rest and in transit so that only authorized clinicians can read them and an intercepted copy is useless to outsiders. Which CIA triad principle is this protecting?","options":["confidentiality","integrity","availability","non-repudiation"],"correctIndex":0,"explanation":"Confidentiality. Encryption for secrecy keeps unauthorized parties from reading the data. The tell: confidentiality = secrecy (encryption), integrity = unaltered (hashing), availability = uptime (redundancy), non-repudiation = cannot deny you did it (signatures)."},
  {"id":"q016","domain":"D1","family":"cia-nonrepudiation","question":"A database platform writes a detailed audit log tying every schema change to the specific administrator account that made it, so no admin can credibly deny an action later. Which principle does this support?","options":["integrity","availability","non-repudiation","confidentiality"],"correctIndex":2,"explanation":"Non-repudiation. Binding actions to identities so they cannot be denied is non-repudiation; the logs may help integrity too, but the stated goal is preventing denial. The tell: non-repudiation = cannot deny you did it (audit logs, signatures), integrity = data unaltered, confidentiality = secrecy, availability = uptime."},
  {"id":"q017","domain":"D1","family":"aaa","question":"A network engineer configures the RADIUS server so that every VPN user's login time, session duration, and data transferred are logged for a later audit and for per-department billing. Which part of the AAA framework is being implemented?","options":["identification","authentication","accounting","authorization"],"correctIndex":2,"explanation":"Accounting. Recording who did what, when, and for how long is the accounting leg of AAA. The tell: authentication = prove who you are, authorization = what you are allowed to do, accounting = record what you did, identification = merely claiming an identity."},
  {"id":"q018","domain":"D1","family":"aaa","question":"After an engineer's smart card and PIN are accepted, the file server checks her group memberships to decide whether she can open the payroll share. Which AAA component performs this second step?","options":["authentication","authorization","accounting","identification"],"correctIndex":1,"explanation":"Authorization. Identity is already proven; deciding what she may access is authorization. The tell: authentication = prove who you are, authorization = what you are allowed to do once proven, accounting = record what you did, identification = the claim itself."},
  {"id":"q019","domain":"D1","family":"aaa","question":"Before allowing a session, a remote-access system verifies a user's claimed identity by checking both a password and a fingerprint scan. Which AAA component is performing this check?","options":["accounting","authentication","authorization","identification"],"correctIndex":1,"explanation":"Authentication. Verifying the claimed identity with factors (password, fingerprint) is authentication; stating the username was merely identification. The tell: authentication = prove who you are, identification = claim who you are, authorization = what you may access, accounting = record what you did."},
  {"id":"q020","domain":"D1","family":"aaa","question":"John signs in successfully, and the system then checks his role and permits him to open only the finance department's folder while denying everything else. Which AAA component makes that determination?","options":["authorization","authentication","accounting","identification"],"correctIndex":0,"explanation":"Authorization. Deciding what an already-authenticated user may access is authorization. The tell: authorization = what you are allowed to do, authentication = proving who you are, accounting = recording what you did, identification = the identity claim itself."},
  {"id":"q021","domain":"D1","family":"zero-trust","question":"In a zero trust deployment, an access request arrives carrying the user's identity, device health report, and location. One component weighs all of this against policy and renders the actual grant-or-deny decision. Which component is it?","options":["Policy Engine","Policy Administrator","Policy Enforcement Point","control plane"],"correctIndex":0,"explanation":"Policy Engine. It is the brain that evaluates the request against policy and decides. The tell: Policy Engine = makes the grant/deny decision, Policy Administrator = generates/relays the access token, Policy Enforcement Point = the gate that opens or blocks the session, control plane = the whole decision-making layer they live in."},
  {"id":"q022","domain":"D1","family":"zero-trust","question":"A zero trust gateway sits directly in the connection path and either opens or drops each user session depending on the token it receives from the control plane. Which zero trust component is this gateway?","options":["Policy Administrator","Policy Engine","Policy Enforcement Point","data plane"],"correctIndex":2,"explanation":"Policy Enforcement Point. It is the gate in the traffic path that actually allows or blocks the session; it does not make the decision itself. The tell: Policy Enforcement Point = enforces, Policy Engine = decides, Policy Administrator = relays the token, data plane = where the traffic flows."},
  {"id":"q023","domain":"D1","family":"zero-trust","question":"In a zero trust architecture, which component takes the Policy Engine's decision, then generates and relays the session token that instructs the enforcement point to permit the connection?","options":["Policy Enforcement Point","Policy Administrator","Policy Engine","threat scope reduction"],"correctIndex":1,"explanation":"Policy Administrator. It is the messenger between decision and enforcement: it issues the token or credential the PEP acts on. The tell: Policy Administrator = generates/relays the token, Policy Engine = makes the decision, Policy Enforcement Point = enforces it, threat scope reduction = the zero trust goal of shrinking what any one subject can reach."},
  {"id":"q024","domain":"D1","family":"zero-trust","question":"A zero trust architect is labeling a network diagram. One area contains the components that make and manage access decisions; a separate area carries the subjects' actual application traffic. What is the decision-making area called?","options":["data plane","adaptive identity","implicit trust zones","control plane"],"correctIndex":3,"explanation":"Control plane. Policy decisions live in the control plane, kept separate from the data plane where subject traffic flows. The tell: control plane = where policy decisions live, data plane = where traffic flows, adaptive identity = risk-based identity validation, implicit trust zones = the legacy assumption zero trust removes."},
  {"id":"q025","domain":"D1","family":"zero-trust","question":"In zero trust vocabulary, which term names the layer where the subject's actual application traffic and sessions flow, as opposed to the separate layer where access decisions are made and managed?","options":["control plane","Policy Engine","Policy Administrator","data plane"],"correctIndex":3,"explanation":"Data plane. Traffic flows in the data plane; decisions happen in the control plane. The tell: data plane = where the subject's traffic actually flows, control plane = where policy decisions live, Policy Engine = the decision maker inside the control plane, Policy Administrator = relays the token."},
  {"id":"q026","domain":"D1","family":"zero-trust","question":"When a user connects from an unfamiliar country on an unmanaged device, the zero trust system automatically demands stronger authentication than it does for the same user at their usual desk. Which zero trust concept is this?","options":["threat scope reduction","implicit trust zones","adaptive identity","policy-driven access control"],"correctIndex":2,"explanation":"Adaptive identity. Identity validation that tightens or relaxes based on context and risk signals is adaptive identity. The tell: adaptive identity = risk-based, context-aware identity checks, threat scope reduction = shrinking what any subject can reach, policy-driven access control = rules deciding access, implicit trust zones = the legacy trust-by-location model zero trust eliminates."},
  {"id":"q027","domain":"D1","family":"zero-trust","question":"A zero trust program limits every user to the minimal set of resources their job requires, so a compromised account exposes as little of the environment as possible. Which zero trust concept does this describe?","options":["threat scope reduction","adaptive identity","control plane","Policy Enforcement Point"],"correctIndex":0,"explanation":"Threat scope reduction. Minimizing what any one subject can reach shrinks the blast radius of a compromise. The tell: threat scope reduction = shrink what an account can reach, adaptive identity = context-aware authentication, control plane = where decisions live, Policy Enforcement Point = the gate enforcing them."},
  {"id":"q028","domain":"D1","family":"physical-security","question":"After a smash-and-grab at a neighboring office, a data center wants to stop a vehicle from being driven through its glass lobby entrance while keeping the walkway fully open to pedestrians. Which physical control BEST meets both requirements?","options":["bollards","fencing","access control vestibule","video surveillance"],"correctIndex":0,"explanation":"Bollards. Short heavy posts stop vehicles but let people walk between them, which is exactly the stated constraint. Fencing blocks pedestrians too, a vestibule controls a doorway not a vehicle, and cameras only record the crash. The tell: bollards = stop vehicles, fencing = perimeter barrier for people, access control vestibule = one-person-at-a-time entry, video surveillance = detects/deters but stops nothing."},
  {"id":"q029","domain":"D1","family":"physical-security","question":"A badge audit shows more people entering the server room than badge swipes recorded, because staff hold the door open for whoever is behind them. The facility installs a double-door enclosure that authenticates and admits exactly one person at a time. Which control is this?","options":["security guard","access badge","access control vestibule","bollards"],"correctIndex":2,"explanation":"Access control vestibule. The double-door, one-person-per-authentication design exists specifically to stop piggybacking through a held door. The tell: access control vestibule = one-person-at-a-time double door, security guard = human verification, access badge = the credential itself, bollards = stop vehicles."},
  {"id":"q030","domain":"D1","family":"physical-security","question":"A warehouse alarm triggers at night when a sensor detects the body heat of an intruder moving through an unlit aisle. Which sensor type detected the intruder?","options":["pressure sensor","infrared sensor","microwave sensor","ultrasonic sensor"],"correctIndex":1,"explanation":"Infrared sensor. Detecting emitted body heat is the infrared signature. The tell: infrared = detects heat/body, pressure = detects weight/step, microwave and ultrasonic = detect motion via reflected waves, not heat."},
  {"id":"q031","domain":"D1","family":"physical-security","question":"After a theft at the loading dock, investigators pull last week's recorded footage to establish who entered and when. Which physical security control made this investigation possible?","options":["lighting","security guard","video surveillance","access badge"],"correctIndex":2,"explanation":"Video surveillance. Recorded cameras provide the after-the-fact evidence trail investigators reviewed, a classic detective use of a physical control. The tell: video surveillance = record and review events, lighting = deters and aids visibility, security guard = live human control, access badge = the entry credential."},
  {"id":"q032","domain":"D1","family":"deception","question":"A security engineer plants a fake set of database credentials in a configuration file on a web server. The credentials grant no real access, but any attempt to use them anywhere fires a high-priority alert. Which deception technique is this?","options":["honeypot","honeyfile","honeytoken","honeynet"],"correctIndex":2,"explanation":"Honeytoken. Bait credentials or records that alert when used are honeytokens; the config file is just the delivery spot. A honeyfile would be the bait file itself being opened, not a credential being replayed. The tell: honeytoken = bait credential/record that fires on use, honeyfile = bait file, honeypot = one decoy system, honeynet = a whole decoy network."},
  {"id":"q033","domain":"D1","family":"deception","question":"Instead of a single decoy host, a threat research team builds an entire simulated environment - fake servers, workstations, and generated traffic - to attract intruders and study their tools over weeks. Which deception technology is this?","options":["honeynet","honeypot","honeyfile","honeytoken"],"correctIndex":0,"explanation":"Honeynet. A whole network of decoys is a honeynet; one decoy system alone would be a honeypot. The tell: honeynet = a whole decoy network, honeypot = one decoy system, honeyfile = a bait file, honeytoken = a bait credential/record."},
  {"id":"q034","domain":"D1","family":"deception","question":"Security engineers stand up a single intentionally vulnerable decoy server on an internet-facing segment purely to attract attackers and record their techniques. Which deception technology is this?","options":["honeypot","honeynet","honeyfile","honeytoken"],"correctIndex":0,"explanation":"Honeypot. One decoy system built to lure and observe attackers is a honeypot; it would take a whole decoy network to be a honeynet. The tell: honeypot = one decoy system, honeynet = a whole decoy network, honeyfile = a bait file, honeytoken = a bait credential/record."},
  {"id":"q035","domain":"D1","family":"deception","question":"A team plants a spreadsheet named passwords.xlsx on a file share. It contains nothing real, but any attempt to open or copy it triggers an alert because no legitimate user has a reason to touch it. Which deception technique is this?","options":["honeynet","honeytoken","honeyfile","honeypot"],"correctIndex":2,"explanation":"Honeyfile. A bait file whose access fires an alert is a honeyfile. If the bait were a fake credential being used elsewhere, that would be a honeytoken. The tell: honeyfile = bait file, honeytoken = bait credential/record, honeypot = one decoy system, honeynet = a decoy network."},
  {"id":"q036","domain":"D1","family":"change-management","question":"A change ticket for a core-switch firmware upgrade includes a section listing the exact commands to reload the previous firmware image if post-upgrade validation fails. Which change management element is this section?","options":["impact analysis","backout plan","maintenance window","test results"],"correctIndex":1,"explanation":"Backout plan. Documented steps to undo a change and return to the last known-good state are the backout plan. The tell: backout plan = how to undo, impact analysis = what could break, maintenance window = the approved time slot, test results = evidence it worked in staging."},
  {"id":"q037","domain":"D1","family":"change-management","question":"A change advisory board approves a disruptive database migration but requires it to run between 1:00 a.m. and 5:00 a.m. Sunday, when the fewest users are connected. Which change management element is this time slot?","options":["impact analysis","approval process","backout plan","maintenance window"],"correctIndex":3,"explanation":"Maintenance window. The pre-approved low-impact period in which the change may be executed is the maintenance window. The tell: maintenance window = approved time to make the change, approval process = the sign-off itself, impact analysis = what could break, backout plan = how to undo."},
  {"id":"q038","domain":"D1","family":"change-management","question":"Before approving a database schema change, the review board requires a written assessment of every downstream system that could break, including the reporting jobs and the mobile app. Which change management element is this assessment?","options":["backout plan","impact analysis","test results","maintenance window"],"correctIndex":1,"explanation":"Impact analysis. Documenting what could break and how badly is the impact analysis, done before approval. The tell: impact analysis = what could break, backout plan = how to undo, test results = evidence from staging, maintenance window = the approved time slot."},
  {"id":"q039","domain":"D1","family":"change-management","question":"A network team stores every revision of its firewall configuration in a repository, so any change can be attributed, compared, and rolled back to an earlier version. Which change management practice is this?","options":["version control","standard operating procedure","approval process","impact analysis"],"correctIndex":0,"explanation":"Version control. Tracking revisions of configs or code with history and rollback is version control. The tell: version control = track revisions over time, standard operating procedure = the documented repeatable process, approval process = the sign-off gate, impact analysis = what could break."},
  {"id":"q040","domain":"D1","family":"crypto-key-handling","question":"A fleet of corporate laptops uses full-disk encryption. Each laptop seals its disk-encryption key inside a dedicated cryptographic chip soldered to its own motherboard, which also validates boot integrity before releasing the key. Which component is being used?","options":["TPM","HSM","secure enclave","key management system"],"correctIndex":0,"explanation":"TPM. A per-device crypto chip on the motherboard handling boot integrity and the disk key is the Trusted Platform Module. The tell: TPM = crypto chip built into ONE endpoint's motherboard, HSM = dedicated appliance serving keys to many systems, secure enclave = isolated region on the CPU itself, key management system = software key-lifecycle service."},
  {"id":"q041","domain":"D1","family":"crypto-key-handling","question":"A payment processor must generate, store, and use thousands of signing keys inside tamper-resistant dedicated hardware that serves an entire rack of application servers at high transaction rates. Which solution fits the requirement?","options":["TPM","key escrow","HSM","secure enclave"],"correctIndex":2,"explanation":"HSM. Scale (thousands of keys, many servers) plus tamper-resistant dedicated hardware points to a hardware security module appliance. A TPM serves only its own device. The tell: HSM = appliance generating/storing keys for many systems, TPM = one endpoint's chip, key escrow = third party holds key copies, secure enclave = isolated CPU region."},
  {"id":"q042","domain":"D1","family":"crypto-key-handling","question":"To satisfy a regulatory requirement, a company deposits copies of its data-encryption keys with a bonded third party so the data can still be recovered if the keys are lost or a court compels access. Which arrangement is this?","options":["key escrow","key management system","HSM","TPM"],"correctIndex":0,"explanation":"Key escrow. A third party holding key copies for recovery or lawful access is the defining trait of escrow; no hardware is implied at all. The tell: key escrow = third party holds a copy, key management system = software lifecycle service you run, HSM = your own hardware appliance, TPM = one endpoint's chip."},
  {"id":"q043","domain":"D1","family":"crypto-key-handling","question":"A smartphone maker stores fingerprint templates and payment keys in an isolated coprocessor region that the main operating system cannot read, so the secrets survive even if the phone is rooted. Which component is this?","options":["TPM","secure enclave","HSM","key escrow"],"correctIndex":1,"explanation":"Secure enclave. An isolated region on the device's own processor protecting keys and biometrics is a secure enclave, typical of phones. The tell: secure enclave = isolated coprocessor region on the CPU/phone, TPM = separate chip on a PC motherboard, HSM = external appliance for many systems, key escrow = third party holds keys."},
  {"id":"q044","domain":"D1","family":"crypto-key-handling","question":"A DevOps team needs a single software service that creates, distributes, rotates, and revokes the encryption keys used by dozens of microservices, with the full lifecycle automated through an API. Which solution BEST fits?","options":["HSM","TPM","secure enclave","key management system"],"correctIndex":3,"explanation":"Key management system. Lifecycle operations (create, rotate, revoke) delivered as a software service define a KMS; it may use an HSM underneath, but the requirement here is the management layer. The tell: key management system = software key-lifecycle service, HSM = the hardware that stores keys, TPM = one endpoint's chip, secure enclave = isolated CPU region."},
  {"id":"q045","domain":"D1","family":"crypto-key-handling","question":"An architect comparing two options notes that the first is built into each individual endpoint and protects only that device's own disk key, while the second is a networked appliance serving keys to many servers. Which term matches the first, per-endpoint option?","options":["HSM","TPM","key management system","key escrow"],"correctIndex":1,"explanation":"TPM. Built into one endpoint for that device's keys = TPM; the networked appliance described second is the HSM. This one-versus-many split is the classic TPM/HSM discriminator. The tell: TPM = one device's motherboard chip, HSM = shared appliance at scale, key management system = software lifecycle layer, key escrow = third party holds copies."},
  {"id":"q046","domain":"D1","family":"crypto-key-handling","question":"An employee is terminated, and the legal team must lawfully decrypt project files that were protected with the employee's own encryption key. The organization retrieves a copy of the key that was stored for exactly this situation. Which arrangement made that possible?","options":["HSM","secure enclave","key escrow","TPM"],"correctIndex":2,"explanation":"Key escrow. Recovering a departed user's key from a held copy is the escrow use case: a trusted party keeps key copies for recovery or legal access. The tell: key escrow = held copy for recovery/legal access, HSM = hardware appliance serving live keys, secure enclave = isolated CPU region, TPM = one endpoint's chip."},
  {"id":"q047","domain":"D1","family":"crypto-key-handling","question":"Which term describes a dedicated, tamper-resistant hardware appliance that generates and stores cryptographic keys and offloads crypto operations for many systems at once?","options":["TPM","secure enclave","key escrow","HSM"],"correctIndex":3,"explanation":"HSM. Dedicated appliance, tamper-resistant, many systems: that is the hardware security module. The tell: HSM = appliance for keys at scale, TPM = chip on ONE endpoint's motherboard, secure enclave = isolated region inside a CPU, key escrow = a third party holding key copies."},
  {"id":"q048","domain":"D1","family":"crypto-key-handling","question":"Which component is an isolated region inside a device's main processor that keeps keys and biometric data protected even when the operating system itself is fully compromised?","options":["key management system","secure enclave","TPM","HSM"],"correctIndex":1,"explanation":"Secure enclave. It lives inside the main CPU and stays isolated from the OS, unlike a TPM, which is its own separate chip on the board. The tell: secure enclave = isolated region on the CPU, TPM = discrete motherboard chip, HSM = external appliance, key management system = software lifecycle service."},
  {"id":"q049","domain":"D1","family":"crypto-key-handling","question":"A security policy requires every application encryption key to rotate automatically every 90 days and to be revocable within minutes of a compromise report, all administered through one software service. Which solution provides this?","options":["key escrow","HSM","TPM","key management system"],"correctIndex":3,"explanation":"Key management system. Automated rotation and revocation are lifecycle functions, which is the KMS's job description. Hardware options store keys but do not manage schedules. The tell: key management system = create/rotate/revoke lifecycle, HSM = hardware vault at scale, TPM = one endpoint's chip, key escrow = third-party copy for recovery."},
  {"id":"q050","domain":"D1","family":"crypto-key-handling","question":"BitLocker on a corporate desktop seals the drive's encryption key to a chip on the motherboard, and the drive unlocks only when boot measurements show the machine started in its known-good state. Which component is this?","options":["HSM","secure enclave","key management system","TPM"],"correctIndex":3,"explanation":"TPM. Sealing a disk key to boot measurements on the device's own motherboard chip is the Trusted Platform Module's signature job. The tell: TPM = one endpoint's motherboard chip (boot integrity, disk key), HSM = shared appliance for many systems, secure enclave = isolated CPU region, key management system = software lifecycle service."},
  {"id":"q051","domain":"D1","family":"crypto-key-handling","question":"Which component is a dedicated cryptographic chip on a single device's motherboard that stores platform measurements so the system can attest it booted without tampering?","options":["key escrow","TPM","HSM","key management system"],"correctIndex":1,"explanation":"TPM. Per-device chip plus boot attestation equals TPM. The tell: TPM = one endpoint's chip with platform measurements, HSM = external appliance serving many systems, key escrow = third party holds key copies, key management system = software key-lifecycle service."},
  {"id":"q052","domain":"D1","family":"crypto-key-handling","question":"A certificate authority keeps its root signing key inside a FIPS-validated hardware appliance; certificates are signed inside the device and the key never leaves it. Which component is this?","options":["HSM","TPM","key escrow","secure enclave"],"correctIndex":0,"explanation":"HSM. A dedicated, certified appliance performing signing operations internally so the key never leaves is a hardware security module, the standard way CAs guard root keys. The tell: HSM = dedicated appliance, keys used inside it, TPM = one endpoint's chip, key escrow = third party holds copies, secure enclave = isolated CPU region."},
  {"id":"q053","domain":"D1","family":"crypto-key-handling","question":"An enterprise needs to generate and protect keys centrally for hundreds of servers rather than securing any single machine's boot process. Which component fits this scale, as opposed to a per-machine motherboard chip?","options":["TPM","secure enclave","HSM","key management system"],"correctIndex":2,"explanation":"HSM. Central hardware key protection for many systems is the HSM's role; the per-machine chip being contrasted is the TPM. The tell: HSM = keys at scale for many systems, TPM = one device's chip, secure enclave = isolated region on one CPU, key management system = the software lifecycle layer, not the hardware."},
  {"id":"q054","domain":"D1","family":"crypto-key-handling","question":"A firm fears its encrypted archives will become unrecoverable if the master key is ever destroyed, so it arranges for a bonded third party to hold a recovery copy. Which arrangement is this?","options":["HSM","key management system","TPM","key escrow"],"correctIndex":3,"explanation":"Key escrow. A third party holding a key copy against loss or lawful demand is escrow; nothing here is about hardware or lifecycle automation. The tell: key escrow = third party holds a copy for recovery/legal access, HSM = your own hardware vault, TPM = one endpoint's chip, key management system = software lifecycle service."},
  {"id":"q055","domain":"D1","family":"crypto-key-handling","question":"Which term specifically means a third party holds a copy of your keys for later recovery or lawful access, rather than a hardware appliance that generates and guards keys in active production use?","options":["HSM","key escrow","secure enclave","TPM"],"correctIndex":1,"explanation":"Key escrow. The discriminator is who holds it and why: a copy held elsewhere for recovery = escrow; hardware guarding live keys = HSM. The tell: key escrow = held copy, recovery/legal access, HSM = active hardware vault at scale, secure enclave = isolated CPU region, TPM = one endpoint's chip."},
  {"id":"q056","domain":"D1","family":"crypto-key-handling","question":"A cloud team wants one central service that controls which applications may use each key, writes an audit log of every key use, and automates rotation and revocation across all services. Which solution is this?","options":["key management system","HSM","key escrow","TPM"],"correctIndex":0,"explanation":"Key management system. Per-application permissions, usage auditing, and lifecycle automation are management-layer functions, so this is a KMS even if an HSM sits underneath. The tell: key management system = software lifecycle and access control for keys, HSM = the hardware that stores/uses them, key escrow = third-party copy, TPM = one endpoint's chip."},
  {"id":"q057","domain":"D1","family":"crypto-key-handling","question":"In a bank's architecture review, one option orchestrates create, rotate, and revoke operations across many applications in software, while a separate hardware device actually performs the cryptographic operations. Which term names the orchestration option?","options":["HSM","TPM","key management system","secure enclave"],"correctIndex":2,"explanation":"Key management system. The KMS is the software brain managing the key lifecycle; the hardware doing the crypto is the HSM. The tell: key management system = software orchestration of the key lifecycle, HSM = hardware performing the crypto, TPM = one endpoint's chip, secure enclave = isolated CPU region."},
  {"id":"q058","domain":"D1","family":"crypto-key-handling","question":"On a modern smartphone, payment credentials and the keys protecting them live in a hardware region isolated from the main processor and operating system, so even on-device malware cannot extract them. Which component is this?","options":["TPM","HSM","key management system","secure enclave"],"correctIndex":3,"explanation":"Secure enclave. An isolated on-die region protecting keys and payment data on a phone is the secure enclave. The tell: secure enclave = isolated coprocessor region on the CPU/phone, TPM = discrete chip on a PC motherboard, HSM = external appliance, key management system = software service."},
  {"id":"q059","domain":"D1","family":"crypto-key-handling","question":"A payment processor needs a certified, tamper-responsive hardware module that generates keys and performs PIN encryption, and that zeroizes its keys the moment its case is opened. Which component is this?","options":["TPM","HSM","secure enclave","key escrow"],"correctIndex":1,"explanation":"HSM. Certified tamper response with key zeroization for payment operations is classic HSM territory. The tell: HSM = tamper-resistant appliance for keys at scale, TPM = one endpoint's chip, secure enclave = isolated CPU region, key escrow = a third party holding copies."},
  {"id":"q060","domain":"D1","family":"crypto-methods","question":"During a password audit, an engineer notices that two users who chose the identical password have completely different stored hashes, because a unique random value is combined with each password before hashing. Which technique causes this?","options":["hashing","salting","key stretching","symmetric encryption"],"correctIndex":1,"explanation":"Salting. A unique per-password random value makes identical passwords hash differently and defeats rainbow tables. The tell: salting = random per-password value before hashing, key stretching = many iterations to slow guessing, hashing = the one-way function itself, symmetric encryption = reversible with a shared key."},
  {"id":"q061","domain":"D1","family":"crypto-methods","question":"A developer configures bcrypt with a high work factor so that verifying one password takes a fraction of a second but brute forcing millions of guesses becomes computationally impractical. Which technique is this?","options":["salting","hashing","key exchange","key stretching"],"correctIndex":3,"explanation":"Key stretching. Deliberately expensive, iterated hashing (bcrypt, PBKDF2) exists to make each guess costly. Salting defeats precomputation but adds no compute cost. The tell: key stretching = make each guess expensive, salting = unique random value per password, hashing = one-way fingerprint, key exchange = agreeing on a shared secret."},
  {"id":"q062","domain":"D1","family":"crypto-methods","question":"Two servers need to agree on a shared session secret across an untrusted network without the secret ever being transmitted, so they perform a Diffie-Hellman negotiation. What is this process called?","options":["key exchange","asymmetric encryption","symmetric encryption","hashing"],"correctIndex":0,"explanation":"Key exchange. Diffie-Hellman lets both sides derive the same secret without sending it, which is the definition of key exchange. The tell: key exchange = safely agree on a shared key, asymmetric = public/private pair operations, symmetric = using the one shared key for bulk data, hashing = one-way integrity fingerprint."},
  {"id":"q063","domain":"D1","family":"crypto-methods","question":"A site-to-site VPN encrypts a multi-gigabyte nightly transfer quickly using one shared secret key that both endpoints already hold. Which cryptographic method is doing the bulk encryption?","options":["asymmetric encryption","symmetric encryption","key exchange","hashing"],"correctIndex":1,"explanation":"Symmetric encryption. One shared key and high speed for bulk data are the symmetric signature; asymmetric is too slow for the payload and is used to set up the key instead. The tell: symmetric = one shared key, fast, bulk data, asymmetric = key pair, slower, exchange and signatures, key exchange = agreeing on the key, hashing = one-way fingerprint."},
  {"id":"q064","domain":"D1","family":"crypto-methods","question":"A secure email system gives each user a key pair: anyone can encrypt a message to the user with one key, but only the user's other, secret key can decrypt it. Which cryptographic method is this?","options":["asymmetric encryption","symmetric encryption","salting","key stretching"],"correctIndex":0,"explanation":"Asymmetric encryption. A public/private key pair where the public key encrypts and only the private key decrypts is asymmetric cryptography. The tell: asymmetric = public/private pair, symmetric = one shared key for both directions, salting = random value added to passwords, key stretching = making password guesses expensive."},
  {"id":"q065","domain":"D1","family":"pki-signatures","question":"An analyst must email a confidential report so that only the intended recipient can open it. Under public key cryptography, which key should the analyst use to encrypt the file?","options":["the recipient's public key","the recipient's private key","the sender's public key","the sender's private key"],"correctIndex":0,"explanation":"The recipient's public key. Only the matching private key, held by the recipient alone, can decrypt it, which delivers confidentiality. The tell: encrypt for secrecy = recipient's PUBLIC key, sign for proof of origin = sender's PRIVATE key. Sender keys prove identity, recipient keys protect delivery."},
  {"id":"q066","domain":"D1","family":"pki-signatures","question":"Maria must prove to business partners that a price list really came from her and was not altered in transit, so she digitally signs it before sending. Which key creates the signature?","options":["the sender's public key","the sender's private key","the recipient's public key","the recipient's private key"],"correctIndex":1,"explanation":"The sender's private key. Signing means encrypting the document hash with her own private key so anyone can verify with her public key, giving integrity plus non-repudiation. The tell: sign = sender's PRIVATE key, verify = sender's public key, encrypt for secrecy = recipient's public key."},
  {"id":"q067","domain":"D1","family":"pki-signatures","question":"Which technology stores transactions in blocks, where each block contains a hash of the previous one, so that altering any historical record invalidates every block that follows?","options":["open public ledger","digital signature","blockchain","hashing"],"correctIndex":2,"explanation":"Blockchain. Chained, hashed blocks are the structure itself; the open public ledger is the visible record built on top of it, and hashing is just the primitive used. The tell: blockchain = chained hashed blocks, open public ledger = the publicly viewable transaction record, digital signature = signed hash proving origin, hashing = one-way fingerprint."},
  {"id":"q068","domain":"D1","family":"pki-signatures","question":"A hash of a message is computed and then encrypted with the sender's private key, letting any recipient verify both that the message is unaltered and who sent it. What is this construct called?","options":["blockchain","hashing","open public ledger","digital signature"],"correctIndex":3,"explanation":"Digital signature. Hash plus sender's-private-key encryption is the definition, and it yields integrity plus non-repudiation. The tell: digital signature = encrypted hash proving origin and integrity, hashing = the fingerprint alone, blockchain = chained hashed blocks, open public ledger = the public transaction record."},
  {"id":"q069","domain":"D1","family":"pki-signatures","question":"A recipient wants to verify that a digitally signed purchase order really came from Raj and was not modified. Which key does the recipient use to check the signature?","options":["Raj's private key","Raj's public key","the recipient's private key","the recipient's public key"],"correctIndex":1,"explanation":"Raj's public key. Raj signed with his private key, so anyone verifies with his public key; if it validates, only Raj's private key could have made it. The tell: sign = sender's private key, verify = sender's public key, encrypt for secrecy = recipient's public key, decrypt = recipient's private key."},
  {"id":"q070","domain":"D1","family":"obfuscation","question":"A DLP investigation finds that an insider hid customer records inside the pixel data of ordinary-looking vacation photos before emailing them out; every image opens and displays normally. Which technique did the insider use?","options":["tokenization","data masking","encryption","steganography"],"correctIndex":3,"explanation":"Steganography. Hiding data inside innocent-looking media so no one suspects a payload exists is steganography; encryption would scramble the data but not disguise its presence. The tell: steganography = hide data inside other media, tokenization = swap value for a vault-mapped token, data masking = show only partial values, encryption = scrambled but visibly protected."},
  {"id":"q071","domain":"D1","family":"obfuscation","question":"A retailer's payment platform replaces each stored card number with a random surrogate value; the real number can be recovered only by querying a hardened vault service. Which technique is this?","options":["data masking","steganography","tokenization","encryption"],"correctIndex":2,"explanation":"Tokenization. A substitute value with a vault lookup back to the original is tokenization; masking is irreversible display hiding, and encryption transforms the value mathematically rather than replacing it. The tell: tokenization = token maps back via a vault, data masking = XXXX-1234 style partial display, steganography = hidden inside media, encryption = reversible with a key."},
  {"id":"q072","domain":"D1","family":"obfuscation","question":"A support portal shows an agent a customer's card number as XXXX-XXXX-XXXX-1234. The hidden digits are permanently obscured in the display layer and cannot be recovered from what the agent sees. Which technique is this?","options":["tokenization","data masking","steganography","encryption"],"correctIndex":1,"explanation":"Data masking. Showing only a partial value with the rest irrecoverably hidden is masking; tokenization would substitute a reversible vault-mapped value, and encryption is mathematically reversible with the key. The tell: data masking = partial/scrambled display, not reversible, tokenization = token maps back via a vault, steganography = hidden inside media, encryption = reversible with a key."},
  {"id":"q073","domain":"D1","family":"obfuscation","question":"An insider embeds a stolen price list inside the inaudible frequency ranges of an MP3 file and emails the song home, sailing past content inspection. Which technique is this?","options":["data masking","tokenization","steganography","encryption"],"correctIndex":2,"explanation":"Steganography. Concealing data inside carrier media (audio, images, video) so its existence is not suspected is steganography. The tell: steganography = hide data inside other media, data masking = partial display of a value, tokenization = vault-mapped substitute value, encryption = scrambled but visibly present."},
  {"id":"q074","domain":"D1","family":"encryption-levels","question":"A database administrator must encrypt only the individual rows holding VIP customers' data, so each of those entries is protected separately while the rest of the table remains readable by reporting jobs. Which encryption level is this?","options":["database","volume","file","record"],"correctIndex":3,"explanation":"Record. Encrypting individual rows/fields inside a table is record-level encryption, the finest granularity. Database-level would cover everything and break the readable-reporting requirement. The tell: record = single row/field, database = the whole database, file = individual files, volume = a logical volume."},
  {"id":"q075","domain":"D1","family":"encryption-levels","question":"Which encryption level protects an entire physical drive, including the operating system, swap space, and every file, and unlocks once at boot time?","options":["partition","volume","full-disk","file"],"correctIndex":2,"explanation":"Full-disk. The entire drive including OS and swap, unlocked at boot, is full-disk encryption. The tell: full-disk = the whole physical drive, partition = one partition of it, volume = a logical volume, file = individual files only."},
  {"id":"q076","domain":"D1","family":"encryption-levels","question":"A consultant encrypts three client contracts stored in a project folder but leaves the operating system and every other file on the laptop unencrypted. Which encryption level is the consultant using?","options":["full-disk encryption","volume encryption","database encryption","file-level encryption"],"correctIndex":3,"explanation":"File-level. Protecting individually chosen files while the rest of the disk stays readable is file-level encryption. The tell: file = individual files, full-disk = the entire drive including the OS, volume = a logical volume, database = an entire data store."},
  {"id":"q077","domain":"D1","family":"encryption-levels","question":"A company applies transparent encryption to its entire customer database, protecting the whole data store as one unit rather than selecting individual tables or rows. Which encryption level is this?","options":["record-level encryption","file-level encryption","database encryption","partition encryption"],"correctIndex":2,"explanation":"Database. Encrypting the whole database as a unit is database-level encryption; row-by-row protection would be record-level. The tell: database = the whole data store, record = a single row/field, file = individual files, partition = one disk partition."},
  {"id":"q078","domain":"D1","family":"certificates","question":"A browser must confirm in real time whether one specific server certificate has been revoked, without downloading the certificate authority's entire revocation list. Which mechanism does this?","options":["CRL","OCSP","CSR","wildcard"],"correctIndex":1,"explanation":"OCSP. The Online Certificate Status Protocol queries the status of a single certificate in real time. The tell: OCSP = live per-certificate revocation check, CRL = downloaded batch list that can be stale, CSR = the request sent to get a cert, wildcard = one cert covering all subdomains."},
  {"id":"q079","domain":"D1","family":"certificates","question":"An administrator wants a single certificate that secures mail.example.com, shop.example.com, and any subdomain the company adds later. Which certificate type fits?","options":["wildcard","self-signed","root of trust","CRL"],"correctIndex":0,"explanation":"Wildcard. A *.example.com certificate covers every current and future subdomain at that level. The tell: wildcard = covers *.domain subdomains, self-signed = no external CA vouches for it, root of trust = the anchor CA of the chain, CRL = revocation list."},
  {"id":"q080","domain":"D1","family":"certificates","question":"Which artifact does an administrator generate on a server - containing its public key and identifying details - and then submit to a certificate authority in order to receive a signed certificate?","options":["CRL","OCSP","CSR","root of trust"],"correctIndex":2,"explanation":"CSR. The certificate signing request packages the public key and identity information for the CA to sign. The tell: CSR = the request you send to a CA, CRL = list of revoked certs, OCSP = live revocation lookup, root of trust = the anchor the chain terminates at."},
  {"id":"q081","domain":"D1","family":"certificates","question":"A client downloads the certificate authority's published list of revoked certificates once every 24 hours, so a certificate revoked this morning may still be trusted this afternoon. Which mechanism is described?","options":["OCSP","CSR","wildcard","CRL"],"correctIndex":3,"explanation":"CRL. A periodically downloaded batch list of revoked certificates is the certificate revocation list, and its staleness window is its classic weakness versus OCSP. The tell: CRL = downloaded list, possibly stale, OCSP = real-time single-cert check, CSR = request for a new cert, wildcard = covers subdomains."},
  {"id":"q082","domain":"D1","family":"certificates","question":"A developer generates a certificate for an internal test server and signs it with the server's own key. Browsers connecting to it warn users because no external authority vouches for the certificate. Which certificate type is this?","options":["self-signed certificate","wildcard certificate","third-party certificate","root of trust"],"correctIndex":0,"explanation":"Self-signed. Signed by its own subject with no CA in the chain, so clients have no reason to trust it and warn. The tell: self-signed = you vouch for yourself, third-party = a trusted CA vouches, wildcard = covers *.domain subdomains, root of trust = the anchor CA in a chain."},
  {"id":"q083","domain":"D1","family":"certificates","question":"In a certificate chain presented by a web server, which element is the anchor certificate authority that the chain ultimately terminates at and that client devices inherently trust out of the box?","options":["certificate signing request","root of trust","OCSP","wildcard certificate"],"correctIndex":1,"explanation":"Root of trust. Chains validate upward until they reach a pre-trusted anchor CA, the root of trust. The tell: root of trust = the anchor the chain ends at, certificate signing request = the request for a new cert, OCSP = live revocation check, wildcard = covers subdomains."},
  {"id":"q084","domain":"D1","family":"certificates","question":"Which entity is responsible for validating a requester's identity and then issuing the signed digital certificate that browsers and other clients will trust?","options":["certificate signing request","certificate revocation list","root of trust","certificate authority"],"correctIndex":3,"explanation":"Certificate authority. The CA verifies identity and issues signed certificates; the CSR is what it receives, and the CRL is what it publishes when certs are revoked. The tell: certificate authority = verifies and issues, certificate signing request = the application for a cert, certificate revocation list = the published revocation list, root of trust = the anchor CA position in a chain."},
  {"id":"q085","domain":"D2","family":"threat-actors","question":"A loosely organized group defaces a city government's website and posts manifestos protesting a new surveillance ordinance. They demand no money and publicize the breach themselves. Which threat actor BEST fits?","options":["hacktivist","nation-state actor","organized crime","insider threat"],"correctIndex":0,"explanation":"Hacktivist. A political or philosophical message with publicity as the goal, and no profit motive, is the hacktivist profile. The tell: hacktivist = philosophical/political message, nation-state = espionage with deep resources, organized crime = financial gain, insider threat = trusted internal person."},
  {"id":"q086","domain":"D2","family":"threat-actors","question":"A security briefing describes an adversary with deep funding, custom tooling, multi-year persistence inside targets, and an espionage mission carried out on behalf of a foreign government. Which threat actor is described?","options":["organized crime","nation-state actor","hacktivist","unskilled attacker"],"correctIndex":1,"explanation":"Nation-state actor. Resources, patience, and espionage on a government's behalf define the nation-state or APT profile. The tell: nation-state = highly resourced espionage/war, organized crime = financial gain, hacktivist = political message, unskilled attacker = low skill using others' tools."},
  {"id":"q087","domain":"D2","family":"threat-actors","question":"An audit discovers the marketing team has been running an unapproved cloud database full of customer data for a year. They set it up to move faster and never told IT, though they meant no harm. Which category fits?","options":["insider threat","unskilled attacker","shadow IT","organized crime"],"correctIndex":2,"explanation":"Shadow IT. Unsanctioned internal technology deployed without IT's knowledge, but without malicious intent, is shadow IT. A malicious trusted employee would be an insider threat. The tell: shadow IT = unsanctioned internal tech, no malice, insider threat = trusted person acting against the org, unskilled attacker = script-using outsider, organized crime = profit-driven group."},
  {"id":"q088","domain":"D2","family":"threat-actors","question":"A well-funded criminal syndicate runs ransomware campaigns against hospital networks, negotiates payouts through professional \"support\" channels, and reinvests profits in better tooling. Which threat actor is this?","options":["hacktivist","unskilled attacker","nation-state","organized crime"],"correctIndex":3,"explanation":"Organized crime. Professionalized operations aimed purely at financial gain define the organized-crime actor. The tell: organized crime = financial gain, nation-state = espionage/war with government backing, hacktivist = political message, unskilled attacker = low-skill script user."},
  {"id":"q089","domain":"D2","family":"threat-actors","question":"A systems administrator passed over for promotion begins quietly copying customer databases to personal storage using the legitimate access his role grants him. Which threat actor category fits BEST?","options":["shadow IT","unskilled attacker","insider threat","organized crime"],"correctIndex":2,"explanation":"Insider threat. A trusted internal person abusing legitimate access, whether for revenge, profit, or ideology, is the insider threat. Shadow IT is unsanctioned tech without malicious intent. The tell: insider threat = trusted person acting against the org, shadow IT = unapproved tech, no malice, unskilled attacker = outsider with borrowed tools, organized crime = external profit-driven group."},
  {"id":"q090","domain":"D2","family":"threat-actors","question":"A teenager downloads an attack tool from a hacking forum and points it at a school's website without understanding how the tool works, defacing the homepage for bragging rights. Which threat actor is this?","options":["nation-state actor","organized crime","insider threat","unskilled attacker"],"correctIndex":3,"explanation":"Unskilled attacker. Using someone else's tools with little understanding, for low-stakes motives, is the unskilled attacker (script kiddie) profile. The tell: unskilled attacker = borrowed tools, low skill, nation-state = elite resources and espionage, organized crime = professional profit operations, insider threat = trusted internal person."},
  {"id":"q091","domain":"D2","family":"threat-actors","question":"On his last day after being fired, a database administrator deletes the backup catalogs he once managed, purely to hurt the company that let him go. Which motivation drove this attack?","options":["espionage","revenge","financial gain","philosophical beliefs"],"correctIndex":1,"explanation":"Revenge. Sabotage by a wronged (ex-)insider to punish the organization is revenge-motivated. The tell: revenge = payback for a grievance, espionage = stealing secrets for an interested party, financial gain = money, philosophical = a cause or message."},
  {"id":"q092","domain":"D2","family":"threat-actors","question":"A group floods an oil company's website with traffic and defaces its investor page with climate slogans during the annual shareholder meeting. It asks for no payment. Which motivation BEST fits?","options":["blackmail","data exfiltration","philosophical/political beliefs","financial gain"],"correctIndex":2,"explanation":"Philosophical/political beliefs. Disruption paired with a cause message and no profit demand is ideological - the hacktivist motivation. The tell: philosophical/political = the message is the point, blackmail = pay or else, data exfiltration = stealing the data itself, financial gain = money as the goal."},
  {"id":"q093","domain":"D2","family":"threat-actors","question":"An auditor must classify two findings: engineers running an unapproved personal cloud drive for convenience, and a payroll clerk secretly selling employee records. Which statement classifies them correctly?","options":["Both are insider threats","The cloud drive is shadow IT; the clerk is an insider threat","The cloud drive is an insider threat; the clerk is shadow IT","Both are shadow IT"],"correctIndex":1,"explanation":"Shadow IT versus insider threat turns on intent. Unsanctioned tech for convenience is shadow IT; a trusted person deliberately acting against the organization is an insider threat. The tell: shadow IT = unapproved but not malicious, insider threat = trusted access used to harm."},
  {"id":"q094","domain":"D2","family":"social-eng-phish","question":"An employee receives a text message claiming to be from their bank: \"Unusual activity detected. Tap this link within 24 hours or your account will be locked.\" Which technique is this?","options":["phishing","vishing","spear phishing","smishing"],"correctIndex":3,"explanation":"Smishing. The delivery channel decides the name, and this arrived by SMS text. The tell: smishing = SMS text, phishing = email, vishing = voice call, spear phishing = targeted at a specific person regardless of polish."},
  {"id":"q095","domain":"D2","family":"social-eng-phish","question":"An attacker phones the help desk after hours, claims to be an executive boarding a flight, and pressures the agent into resetting the executive's password on the spot. Which technique is this?","options":["vishing","smishing","phishing","spear phishing"],"correctIndex":0,"explanation":"Vishing. Social engineering delivered over a voice call is vishing, whatever story the caller uses. The tell: vishing = voice call, smishing = SMS, phishing = email, spear phishing = aimed at one specific target."},
  {"id":"q096","domain":"D2","family":"social-eng-phish","question":"A security team traces a credential theft campaign to a fraudulent email blast sent to roughly 40,000 random recipients, hoping a small percentage click and sign in to a fake portal. Which term describes this?","options":["smishing","phishing","vishing","spear phishing"],"correctIndex":1,"explanation":"Phishing. Broad, untargeted fraudulent email is plain phishing; had it been tailored to specific individuals it would be spear phishing. The tell: phishing = mass email, spear phishing = targeted email, vishing = voice, smishing = SMS."},
  {"id":"q097","domain":"D2","family":"social-eng-phish","question":"A finance clerk receives a phone call from someone claiming to be the company's bank fraud department, who walks her through \"verifying\" her online banking credentials over the call. Which social engineering technique is this?","options":["smishing","vishing","phishing","spear phishing"],"correctIndex":1,"explanation":"Vishing. The attack is delivered by voice call, which is the whole discriminator in this family. The tell: vishing = voice call, smishing = SMS text, phishing = email, spear phishing = tailored to one specific target."},
  {"id":"q098","domain":"D2","family":"social-eng-phish","question":"On the exam, classic phishing is defined by its delivery channel. Which channel is it?","options":["email","an SMS text message","a voice phone call","an instant-messaging app"],"correctIndex":0,"explanation":"Email. Phishing's home channel is email; the same con by text is smishing and by phone is vishing. The tell: phishing = email, smishing = SMS, vishing = voice. The channel names the crime."},
  {"id":"q099","domain":"D2","family":"social-eng-phish","question":"A company's CFO receives an email addressing her by name, referencing this quarter's real acquisition target, and linking to a \"revised term sheet\" that harvests her credentials. Only she received it. Which technique is this?","options":["phishing","smishing","spear phishing","vishing"],"correctIndex":2,"explanation":"Spear phishing. A tailored email aimed at one specific, researched target is spear phishing; a mass blast would be plain phishing. The tell: spear phishing = personalized, single target, phishing = broad and untargeted, vishing = voice call, smishing = SMS."},
  {"id":"q100","domain":"D2","family":"social-eng-phish","question":"A new SOC analyst is memorizing the phishing family. Which pairing of technique to delivery channel is correct?","options":["vishing = SMS, smishing = voice","phishing = email, vishing = voice, smishing = SMS","phishing = voice, vishing = email","smishing = email, phishing = SMS"],"correctIndex":1,"explanation":"Phishing = email, vishing = voice, smishing = SMS. The channel is the entire distinction in this family. The tell: v for voice, sm for SMS, and plain phishing keeps the original email channel."},
  {"id":"q101","domain":"D2","family":"social-eng-phish","question":"Every member of one company's engineering team receives an email referencing the internal codename of their current project and linking to a fake single sign-on page. No other company received it. Which technique is this?","options":["smishing","vishing","phishing","spear phishing"],"correctIndex":3,"explanation":"Spear phishing. Tailoring with insider details (the project codename) and targeting a specific group makes it spear phishing rather than a generic blast. The tell: spear phishing = researched and targeted, phishing = generic and mass, vishing/smishing = other channels entirely."},
  {"id":"q102","domain":"D2","family":"misinformation","question":"A well-meaning employee shares a two-year-old article about a product recall in the company chat, believing it is current news. The facts have long since changed, but the employee has no intent to mislead anyone. What is this?","options":["disinformation","malinformation","misinformation","influence campaign"],"correctIndex":2,"explanation":"Misinformation. False information passed along in honest error, with no intent to deceive, is misinformation. The tell: misinformation = false, no intent to deceive, disinformation = false and deliberately spread to deceive, influence campaign = coordinated effort to sway opinion at scale."},
  {"id":"q103","domain":"D2","family":"misinformation","question":"A fired executive knowingly fabricates stories about his former employer's finances and seeds them across investor forums under fake names, hoping to tank the stock before earnings. What is this?","options":["misinformation","malinformation","influence campaign","disinformation"],"correctIndex":3,"explanation":"Disinformation. The content is false AND deliberately created to deceive, which is the defining difference from misinformation. The tell: disinformation = deliberate deception, misinformation = honest error, influence campaign = organized perception-shaping operation, malinformation = true info weaponized out of context."},
  {"id":"q104","domain":"D2","family":"misinformation","question":"On the exam, which term specifically means false information circulated WITHOUT any intent to deceive - an honest mistake repeated in good faith?","options":["misinformation","disinformation","malinformation","influence campaign"],"correctIndex":0,"explanation":"Misinformation. Intent is the discriminator: none here. The tell: misinformation = false, spread innocently, disinformation = false, spread deliberately to manipulate, malinformation = genuine info used to harm, influence campaign = the coordinated umbrella operation."},
  {"id":"q105","domain":"D2","family":"misinformation","question":"Which term means false information created and spread deliberately to deceive or manipulate an audience?","options":["misinformation","malinformation","disinformation","influence campaign"],"correctIndex":2,"explanation":"Disinformation. Deliberate intent to deceive is the defining ingredient. The tell: disinformation = false and intentional, misinformation = false but innocent, malinformation = true info used maliciously, influence campaign = the coordinated operation that may use all three."},
  {"id":"q106","domain":"D2","family":"misinformation","question":"A company pays a click farm to plant fabricated one-star reviews, which it knows are untrue, to damage a competitor's product launch. What is this?","options":["influence campaign","disinformation","misinformation","malinformation"],"correctIndex":1,"explanation":"Disinformation. The reviews are false and deployed knowingly to deceive buyers. Coordinated at scale it could also be called an influence campaign, but the content itself is disinformation. The tell: disinformation = known-false content spread on purpose, misinformation = honest error, influence campaign = the broader coordinated push, malinformation = truth weaponized."},
  {"id":"q107","domain":"D2","family":"misinformation","question":"A security awareness trainer asks the class to distinguish misinformation from disinformation. Which statement is correct?","options":["Misinformation is spread without intent to deceive, while disinformation is spread deliberately to deceive.","Misinformation is deliberate, while disinformation is accidental.","Both always require intent to deceive.","Disinformation is only ever shared by mistake."],"correctIndex":0,"explanation":"Misinformation is innocent, disinformation is intentional. Intent to deceive is the only line between them. The tell: mis = mistake, dis = dishonest. Same false content, opposite intent."},
  {"id":"q108","domain":"D2","family":"misinformation","question":"Ahead of an election, a coordinated network of fake social media accounts mass-amplifies divisive stories - some true, some fabricated - to sway public opinion at scale. Which term BEST describes the overall operation?","options":["misinformation","influence campaign","malinformation","phishing"],"correctIndex":1,"explanation":"Influence campaign. The coordinated, large-scale operation to shape opinion is the influence campaign; misinformation and disinformation are the content types it spreads. The tell: influence campaign = the organized effort, disinformation/misinformation = the false content inside it, malinformation = true content weaponized."},
  {"id":"q109","domain":"D2","family":"misinformation","question":"A threat briefing tests the audience: which statement about disinformation is accurate?","options":["It is always spread by people who believe it is true","It is false information created and spread deliberately to deceive","It only exists on social media","It becomes misinformation once enough people share it"],"correctIndex":1,"explanation":"Disinformation is deliberate deception. Intent at creation defines it; the same false story innocently reshared by believers becomes misinformation in their hands, but the original deliberate act is disinformation. The tell: dis = deliberate, mis = mistaken."},
  {"id":"q110","domain":"D2","family":"impersonation","question":"The finance team receives an email from the CEO's real mailbox, which attackers quietly compromised, urgently requesting a wire transfer to a new vendor account before end of day. Which technique is this?","options":["impersonation","business email compromise (BEC)","pretexting","brand impersonation"],"correctIndex":1,"explanation":"Business email compromise. A compromised or spoofed internal executive mailbox used to request payments is BEC, the costliest form of this family. The tell: BEC = executive email account abused for wire/gift-card requests, impersonation = pretending to be someone in person or by phone, pretexting = the invented backstory, brand impersonation = faking a company's look to its customers."},
  {"id":"q111","domain":"D2","family":"impersonation","question":"A caller introduces herself as a newly assigned external auditor, cites a plausible compliance deadline, names the CFO, and uses this invented backstory to justify asking for access to financial records. Which technique is this?","options":["impersonation","brand impersonation","pretexting","business email compromise (BEC)"],"correctIndex":2,"explanation":"Pretexting. The engineered, believable scenario constructed to justify the request is the pretext; that fabricated context is what distinguishes it from simple impersonation. The tell: pretexting = invented backstory legitimizing the ask, impersonation = claiming to be someone, BEC = compromised executive mailbox, brand impersonation = faking a company's identity."},
  {"id":"q112","domain":"D2","family":"impersonation","question":"Customers of a national bank receive emails using the bank's exact logo, colors, and footer, linking to a pixel-perfect copy of its login page that harvests credentials. Which technique is this?","options":["impersonation","pretexting","business email compromise (BEC)","brand impersonation"],"correctIndex":3,"explanation":"Brand impersonation. Copying a trusted company's visual identity to fool that company's customers is brand impersonation. The tell: brand impersonation = fake the company's look to outsiders, BEC = abuse a real internal mailbox, impersonation = pose as an individual, pretexting = the cover story."},
  {"id":"q113","domain":"D2","family":"impersonation","question":"An attacker emails staff claiming to be \"Mike, the new IT technician,\" and asks them to install a remote-support tool. There is no elaborate backstory, no spoofed executive mailbox, and no faked corporate branding - just the false identity. Which technique is this?","options":["brand impersonation","pretexting","impersonation","business email compromise (BEC)"],"correctIndex":2,"explanation":"Impersonation. Simply posing as someone with a right to ask is impersonation; adding an engineered scenario would make it pretexting, and abusing a real executive mailbox would be BEC. The tell: impersonation = the false identity alone, pretexting = identity plus invented backstory, BEC = compromised/spoofed internal executive email, brand impersonation = faking a company's look."},
  {"id":"q114","domain":"D2","family":"impersonation","question":"An analyst is writing a detection playbook for business email compromise. Which description should the playbook use for BEC?","options":["a spoofed or compromised internal executive email requesting urgent payments","a fake lookalike of a consumer brand's website","an invented backstory used to justify a request","casually posing as a coworker in a hallway"],"correctIndex":0,"explanation":"BEC = executive mailbox abuse for money. The compromised or spoofed internal email plus an urgent financial request is the pattern that makes BEC the costliest scam in this family. The tell: BEC = internal executive email and payments, brand impersonation = external customer-facing fakery, pretexting = the cover story, impersonation = posing as a person."},
  {"id":"q115","domain":"D2","family":"impersonation","question":"Finance receives an urgent gift-card request from ceo@cornpany.com - a registered lookalike of the real company.com domain, complete with the CEO's real signature block scraped from LinkedIn. Which technique is this?","options":["pretexting","business email compromise (BEC)","watering hole","brand impersonation"],"correctIndex":1,"explanation":"Business email compromise. A spoofed or lookalike executive mailbox pressuring staff for payments is BEC - compromise of the real mailbox is not required, spoofing counts. The tell: BEC = executive email angle plus a money request, pretexting = the invented backstory, brand impersonation = faking a company to its customers, watering hole = poisoning a site targets visit."},
  {"id":"q116","domain":"D2","family":"impersonation","question":"A caller says he is from the company's HVAC vendor doing \"scheduled emergency maintenance,\" quotes a fake ticket number, and asks the receptionist for the server room door code to \"finish the job.\" Which technique BEST describes the fabricated maintenance story?","options":["brand impersonation","business email compromise (BEC)","pretexting","typosquatting"],"correctIndex":2,"explanation":"Pretexting. The engineered scenario - fake ticket, scheduled maintenance, urgency - is the pretext built to make the request seem legitimate. The tell: pretexting = the believable invented backstory, impersonation = just the false identity, BEC = executive email fraud, typosquatting = lookalike domains."},
  {"id":"q117","domain":"D2","family":"impersonation","question":"Thousands of consumers receive texts and emails styled exactly like a national parcel carrier - logo, colors, tracking-number format - claiming a failed delivery and linking to a payment page. Which technique is this?","options":["pretexting","impersonation","business email compromise (BEC)","brand impersonation"],"correctIndex":3,"explanation":"Brand impersonation. Faking a trusted company's visual identity to defraud that brand's customers at scale is brand impersonation. The tell: brand impersonation = the company's look copied for outsiders, BEC = an internal executive mailbox angle, impersonation = posing as an individual, pretexting = the story used to justify an ask."},
  {"id":"q118","domain":"D2","family":"social-eng-other","question":"Attackers compromise a niche industry news site that a defense contractor's engineers read every morning, planting an exploit kit that infects only visitors from the contractor's IP range. Which attack is this?","options":["watering hole","typosquatting","phishing","brand impersonation"],"correctIndex":0,"explanation":"Watering hole. Poisoning a legitimate site the target group already frequents, then waiting for them to come drink, is the watering hole attack. The tell: watering hole = compromise a site the targets already visit, typosquatting = register a misspelled lookalike domain, phishing = bait sent by email, brand impersonation = faking a company's identity."},
  {"id":"q119","domain":"D2","family":"social-eng-other","question":"A user typing quickly lands on a malicious site because an attacker registered a domain matching a common misspelling of a popular address, complete with a cloned login page. Which attack is this?","options":["watering hole","typosquatting","phishing","impersonation"],"correctIndex":1,"explanation":"Typosquatting. Registering the misspelled lookalike domain and waiting for fat-fingered visitors is typosquatting; no email lure or compromised legitimate site is involved. The tell: typosquatting = misspelled lookalike domain, watering hole = compromising a site targets already visit, phishing = fraudulent email, impersonation = posing as a person."},
  {"id":"q120","domain":"D2","family":"social-eng-other","question":"A threat intel report flags dozens of newly registered domains that are one keystroke away from the company's real domain, each hosting a cloned portal. Which technique do these registrations indicate?","options":["watering hole","brand impersonation","typosquatting","phishing"],"correctIndex":2,"explanation":"Typosquatting. Registering misspellings and near-variants of a legitimate domain to catch mistyped traffic is typosquatting. The tell: typosquatting = lookalike misspelled domains, watering hole = compromising a site targets already visit, phishing = the email lure itself, brand impersonation = copying the brand's look."},
  {"id":"q121","domain":"D2","family":"social-eng-other","question":"In a watering hole attack, how does the attacker reach the intended victims?","options":["by compromising a legitimate site the target group routinely visits","by registering a misspelled lookalike domain","by sending fraudulent email to each victim directly","by placing a phone call to each victim"],"correctIndex":0,"explanation":"By poisoning a site the targets already trust and visit, then waiting. The victims come to the attacker, not the reverse. The tell: watering hole = infect their regular watering spot, typosquatting = catch their typos, phishing = push email at them, vishing = call them."},
  {"id":"q122","domain":"D2","family":"social-eng-other","question":"Unable to breach a hardened defense contractor directly, attackers compromise the small restaurant-review site the contractor's staff browse every lunch break, serving exploits only to visitors from the contractor's IP range. Which attack is this?","options":["typosquatting","watering hole","brand impersonation","spear phishing"],"correctIndex":1,"explanation":"Watering hole. Compromising a legitimate third-party site the targets already frequent, then filtering for them, is the watering hole play - it flips the approach from reaching out to lying in wait. The tell: watering hole = poison where they already drink, typosquatting = catch their typos, spear phishing = targeted email outreach, brand impersonation = faking a trusted brand."},
  {"id":"q123","domain":"D2","family":"social-eng-other","question":"A security team's domain-monitoring service flags a fresh registration: gooogle-login.com, hosting a pixel-perfect copy of a sign-in page. Which attack does the registration itself represent?","options":["watering hole","brand impersonation","typosquatting","pretexting"],"correctIndex":2,"explanation":"Typosquatting. Registering a misspelling of a popular domain to catch mistyped traffic is typosquatting; the cloned page it hosts adds brand impersonation, but the registration play is the squat. The tell: typosquatting = the lookalike domain itself, brand impersonation = the copied visual identity, watering hole = compromising a real site, pretexting = the cover story."},
  {"id":"q124","domain":"D2","family":"social-eng-other","question":"A trainer asks the class to state the core difference between a watering hole attack and typosquatting. Which answer is correct?","options":["A watering hole compromises a legitimate site targets already visit; typosquatting registers a fake lookalike domain and waits for mistakes","They are two names for the same attack","Typosquatting requires compromising a CDN; watering holes require stolen certificates","A watering hole only works over SMS"],"correctIndex":0,"explanation":"Real site poisoned versus fake domain registered. The watering hole abuses a genuine site's existing audience; typosquatting builds a trap at a misspelled address. The tell: watering hole = their trusted site turns hostile, typosquatting = a hostile site pretends to be the address they meant."},
  {"id":"q125","domain":"D2","family":"attack-vectors","question":"A penetration tester scatters branded USB drives around the client's parking lot and lobby. Within two days, three had been plugged into corporate workstations. Which attack vector does this exercise test?","options":["open service ports","default credentials","removable device","message-based vector"],"correctIndex":2,"explanation":"Removable device. USB baiting exploits the removable-media vector and human curiosity. The tell: removable device = USB media carrying the payload, message-based = email/SMS/IM delivery, open service ports = exposed listening services, default credentials = unchanged factory passwords."},
  {"id":"q126","domain":"D2","family":"attack-vectors","question":"Attackers gain admin access to a newly racked network switch on its first weekend in production because nobody changed the factory admin password printed in the vendor manual. Which vector was exploited?","options":["open service ports","unsecure networks","removable device","default credentials"],"correctIndex":3,"explanation":"Default credentials. The out-of-the-box password, documented publicly by the vendor, was the way in. The tell: default credentials = unchanged factory passwords, open service ports = exposed services an attacker probes, unsecure networks = unencrypted or open Wi-Fi/LAN, removable device = USB media."},
  {"id":"q127","domain":"D2","family":"attack-vectors","question":"Evaluating monitoring products, an architect notes one option needs no software installed on the endpoints it watches: a smaller attack surface and nothing for malware to tamper with, but shallower visibility and control. Which model is described?","options":["agentless","client-based","file-based vector","open service ports"],"correctIndex":0,"explanation":"Agentless. No installed endpoint software is the agentless trade-off: lighter footprint, less depth. The tell: agentless = no installed software, less control, client-based = installed agent that itself can be attacked, file-based = malicious file as the carrier, open service ports = exposed listening services."},
  {"id":"q128","domain":"D2","family":"attack-vectors","question":"An external scan of a company's address space finds a database service listening on its default port, directly reachable from the internet with no filtering. Which attack vector does this exposure represent?","options":["default credentials","open service ports","removable device","unsecure networks"],"correctIndex":1,"explanation":"Open service ports. An exposed, listening service reachable by attackers is the open-port vector, regardless of what credentials it has. The tell: open service ports = exposed listening service, default credentials = unchanged factory passwords, unsecure networks = unencrypted/open networks, removable device = USB media."},
  {"id":"q129","domain":"D2","family":"attack-vectors","question":"A traveling employee joins the free open Wi-Fi at a cafe, which uses no encryption. Another patron passively captures the employee's traffic, including an unencrypted login. Which vector was exploited?","options":["open service ports","removable device","unsecure networks","default credentials"],"correctIndex":2,"explanation":"Unsecure networks. An open, unencrypted network lets anyone nearby read the traffic; the weakness is the network itself. The tell: unsecure networks = open/unencrypted Wi-Fi or LAN, open service ports = an exposed listening service, default credentials = factory passwords, removable device = USB media."},
  {"id":"q130","domain":"D2","family":"attack-vectors","question":"A user opens an SVG file from a chat message; script embedded inside the image executes in the browser and steals the session. Which attack vector did the payload travel through?","options":["image-based","voice call","removable device","default credentials"],"correctIndex":0,"explanation":"Image-based. Payload embedded in an image format (SVG can carry script) is the image-based vector - files that look like harmless pictures. The tell: image-based = the image is the carrier, file-based = documents/executables generally, removable device = USB media, voice call = the phone channel."},
  {"id":"q131","domain":"D2","family":"attack-vectors","question":"Attackers blast employees' phones with SMS messages containing a link to a fake benefits-enrollment portal during open-enrollment week. Which attack vector category is this?","options":["open service ports","message-based","client-based","removable device"],"correctIndex":1,"explanation":"Message-based. Delivery through email, SMS, or instant messaging is the message-based vector; this one rides SMS. The tell: message-based = the communication channel carries the lure, open service ports = exposed listeners, client-based = an installed agent as the way in, removable device = USB."},
  {"id":"q132","domain":"D2","family":"attack-vectors","question":"A vulnerability advisory reveals that a company's endpoint monitoring AGENT itself can be exploited for SYSTEM-level code execution, turning the security software into the entry point. Which vector category does this illustrate?","options":["agentless","unsecure networks","client-based","message-based"],"correctIndex":2,"explanation":"Client-based. Installed software - including security agents - expands the attack surface and can itself be compromised, the core client-based risk that agentless designs avoid. The tell: client-based = the installed agent is attackable, agentless = nothing installed to attack, unsecure networks = open/unencrypted transit, message-based = email/SMS/IM lures."},
  {"id":"q133","domain":"D2","family":"attack-vectors","question":"An accounts-payable clerk receives a call that sounds exactly like the company's controller - an AI-cloned voice - instructing her to release a held payment. Which attack vector is being used?","options":["removable device","file-based","image-based","voice call"],"correctIndex":3,"explanation":"Voice call. The attack arrives over the phone, cloned voice or not - the voice channel is the vector, and deepfakes just make it more convincing. The tell: voice call = the phone is the path in, message-based = text channels, file-based = a malicious file, image-based = a malicious image."},
  {"id":"q134","domain":"D2","family":"supply-chain","question":"A 60-person firm outsources its entire IT operation - helpdesk, server administration, and patching - to a third party that runs everything remotely under contract. Which supply-chain party is this third party?","options":["vendor","managed service provider (MSP)","supplier","hardware provider"],"correctIndex":1,"explanation":"Managed service provider. A third party operating your IT on an ongoing basis is an MSP, and its privileged access makes it a major supply-chain risk. The tell: MSP = runs your IT operations, vendor = sells you a product/service, supplier = provides upstream parts/materials, hardware provider = supplies the devices."},
  {"id":"q135","domain":"D2","family":"supply-chain","question":"A risk assessment maps the upstream chain for a laptop line: one firm provides the raw chips and components that the manufacturer builds into the finished machines. Which supply-chain party is the component firm?","options":["managed service provider (MSP)","software provider","supplier","vendor"],"correctIndex":2,"explanation":"Supplier. Providing parts and materials upstream that get built into finished goods is the supplier role. The tell: supplier = upstream parts/materials, vendor = sells you the finished product/service, MSP = operates your IT, software provider = supplies the applications."},
  {"id":"q136","domain":"D2","family":"supply-chain","question":"A company purchases a commercial endpoint-protection suite from the firm that develops and sells it, under a standard license agreement. In supply-chain terms, what is that firm to the company?","options":["managed service provider (MSP)","vendor","supplier","hardware provider"],"correctIndex":1,"explanation":"Vendor. Selling a finished product or service makes the firm a vendor; it does not operate the buyer's IT (MSP) or provide upstream components (supplier). The tell: vendor = sells you the product/service, MSP = runs your IT for you, supplier = upstream parts/materials, hardware provider = supplies the physical devices."},
  {"id":"q137","domain":"D2","family":"supply-chain","question":"In a supply-chain risk register, which party is defined as the one supplying the finished physical devices and equipment - laptops, switches, servers - that the organization deploys?","options":["software provider","supplier","managed service provider (MSP)","hardware provider"],"correctIndex":3,"explanation":"Hardware provider. Finished physical devices come from the hardware provider; raw upstream components come from suppliers. The tell: hardware provider = the devices, software provider = the applications, supplier = upstream parts/materials, MSP = operates your IT."},
  {"id":"q138","domain":"D2","family":"supply-chain","question":"Attackers breach a managed service provider and use its legitimate remote-management tool to push ransomware simultaneously to dozens of the MSP's client networks. Which supply-chain party turned one breach into many?","options":["managed service provider (MSP)","supplier","hardware provider","software provider"],"correctIndex":0,"explanation":"MSP. Its privileged, tooled access into every client makes the MSP a force multiplier: compromise one, reach all. The tell: MSP = operates inside many customers with standing access, vendor/supplier = sell things, hardware/software provider = supply products rather than run your systems."},
  {"id":"q139","domain":"D2","family":"supply-chain","question":"A batch of network appliances arrives from the factory with modified firmware that beacons to an attacker - implanted before the devices ever reached the customer. Which supply-chain party was the compromise point?","options":["managed service provider (MSP)","software provider","hardware provider","vendor's customer"],"correctIndex":2,"explanation":"Hardware provider. Tampering introduced in manufacturing or shipping compromises the hardware supply chain before deployment. The tell: hardware provider = the physical devices and their factory path, software provider = the applications and updates, MSP = operates your IT remotely."},
  {"id":"q140","domain":"D2","family":"supply-chain","question":"A company's own code is clean, but a compromised commercial library it licenses ships a backdoored update that flows straight into the company's product build. Which supply-chain party introduced the risk?","options":["software provider","hardware provider","managed service provider (MSP)","supplier of raw materials"],"correctIndex":0,"explanation":"Software provider. Licensed code and its update channel are the software supply chain; their compromise becomes yours at build time. The tell: software provider = the code you consume, hardware provider = the devices, MSP = your outsourced operations, supplier = upstream parts and materials."},
  {"id":"q141","domain":"D2","family":"supply-chain","question":"A procurement training slide contrasts two roles: one sells the company its finished firewall product; the other provides the chips that go INTO that firewall upstream. Which pairing is correct?","options":["Both are MSPs","The firewall seller is the supplier; the chip firm is the vendor","The firewall seller is the vendor; the chip firm is the supplier","Both are hardware providers with identical risk"],"correctIndex":2,"explanation":"Vendor sells you the product; supplier feeds the chain upstream. The chip firm never deals with you directly, which is exactly why its risk hides. The tell: vendor = your direct seller, supplier = the parts behind your seller, MSP = a third party operating your IT."},
  {"id":"q142","domain":"D2","family":"app-vulns","question":"A tester types ' OR '1'='1 into a login form's username field, and the application responds by returning every row of the user table. Which vulnerability was exploited?","options":["cross-site scripting (XSS)","buffer overflow","memory injection","SQL injection (SQLi)"],"correctIndex":3,"explanation":"SQL injection. Input altered the database query itself, dumping table contents; the target was the database, not other users' browsers. The tell: SQLi = inject SQL into a query to hit the database, XSS = inject script that runs in another user's browser, buffer overflow = write past a memory boundary, memory injection = insert code into a running process."},
  {"id":"q143","domain":"D2","family":"app-vulns","question":"An attacker posts a product review containing a hidden script tag. Every shopper who later views that page unknowingly runs the script, which ships their session cookies to the attacker. Which vulnerability is this?","options":["cross-site scripting (XSS)","SQL injection (SQLi)","malicious update","buffer overflow"],"correctIndex":0,"explanation":"Cross-site scripting. The injected script executes in other users' browsers, stealing their sessions; the victims are the visitors, not the database. The tell: XSS = script runs in another user's browser, SQLi = query manipulation against the database, malicious update = trojanized software update, buffer overflow = overrun a memory boundary."},
  {"id":"q144","domain":"D2","family":"app-vulns","question":"A vulnerability report explains that a network service copies attacker-supplied data into a fixed-length memory region without checking size, letting the attacker overwrite adjacent memory and hijack execution. Which vulnerability is described?","options":["memory injection","buffer overflow","SQL injection (SQLi)","malicious update"],"correctIndex":1,"explanation":"Buffer overflow. Writing past a fixed buffer's boundary to clobber adjacent memory is the classic overflow. The tell: buffer overflow = write past a buffer boundary, memory injection = insert code into a running process's memory space, SQLi = database query manipulation, malicious update = poisoned software update."},
  {"id":"q145","domain":"D2","family":"app-vulns","question":"Attackers breach a software vendor's build server and slip a backdoor into the next signed update. Thousands of customers install it automatically because it comes from the trusted update channel. Which vulnerability is this?","options":["malicious update","memory injection","buffer overflow","SQL injection (SQLi)"],"correctIndex":0,"explanation":"Malicious update. A trojanized update delivered through the vendor's own trusted channel is the malicious-update vulnerability, the pattern behind major supply-chain breaches. The tell: malicious update = poisoned software update, memory injection = code inserted into a running process, buffer overflow = overrun a memory boundary, SQLi = database query manipulation."},
  {"id":"q146","domain":"D2","family":"app-vulns","question":"An EDR alert shows attack code being written directly into the address space of a running, legitimate process and executed there, leaving no new file on disk. Which vulnerability class is this?","options":["buffer overflow","memory injection","cross-site scripting (XSS)","malicious update"],"correctIndex":1,"explanation":"Memory injection. Inserting and running code inside a live process's memory, common in fileless malware, is memory injection. A buffer overflow is one way in, but the described technique is the injection itself. The tell: memory injection = code planted in a running process's memory, buffer overflow = writing past a buffer to corrupt memory, XSS = script in another user's browser, malicious update = poisoned update channel."},
  {"id":"q147","domain":"D2","family":"app-vulns","question":"An attacker saves a script tag into the \"display name\" field of his profile on a forum. From then on, EVERY user who views any page showing that name executes the script. Which vulnerability is this?","options":["SQL injection (SQLi)","cross-site scripting (XSS)","memory injection","buffer overflow"],"correctIndex":1,"explanation":"Cross-site scripting - the stored variety. The script persists in the application's data and executes in every viewer's browser. The tell: XSS = script runs in other users' browsers, SQLi = query manipulation against the database, memory injection = code into a running process, buffer overflow = overrunning memory bounds."},
  {"id":"q148","domain":"D2","family":"app-vulns","question":"A tester enters 1' UNION SELECT username, password FROM users-- into a product search box, and the results page renders the credential table alongside the products. Which vulnerability was exploited?","options":["cross-site scripting (XSS)","malicious update","buffer overflow","SQL injection (SQLi)"],"correctIndex":3,"explanation":"SQL injection. The UNION SELECT reshaped the database query itself, pulling another table into the results - the payload targeted the database, not other users. The tell: SQLi = the query is the victim, XSS = the viewer's browser is the victim, buffer overflow = memory bounds, malicious update = poisoned update channel."},
  {"id":"q149","domain":"D2","family":"app-vulns","question":"A report explains that sending an oversized crafted string to an IoT camera's login service overwrites the return address on the stack, letting the attacker redirect execution into their payload. Which vulnerability class is this?","options":["buffer overflow","SQL injection (SQLi)","malicious update","cross-site scripting (XSS)"],"correctIndex":0,"explanation":"Buffer overflow. Oversized input overwriting adjacent memory - here the stack return address - is the classic overflow leading to code execution. The tell: buffer overflow = past the buffer's boundary into control data, memory injection = planting code in a live process by other means, SQLi/XSS = interpreter and browser attacks."},
  {"id":"q150","domain":"D2","family":"app-vulns","question":"A security review flags that a desktop application fetches updates over plain HTTP and never verifies signatures, meaning anyone on the path could substitute a poisoned installer that clients would trust and run. Which vulnerability does this expose the product to?","options":["memory injection","malicious update","race condition","SQL injection (SQLi)"],"correctIndex":1,"explanation":"Malicious update. An unauthenticated update channel lets attackers deliver trojanized updates that install with full user trust. Signed, verified updates are the defense. The tell: malicious update = the update path is the weapon, memory injection = code into a running process, SQLi = database queries, race condition = timing gaps."},
  {"id":"q151","domain":"D2","family":"race-conditions","question":"A program checks that a user may access a file, then opens it a few milliseconds later. An attacker swaps in a symlink to /etc/shadow during that tiny gap. What is the exploited gap between the check and the access called?","options":["time-of-check (TOC)","time-of-use (TOU)","time-of-check to time-of-use (TOCTOU)","race condition"],"correctIndex":2,"explanation":"TOCTOU. The exploit window between checking and using the resource is the time-of-check to time-of-use gap. The tell: TOC = the moment permission is checked, TOU = the moment the resource is used, TOCTOU = the exploitable gap between them, race condition = the general timing-dependent bug class."},
  {"id":"q152","domain":"D2","family":"race-conditions","question":"In a TOCTOU vulnerability writeup, the report references the exact instant at which the application validated the resource's permissions. Which term names that instant?","options":["time-of-use (TOU)","race condition","TOCTOU window","time-of-check (TOC)"],"correctIndex":3,"explanation":"Time-of-check. The validation moment is the TOC; the later access moment is the TOU. The tell: TOC = when permission is checked, TOU = when the resource is actually used, TOCTOU window = the gap between them, race condition = the broader timing-bug category."},
  {"id":"q153","domain":"D2","family":"race-conditions","question":"Two threads of a banking app process the same withdrawal simultaneously, and whether the account goes negative depends purely on which thread finishes first. What is this class of bug generally called?","options":["race condition","time-of-check (TOC)","time-of-use (TOU)","TOCTOU"],"correctIndex":0,"explanation":"Race condition. Any flaw whose outcome depends on the unpredictable timing or ordering of concurrent events is a race condition; TOCTOU is one specific flavor. The tell: race condition = outcome depends on timing, TOC = the check moment, TOU = the use moment, TOCTOU = the check-to-use gap exploit."},
  {"id":"q154","domain":"D2","family":"race-conditions","question":"In a TOCTOU vulnerability report, which term names the exact moment the resource is actually accessed or consumed, after its permissions were validated earlier?","options":["race condition","time-of-check (TOC)","time-of-use (TOU)","TOCTOU window"],"correctIndex":2,"explanation":"Time-of-use. The access moment is the TOU; the earlier validation was the TOC, and the exploitable gap between them is the TOCTOU window. The tell: TOU = when the resource is used, TOC = when it is checked, TOCTOU window = the gap, race condition = the general class."},
  {"id":"q155","domain":"D2","family":"race-conditions","question":"Two threads each read an account balance of $100 at the same instant, and each subtracts $80. The final balance is wrong because the operations interleaved unpredictably. This flaw is best classified as a ___.","options":["time-of-check (TOC)","time-of-use (TOU)","TOCTOU window","race condition"],"correctIndex":3,"explanation":"Race condition. The outcome depends purely on the timing and interleaving of concurrent operations, the definition of a race. No separate check-then-use gap is described, so it is not specifically TOCTOU. The tell: race condition = timing-dependent outcome, TOC = the check moment, TOU = the use moment, TOCTOU = the check-to-use exploit window."},
  {"id":"q156","domain":"D2","family":"race-conditions","question":"Which statement correctly pairs the two moments that define a TOCTOU flaw?","options":["Time-of-check and time-of-use are the same instant.","Time-of-use always occurs before time-of-check.","Neither term relates to timing.","Time-of-check is when permission is validated; time-of-use is when the resource is actually accessed."],"correctIndex":3,"explanation":"Check first, use later, exploit the gap. TOC is the validation instant, TOU is the access instant, and the attack lives in the time between. The tell: TOC = check, TOU = use, and TOCTOU is dangerous precisely because they are NOT the same instant."},
  {"id":"q157","domain":"D2","family":"system-vulns","question":"A cloud tenant exploits a hypervisor flaw to break out of their guest virtual machine and execute code on the underlying host, exposing every other tenant's VM on that box. Which vulnerability is this?","options":["resource reuse","VM escape","side loading","jailbreaking"],"correctIndex":1,"explanation":"VM escape. Breaking out of a guest to reach the hypervisor or host is VM escape, the nightmare scenario for shared infrastructure. The tell: VM escape = guest to host breakout, resource reuse = leftover data in reallocated memory/storage, side loading = installing apps outside the official store, jailbreaking = removing OS restrictions for root."},
  {"id":"q158","domain":"D2","family":"system-vulns","question":"A security advisory warns of active exploitation of a flaw the software vendor does not yet know exists, meaning no patch or signature is available to anyone. What is this vulnerability called?","options":["end-of-life","legacy","zero-day","misconfiguration"],"correctIndex":2,"explanation":"Zero-day. Unknown to the vendor and unpatched, giving defenders zero days of warning. The tell: zero-day = no patch exists yet, end-of-life = vendor stopped supporting it, legacy = outdated but still running, misconfiguration = insecure settings, not a code flaw."},
  {"id":"q159","domain":"D2","family":"system-vulns","question":"An employee removes the manufacturer's operating system restrictions on their personal phone to get root access and install apps the platform forbids, then connects the phone to corporate email. Which term describes what they did to the phone?","options":["side loading","resource reuse","firmware vulnerability","jailbreaking"],"correctIndex":3,"explanation":"Jailbreaking. Removing OS restrictions to gain root is jailbreaking; merely installing an app from outside the official store, without rooting, would be side loading. The tell: jailbreaking = strip OS restrictions for root access, side loading = install apps outside the official store, resource reuse = leftover data in reallocated resources, firmware vulnerability = flaw in the low-level device code."},
  {"id":"q160","domain":"D2","family":"system-vulns","question":"An operations team discovers a production firewall model that the vendor stopped selling years ago and no longer writes security patches for. Which term describes the device's status?","options":["legacy","end-of-life","misconfiguration","firmware vulnerability"],"correctIndex":1,"explanation":"End-of-life. The vendor has formally ended sales and support, so no patches will ever come. Legacy describes outdated technology still in use, which may or may not still be supported. The tell: end-of-life = vendor ended support, legacy = outdated but still running, misconfiguration = insecure settings, firmware vulnerability = flaw in the device's low-level code."},
  {"id":"q161","domain":"D2","family":"system-vulns","question":"A cloud tenant spins up a new virtual disk and finds fragments of another company's database in the unwiped blocks, left over from the volume's previous owner. Which vulnerability is this?","options":["misconfiguration","VM escape","side loading","resource reuse"],"correctIndex":3,"explanation":"Resource reuse. Leftover data surviving in reallocated memory or storage handed to a new tenant is the resource-reuse vulnerability. The tell: resource reuse = residual data in reallocated resources, VM escape = guest-to-host breakout, misconfiguration = insecure settings, side loading = apps installed outside the official store."},
  {"id":"q162","domain":"D2","family":"system-vulns","question":"Researchers disclose a flaw in a router's low-level bootstrap code - beneath the operating system - that survives OS reinstalls and lets attackers persist invisibly. Which vulnerability category is this?","options":["firmware","misconfiguration","side loading","VM escape"],"correctIndex":0,"explanation":"Firmware. Flaws in the device's embedded low-level code sit below the OS, survive reinstalls, and are patched only by firmware updates. The tell: firmware = beneath the OS, persists through rebuilds, misconfiguration = wrong settings, side loading = out-of-store app installs, VM escape = guest-to-host breakout."},
  {"id":"q163","domain":"D2","family":"system-vulns","question":"A plant still runs a 15-year-old control workstation because the machinery requires it. The OS is long outdated, though the vendor still sells extended security patches the plant purchases. Which term BEST describes this system?","options":["zero-day","end-of-life","legacy","resource reuse"],"correctIndex":2,"explanation":"Legacy. Outdated technology still in production is legacy; because the vendor still provides (paid) support, it is not yet end-of-life. The tell: legacy = old but still running and possibly still supported, end-of-life = vendor support has ended, zero-day = an unknown unpatched flaw, resource reuse = leftover data in reallocated resources."},
  {"id":"q164","domain":"D2","family":"system-vulns","question":"Without rooting or jailbreaking anything, a user downloads an APK file from a website and installs it on her Android phone, bypassing the official store's vetting entirely. Which term describes this?","options":["jailbreaking","side loading","VM escape","firmware vulnerability"],"correctIndex":1,"explanation":"Side loading. Installing apps from outside the official store, without modifying the OS, is side loading - the store's malware vetting is what gets skipped. The tell: side loading = out-of-store install on a stock device, jailbreaking = removing OS restrictions for root, VM escape = hypervisor breakout, firmware = below-OS code flaws."},
  {"id":"q165","domain":"D2","family":"system-vulns","question":"A breach postmortem finds the exposed cloud storage bucket had no flaw in its code at all - an engineer simply set its permissions to public during testing and never reverted them. Which vulnerability category is this?","options":["zero-day","end-of-life","VM escape","misconfiguration"],"correctIndex":3,"explanation":"Misconfiguration. The software worked exactly as configured; the configuration was the vulnerability. Human settings errors rival code flaws as breach causes. The tell: misconfiguration = insecure settings, not broken code, zero-day = unknown code flaw, end-of-life = unsupported product, VM escape = guest breakout."},
  {"id":"q166","domain":"D2","family":"malware","question":"Overnight, malware sweeps through a flat corporate network by exploiting an unpatched SMB service on each machine it finds. No user opened, clicked, or ran anything. Which malware type is this?","options":["worm","virus","trojan","logic bomb"],"correctIndex":0,"explanation":"Worm. Self-replication across the network with zero user action is the worm signature; a virus needs a host file and a user to trigger it. The tell: worm = self-spreads over the network, virus = needs a host file and user action, trojan = disguised as legitimate software, logic bomb = payload waiting on a trigger condition."},
  {"id":"q167","domain":"D2","family":"malware","question":"Staff arrive to find every shared drive encrypted and a note demanding cryptocurrency within 72 hours for the decryption key. Which malware type hit them?","options":["spyware","ransomware","rootkit","keylogger"],"correctIndex":1,"explanation":"Ransomware. Encrypting data and extorting payment for its return defines ransomware. The tell: ransomware = encrypts and extorts, spyware = secretly collects activity, rootkit = hides at the OS/kernel level, keylogger = records keystrokes."},
  {"id":"q168","domain":"D2","family":"malware","question":"During incident response, analysts discover malware that patched kernel structures to hide its own processes and files from every tool on the box, maintaining privileged persistence for months. Which malware type is this?","options":["trojan","bloatware","rootkit","virus"],"correctIndex":2,"explanation":"Rootkit. Kernel-level concealment and persistent privileged access are rootkit behavior, which is why detection from inside the infected OS is unreliable. The tell: rootkit = hides at OS/kernel level, trojan = disguised as legitimate, bloatware = unwanted preinstalled software, virus = infects host files, needs user action."},
  {"id":"q169","domain":"D2","family":"malware","question":"A database administrator facing layoffs plants a script that will wipe the production databases automatically if his account ever disappears from the payroll system. Which malware type is this?","options":["worm","spyware","keylogger","logic bomb"],"correctIndex":3,"explanation":"Logic bomb. A dormant payload triggered by a specific condition, here his own termination, is a logic bomb. The tell: logic bomb = payload fires on a condition/date, worm = self-spreads, spyware = covert data collection, keylogger = records keystrokes."},
  {"id":"q170","domain":"D2","family":"malware","question":"A user downloads what appears to be a free PDF converter. It converts PDFs as advertised, while quietly installing a remote-access backdoor in the background. Which malware type is this?","options":["trojan","virus","worm","bloatware"],"correctIndex":0,"explanation":"Trojan. Software posing as something legitimate and useful that the user willingly installs, hiding a malicious payload, is a trojan. The tell: trojan = disguised as legitimate, virus = attaches to host files and spreads with user action, worm = spreads itself over the network, bloatware = unwanted but not malicious preinstalls."},
  {"id":"q171","domain":"D2","family":"malware","question":"Forensics on a compromised laptop finds software that silently recorded every keystroke - passwords, messages, card numbers - and uploaded the capture files to an attacker's server nightly. Which malware type is this?","options":["spyware","trojan","rootkit","keylogger"],"correctIndex":3,"explanation":"Keylogger. Recording keystrokes specifically is the keylogger's defining behavior; broader covert activity monitoring would be spyware. The tell: keylogger = records keystrokes, spyware = collects activity/browsing generally, trojan = disguised delivery vehicle, rootkit = kernel-level concealment."},
  {"id":"q172","domain":"D2","family":"malware","question":"A malicious payload rides inside a spreadsheet macro. It runs only when a user opens the file and clicks Enable Content, after which it infects other documents on the machine. Which malware type is this?","options":["virus","worm","trojan","spyware"],"correctIndex":0,"explanation":"Virus. It needs a host file and a user action to execute and spread, the classic virus requirements; a worm would spread by itself over the network. The tell: virus = host file plus user action, worm = self-replicates with no user, trojan = poses as legitimate software, spyware = covert monitoring."},
  {"id":"q173","domain":"D2","family":"malware","question":"An investigation finds software covertly logging a user's browsing history, search terms, and app usage and selling the profile to a third party. It captures no keystrokes. Which malware type is this?","options":["keylogger","bloatware","spyware","rootkit"],"correctIndex":2,"explanation":"Spyware. Covert collection of activity data without consent is spyware; the stem explicitly rules out keystroke capture. The tell: spyware = secretly collects activity, keylogger = specifically records keystrokes, bloatware = unwanted preinstalled software, rootkit = hides at the kernel."},
  {"id":"q174","domain":"D2","family":"malware","question":"A brand-new consumer laptop arrives crammed with preinstalled trialware and vendor utilities that slow boot times and nag the user. Nothing is stealing data - it is just unwanted. Which category is this?","options":["spyware","trojan","bloatware","rootkit"],"correctIndex":2,"explanation":"Bloatware. Unwanted preinstalled software that degrades performance without malicious behavior is bloatware - remove it to shrink the attack surface anyway. The tell: bloatware = unwanted but not hostile, spyware = covert data collection, trojan = disguised malice, rootkit = kernel-level hiding."},
  {"id":"q175","domain":"D2","family":"malware","question":"During a sweep, a technician finds a small device plugged inline between a workstation's keyboard cable and its USB port, storing every keystroke typed at the machine. Which threat is this?","options":["keylogger","rootkit","worm","logic bomb"],"correctIndex":0,"explanation":"Keylogger - the hardware variety. Keystroke capture defines the keylogger whether implemented in software or as an inline dongle no antivirus can see. The tell: keylogger = records keystrokes, rootkit = software hiding in the kernel, worm = self-spreading malware, logic bomb = condition-triggered payload."},
  {"id":"q176","domain":"D2","family":"malware","question":"An instructor asks what a worm does NOT require that a virus does. Which answer is correct?","options":["A network connection","A host file and user action to spread","An operating system","A payload"],"correctIndex":1,"explanation":"A worm needs no host file and no user action - it spreads itself across the network by exploiting services. A virus must attach to a file and wait for a user to run it. The tell: worm = autonomous spread, virus = hitchhikes on files and users; both may carry any payload."},
  {"id":"q177","domain":"D2","family":"malware","question":"Attackers encrypt a firm's files AND exfiltrate copies first, threatening to publish the data publicly if the payment demand is refused - extortion on two fronts. Which malware category is at work?","options":["spyware","logic bomb","trojan","ransomware"],"correctIndex":3,"explanation":"Ransomware. Encryption plus payment demand is ransomware; the added leak threat is the double-extortion evolution of the same category. The tell: ransomware = extortion over your data's availability or secrecy, spyware = quiet collection, trojan = the disguise it may arrive in, logic bomb = waits for a trigger."},
  {"id":"q178","domain":"D2","family":"malware","question":"A gamer installs a \"free cracked version\" of a paid game from a torrent site. The game runs perfectly - while a hidden cryptominer pins the GPU whenever the machine idles. Which malware type is the download?","options":["worm","virus","trojan","bloatware"],"correctIndex":2,"explanation":"Trojan. Desirable-looking software willingly installed, hiding an unwanted payload, is a trojan - the cracked game is the classic lure. The tell: trojan = the disguise is the delivery, virus = infects host files, worm = spreads itself, bloatware = unwanted but honest preinstalls."},
  {"id":"q179","domain":"D2","family":"ddos-network","question":"An attacker sends 60-byte queries to open DNS resolvers, each of which emits a 3,000-byte response aimed at the victim. It is this response-to-request size multiplication that crushes the victim's link. Which DDoS characteristic does this describe?","options":["reflected DDoS","amplified DDoS","on-path attack","credential replay"],"correctIndex":1,"explanation":"Amplified DDoS. The defining feature named here is the size multiplier: tiny request, huge response. Reflection (spoofing the victim's address) is usually combined with it, but the multiplication is amplification. The tell: amplified = small request yields a huge response, reflected = third parties reply to the spoofed victim, on-path = attacker sits between two parties, credential replay = resending captured credentials."},
  {"id":"q180","domain":"D2","family":"ddos-network","question":"An attacker spoofs the victim's IP address as the source on thousands of requests to innocent third-party servers, so every server's reply lands on the victim instead of the attacker. Which attack is this?","options":["amplified DDoS","on-path attack","reflected DDoS","DNS attack"],"correctIndex":2,"explanation":"Reflected DDoS. Bouncing traffic off third parties by spoofing the victim's source address is reflection; if the replies were also much larger than the requests, amplification would be stacked on top. The tell: reflected = spoofed source makes third parties reply to the victim, amplified = the size multiplier, on-path = interception between two parties, DNS attack = poisoning or hijacking name resolution."},
  {"id":"q181","domain":"D2","family":"ddos-network","question":"On a hotel network, an attacker inserts themselves between a guest's laptop and the gateway, silently relaying and modifying the traffic flowing in both directions. Which attack is this?","options":["credential replay","reflected DDoS","DNS attack","on-path attack"],"correctIndex":3,"explanation":"On-path attack. Sitting between two parties to read or alter their traffic is the on-path attack (the SY0-701 term for what was once called man in the middle). The tell: on-path = attacker between two parties reading/altering traffic, credential replay = resending captured credentials, reflected DDoS = third parties reply to a spoofed victim, DNS attack = corrupting name resolution."},
  {"id":"q182","domain":"D2","family":"ddos-network","question":"An attacker sniffs a valid session token from unencrypted traffic, then resends it an hour later to authenticate to the application as the legitimate user. Which attack is this?","options":["credential replay","on-path attack","amplified DDoS","DNS attack"],"correctIndex":0,"explanation":"Credential replay. Capturing valid credentials or a session token and resending them later is replay; the attacker never cracked anything. The tell: credential replay = resend captured credentials/session, on-path = live interception between parties, amplified DDoS = small request/huge response flooding, DNS attack = poisoned name resolution."},
  {"id":"q183","domain":"D2","family":"ddos-network","question":"Users typing their bank's correct web address are silently routed to a fraudulent server because an attacker poisoned the cached answers on their DNS resolver. Which attack is this?","options":["reflected DDoS","DNS attack","credential replay","on-path attack"],"correctIndex":1,"explanation":"DNS attack. Corrupting name resolution so a correct domain resolves to the attacker's server is DNS poisoning/hijacking. The tell: DNS attack = poisoned or hijacked name resolution, on-path = attacker relaying between two parties, credential replay = resending captured credentials, reflected DDoS = third parties flooding a spoofed victim."},
  {"id":"q184","domain":"D2","family":"ddos-network","question":"In an office lobby, an attacker's device broadcasts the same SSID as the corporate wireless network at higher power, luring laptops into associating with it instead. Which attack category is this?","options":["DNS attack","credential replay","amplified DDoS","wireless attack"],"correctIndex":3,"explanation":"Wireless attack. A rogue access point (evil twin) impersonating the legitimate SSID is a wireless-layer attack. The tell: wireless attack = rogue AP/evil twin at the radio layer, DNS attack = poisoned name resolution, credential replay = resent captured credentials, amplified DDoS = small-request/huge-response flooding."},
  {"id":"q185","domain":"D2","family":"ddos-network","question":"A network engineer is explaining DDoS mechanics to a junior analyst. What primarily distinguishes an amplified DDoS from a reflected DDoS?","options":["Amplification exploits a large response-to-request size ratio, while reflection spoofs the victim's source so third parties reply to the victim.","They are identical attacks.","Reflection uses malware while amplification uses phishing.","Amplification only works against DNS servers."],"correctIndex":0,"explanation":"Amplification is the size multiplier; reflection is the redirection trick. Real attacks usually combine them: spoof the victim (reflection) at services with huge responses (amplification). The tell: amplified = response much bigger than request, reflected = spoofed source makes third parties answer the victim."},
  {"id":"q186","domain":"D2","family":"ddos-network","question":"Attackers social-engineer a domain registrar into transferring control of a company's domain, then point its name records at their own servers - every user typing the correct address now lands on attacker infrastructure. Which attack category is this?","options":["DNS attack","amplified DDoS","credential replay","on-path attack"],"correctIndex":0,"explanation":"DNS attack - domain hijacking. Controlling the domain's records corrupts name resolution at the source, no cache poisoning needed. The tell: DNS attack = name resolution is the target (poisoning, hijacking), on-path = interception between parties, amplified DDoS = volumetric flooding, credential replay = resent captured credentials."},
  {"id":"q187","domain":"D2","family":"ddos-network","question":"On a corporate LAN, an attacker sends forged ARP replies so the victim's traffic to the gateway routes through the attacker's machine first, where it is read and forwarded along. Which attack is this?","options":["reflected DDoS","on-path attack","DNS attack","amplified DDoS"],"correctIndex":1,"explanation":"On-path attack. ARP spoofing inserts the attacker between victim and gateway to read or alter traffic in transit - a textbook on-path technique at Layer 2. The tell: on-path = positioned between two parties, DNS attack = poisoned name lookups, reflected/amplified DDoS = flooding via third parties."},
  {"id":"q188","domain":"D2","family":"ddos-network","question":"An attacker abuses NTP servers whose response to one small query is up to 500 times larger, directing that multiplied flood at a victim. The 500x ratio is the weapon. Which DDoS characteristic is this?","options":["reflected DDoS","credential replay","amplified DDoS","on-path attack"],"correctIndex":2,"explanation":"Amplified DDoS. The huge response-to-request ratio is amplification, and NTP's legacy commands were a notorious multiplier. The tell: amplified = the size multiplication, reflected = the spoofed-source redirection usually paired with it, on-path = interception, credential replay = resending captured authentication."},
  {"id":"q189","domain":"D2","family":"ddos-network","question":"An attacker captures an authentication hash off the network and, without ever cracking it, submits the hash itself to authenticate to other servers as that user. Which attack category is this?","options":["credential replay","amplified DDoS","DNS attack","wireless attack"],"correctIndex":0,"explanation":"Credential replay. Reusing captured authentication material as-is (pass-the-hash) is replaying credentials - no cracking required. The tell: credential replay = captured material resubmitted, on-path = live interception position, DNS attack = name resolution abuse, wireless = radio-layer attacks."},
  {"id":"q190","domain":"D2","family":"app-attacks","question":"A web server log shows requests like GET /view?file=../../../../etc/passwd, and the response body contains the server's account file from outside the web root. Which attack is this?","options":["injection","directory traversal","request forgery (CSRF)","replay attack"],"correctIndex":1,"explanation":"Directory traversal. Using ../ sequences to walk out of the web root and read arbitrary server files is traversal. The tell: directory traversal = ../ path tricks to escape the web root, injection = malicious input fed to an interpreter, forgery = tricking a user's browser into a state-changing request, replay = resending captured traffic."},
  {"id":"q191","domain":"D2","family":"app-attacks","question":"While logged in to her bank, a user clicks a link in a forum post. Her browser silently submits a hidden transfer request to the bank, which processes it because her session cookie rides along automatically. Which attack is this?","options":["privilege escalation","replay attack","request forgery (CSRF)","directory traversal"],"correctIndex":2,"explanation":"Request forgery. The attacker tricked the victim's own authenticated browser into sending a state-changing request, the essence of CSRF. The tell: forgery = victim's browser unknowingly sends the request, replay = attacker resends captured traffic, privilege escalation = gaining higher rights, directory traversal = ../ file access."},
  {"id":"q192","domain":"D2","family":"app-attacks","question":"A help-desk user exploits an unquoted service path flaw on a server and ends up running commands as SYSTEM, far beyond the rights their account was ever granted. Which attack is this?","options":["injection","request forgery (CSRF)","replay attack","privilege escalation"],"correctIndex":3,"explanation":"Privilege escalation. Leveraging a flaw to move from limited rights to administrator/SYSTEM is escalation, the follow-on step after most footholds. The tell: privilege escalation = gain higher rights than granted, injection = malicious input to an interpreter, forgery = tricking a browser into a request, replay = resending captured traffic."},
  {"id":"q193","domain":"D2","family":"app-attacks","question":"An attacker captures a legitimate signed API request that transfers $500, then resends the identical request fifty times, draining the account through repetition alone. Which attack is this?","options":["injection","replay attack","request forgery (CSRF)","directory traversal"],"correctIndex":1,"explanation":"Replay attack. Recording valid traffic and resending it unchanged to repeat the action is replay; nothing was forged or injected. The tell: replay = attacker resends captured traffic, forgery = victim's own browser is tricked into sending the request, injection = malicious input to an interpreter, directory traversal = ../ path escape."},
  {"id":"q194","domain":"D2","family":"app-attacks","question":"A code review guideline warns about the attack category where untrusted input is passed to an interpreter - SQL, LDAP, OS shell - and executed as part of the command. Which category is this?","options":["directory traversal","request forgery (CSRF)","injection","replay attack"],"correctIndex":2,"explanation":"Injection. Any attack where crafted input becomes executable interpreter syntax - SQLi, command injection, LDAP injection - belongs to the injection category. The tell: injection = input executed by an interpreter, directory traversal = path tricks to read files, forgery = tricking a browser into a request, replay = resending captured traffic."},
  {"id":"q195","domain":"D2","family":"app-attacks","question":"A web form pings a user-supplied IP for diagnostics. A tester enters 8.8.8.8; rm -rf /tmp/test and the server executes both commands, proving user input reaches the OS shell. Which attack category is this?","options":["directory traversal","replay attack","request forgery (CSRF)","injection"],"correctIndex":3,"explanation":"Injection - command injection. Input flowing into the OS shell and executing is injection against the command interpreter, the same family as SQLi. The tell: injection = input becomes interpreter commands, directory traversal = path escape to read files, forgery = a victim's browser tricked into requests, replay = resent captured traffic."},
  {"id":"q196","domain":"D2","family":"app-attacks","question":"A WAF log shows requests containing %2e%2e%2f%2e%2e%2fetc%2fpasswd - URL-encoded to slip past naive filters, but decoding to a familiar pattern. Which attack is being attempted?","options":["injection","directory traversal","replay attack","privilege escalation"],"correctIndex":1,"explanation":"Directory traversal. The encoding decodes to ../../etc/passwd - the classic path escape, dressed up to evade filters that only match literal dots and slashes. The tell: directory traversal = ../ escapes (encoded or not), injection = commands into an interpreter, replay = captured traffic resent, privilege escalation = rights beyond those granted."},
  {"id":"q197","domain":"D2","family":"app-attacks","question":"A forum post contains an invisible image tag whose source URL is the router admin panel's \"disable firewall\" action. Any logged-in admin who merely views the post has their browser silently fire that request. Which attack is this?","options":["replay attack","injection","request forgery (CSRF)","directory traversal"],"correctIndex":2,"explanation":"Request forgery. The victim's own authenticated browser is tricked into issuing a state-changing request - no click even needed when an image tag does it. The tell: forgery = the victim's browser sends the attacker's request, replay = the attacker resends captured traffic, injection = interpreter abuse, traversal = path escape."},
  {"id":"q198","domain":"D2","family":"app-attacks","question":"An attacker intercepts a valid one-time payment authorization and resubmits the identical message before its window expires, causing the transaction to process a second time. Which attack is this?","options":["privilege escalation","replay attack","injection","request forgery (CSRF)"],"correctIndex":1,"explanation":"Replay attack. Capturing legitimate traffic and resending it unchanged within its validity window is replay; nonces and short expirations are the standard defenses. The tell: replay = the attacker resends real captured messages, forgery = the victim's browser is the unwitting sender, injection = crafted malicious input, privilege escalation = gaining higher rights."},
  {"id":"q199","domain":"D2","family":"app-attacks","question":"From a compromised low-privilege web account, an attacker exploits an unpatched kernel flaw on the server and lands a root shell - rights the web account never had. Which attack category is the kernel step?","options":["replay attack","request forgery (CSRF)","directory traversal","privilege escalation"],"correctIndex":3,"explanation":"Privilege escalation. Moving from limited rights to root via a flaw is vertical escalation, the standard second step after an initial foothold. The tell: privilege escalation = higher rights than granted, injection/traversal = ways to get the foothold, replay/forgery = request-level attacks."},
  {"id":"q200","domain":"D2","family":"crypto-attacks","question":"During a TLS handshake, an attacker interferes with the negotiation so client and server settle on an obsolete, breakable SSL cipher suite instead of the modern default both support. Which attack is this?","options":["downgrade attack","collision attack","birthday attack","rainbow table attack"],"correctIndex":0,"explanation":"Downgrade attack. Forcing parties onto a weaker protocol or cipher than they would normally use is a downgrade, the setup step for breaking the resulting weak session. The tell: downgrade = force a weaker protocol/cipher, collision = two inputs with the same hash, birthday = probability shortcut to find collisions, rainbow table = precomputed hash lookups."},
  {"id":"q201","domain":"D2","family":"crypto-attacks","question":"A researcher demonstrates two different PDF files that produce the identical MD5 digest, allowing a malicious contract to swap in for a signed benign one. Which attack does this demonstrate?","options":["downgrade attack","collision attack","birthday attack","brute-force attack"],"correctIndex":1,"explanation":"Collision attack. Two different inputs yielding the same hash is a collision, which breaks the integrity guarantee of the hash. The tell: collision = two inputs, same hash, birthday = the probabilistic method for finding collisions faster, downgrade = force weaker crypto, brute force = exhaustively trying inputs."},
  {"id":"q202","domain":"D2","family":"crypto-attacks","question":"An attack paper shows that finding a hash collision takes roughly the square root of the expected tries because the chance of ANY two inputs matching grows surprisingly fast, the same math as shared birthdays in a room. Which attack is this?","options":["collision attack","downgrade attack","birthday attack","rainbow table attack"],"correctIndex":2,"explanation":"Birthday attack. Exploiting the birthday-paradox math to find collisions far faster than brute force expects is the birthday attack; the collision is the result, the birthday attack is the method. The tell: birthday = probability shortcut for collisions, collision = the two-inputs-one-hash outcome, downgrade = force weaker crypto, rainbow table = precomputed lookups."},
  {"id":"q203","domain":"D2","family":"crypto-attacks","question":"A security researcher publishes two different executables with the identical SHA-1 digest, proving a malicious binary could silently stand in for a legitimately distributed one. Which attack does this exemplify?","options":["downgrade attack","birthday attack","rainbow table attack","collision attack"],"correctIndex":3,"explanation":"Collision attack. Two distinct inputs producing the same hash is a collision, which destroys the hash's value as an integrity check. The tell: collision = two inputs, one hash, birthday = the probability method that finds collisions faster, downgrade = forcing weaker crypto, rainbow table = precomputed hash lookups for password cracking."},
  {"id":"q204","domain":"D2","family":"crypto-attacks","question":"During TLS connection setup, an on-path attacker strips the strong cipher suites from the negotiation so both endpoints settle on an obsolete, breakable algorithm they still support for compatibility. Which attack is this?","options":["birthday attack","downgrade attack","collision attack","brute-force attack"],"correctIndex":1,"explanation":"Downgrade attack. Manipulating negotiation to force weaker crypto than both sides are capable of is the downgrade, and legacy-compatibility options are exactly what it exploits. The tell: downgrade = force the weaker protocol/cipher, birthday = probability shortcut for collisions, collision = same-hash forgery, brute force = exhaustive guessing."},
  {"id":"q205","domain":"D2","family":"crypto-attacks","question":"An exam-prep flashcard asks: how does a birthday attack relate to a collision attack?","options":["A birthday attack is a probability technique that finds hash collisions faster than brute force.","A birthday attack downgrades ciphers to weaker versions.","A collision attack only works against encryption keys, not hashes.","They are unrelated to one another."],"correctIndex":0,"explanation":"The birthday attack is the method, the collision is the result. Birthday-paradox math means matches appear after roughly the square root of the brute-force effort. The tell: birthday = the probabilistic technique, collision = the two-inputs-one-hash outcome it produces."},
  {"id":"q206","domain":"D2","family":"crypto-attacks","question":"A rogue access point advertises itself as WPA2-only, forcing nearby WPA3-capable clients to associate using the older protocol's weaker handshake, which the attacker then attacks offline. Which crypto attack pattern is this?","options":["downgrade attack","birthday attack","collision attack","spraying"],"correctIndex":0,"explanation":"Downgrade attack. Forcing capable parties onto an older, weaker protocol - WPA3 down to WPA2, TLS down to SSL - is the downgrade, exploited because compatibility fallbacks exist. The tell: downgrade = weaker protocol forced, collision = same hash from different inputs, birthday = the probability method for collisions, spraying = a password attack."},
  {"id":"q207","domain":"D2","family":"crypto-attacks","question":"A cryptographer explains that with a 128-bit hash, an attacker finds a collision after roughly 2 to the 64th attempts rather than 2 to the 128th, because the odds of ANY two inputs matching climb shockingly fast - like shared birthdays in a classroom. Which attack exploits this math?","options":["downgrade attack","birthday attack","rainbow table attack","brute-force attack"],"correctIndex":1,"explanation":"Birthday attack. The square-root shortcut from birthday-paradox probability is exactly what the birthday attack exploits, halving the effective bit strength against collisions. The tell: birthday = the probability math, collision = the result it finds, brute force = naive exhaustion, rainbow table = precomputed password lookups."},
  {"id":"q208","domain":"D2","family":"crypto-attacks","question":"Researchers craft a fraudulent TLS certificate whose hash exactly matches a legitimately signed certificate, letting the fake inherit the real signature's trust. Which attack does the matching hash represent?","options":["downgrade attack","brute-force attack","collision attack","password spraying"],"correctIndex":2,"explanation":"Collision attack. Two different documents sharing one hash means a signature on the benign one validates the malicious one - the attack that retired MD5 from certificates. The tell: collision = two inputs, one hash, one stolen trust, downgrade = weaker crypto forced, brute force = exhaustive guessing, spraying = passwords, not hashes."},
  {"id":"q209","domain":"D2","family":"crypto-attacks","question":"An exam-prep drill asks students to separate two attacks: one manipulates protocol negotiation to weaken the crypto in use; the other finds two inputs producing the same hash. Which pairing is correct?","options":["Negotiation = collision; matching hashes = downgrade","Negotiation = downgrade; matching hashes = collision","Both describe birthday attacks","Both describe downgrade attacks"],"correctIndex":1,"explanation":"Downgrade attacks weaken the negotiation; collision attacks defeat the hash. One attacks the handshake before data flows, the other attacks integrity math. The tell: downgrade = force the weaker cipher, collision = same digest from different inputs, birthday = the fast way to find collisions."},
  {"id":"q210","domain":"D2","family":"password-attacks","question":"Log analysis shows one source IP tried exactly three passwords - Winter2026!, Password1, and Welcome123 - against 5,000 different accounts, never a fourth attempt on any account. Which attack is this?","options":["dictionary attack","brute force","credential stuffing","password spraying"],"correctIndex":3,"explanation":"Password spraying. A few common passwords across MANY accounts, deliberately staying under lockout thresholds, is spraying. The tell: spraying = few passwords, many accounts, brute force = many passwords, one account, dictionary = wordlist-driven guessing, credential stuffing = replaying username/password pairs leaked from another site."},
  {"id":"q211","domain":"D2","family":"password-attacks","question":"An attacker fixates on a single domain-admin account and hammers it with every possible character combination, generating tens of millions of failed logins over a weekend. Which attack is this?","options":["brute force","password spraying","dictionary attack","credential stuffing"],"correctIndex":0,"explanation":"Brute force. Exhaustive guessing of every combination against ONE account is brute force, noisy and lockout-prone. The tell: brute force = everything against one account, spraying = a few passwords across many accounts, dictionary = curated wordlist, credential stuffing = reusing leaked credential pairs."},
  {"id":"q212","domain":"D2","family":"password-attacks","question":"A cracking tool works through a curated wordlist - sports teams, seasons, keyboard walks, and common substitutions like P@ssw0rd - against a stolen hash file. Which attack is this?","options":["password spraying","dictionary attack","credential stuffing","brute force"],"correctIndex":1,"explanation":"Dictionary attack. Guessing from a wordlist of likely passwords rather than every possible string is the dictionary approach. The tell: dictionary = curated wordlist of likely passwords, brute force = every possible combination, spraying = few passwords across many accounts, credential stuffing = replaying leaked pairs."},
  {"id":"q213","domain":"D2","family":"password-attacks","question":"A SOC notices a slow, quiet pattern: the same three common passwords attempted once against every account in the directory, spread over days so no account ever hits its lockout threshold. What is this attack called?","options":["brute force","dictionary attack","password spraying","credential stuffing"],"correctIndex":2,"explanation":"Password spraying. Few passwords, many accounts, deliberately under the lockout radar. The tell: spraying = few passwords across MANY accounts, brute force = many guesses against ONE account, dictionary = wordlist-based guessing, credential stuffing = replaying leaked username/password pairs."},
  {"id":"q214","domain":"D2","family":"password-attacks","question":"A trainee asks what actually separates a brute-force attack from password spraying. Which answer is correct?","options":["Brute force hammers one account with many guesses, while spraying tries a few passwords across many accounts.","They are the same attack.","Brute force uses a wordlist, while spraying uses breached credentials.","Spraying always locks out every account it touches."],"correctIndex":0,"explanation":"One-versus-many is the whole distinction. Brute force = depth against a single account; spraying = breadth across the userbase, tuned to dodge lockouts. The tell: brute force = many passwords, one account, spraying = few passwords, many accounts."},
  {"id":"q215","domain":"D2","family":"password-attacks","question":"An attacker aims a cracking tool loaded with the 10,000 most common leaked passwords at one captured password hash, trying each candidate in order. Which attack is this?","options":["password spraying","dictionary attack","brute force","credential stuffing"],"correctIndex":1,"explanation":"Dictionary attack. Guessing from a curated list of likely passwords is the dictionary method, faster than brute force but blind to anything not on the list. The tell: dictionary = wordlist of likely passwords, brute force = every possible combination, spraying = few passwords across many live accounts, credential stuffing = replaying leaked pairs."},
  {"id":"q216","domain":"D2","family":"password-attacks","question":"After a gaming site's breach, attackers take the leaked email-and-password pairs and try each pair, unchanged, against a bank's login portal - betting that users repeated their passwords. Which attack is this?","options":["password spraying","dictionary attack","brute force","credential stuffing"],"correctIndex":3,"explanation":"Credential stuffing. Replaying real username/password pairs leaked from one site against another exploits reuse, not guessing. The tell: credential stuffing = leaked PAIRS replayed elsewhere, spraying = few guessed passwords across many accounts, dictionary = wordlist guessing, brute force = exhaustive guessing on one account."},
  {"id":"q217","domain":"D2","family":"password-attacks","question":"An attacker exfiltrates the password hash database, loads it onto a GPU rig, and grinds through every possible candidate offline - no login attempts ever touch the victim's servers. Which attack is this?","options":["brute force","password spraying","credential stuffing","phishing"],"correctIndex":0,"explanation":"Brute force - the offline variety. Exhaustively attacking captured hashes on the attacker's own hardware is brute force with no lockouts or rate limits to slow it, which is why hash strength and stretching matter. The tell: brute force = try everything, offline = against stolen hashes, spraying = live logins across many accounts, credential stuffing = replayed leaked pairs."},
  {"id":"q218","domain":"D2","family":"password-attacks","question":"A defender asks why password spraying so often evades account lockout policies entirely. Which answer is correct?","options":["It only attacks accounts that have no lockout policy","Each account receives just one or two attempts, staying under every lockout threshold","It disables the lockout mechanism first","Lockout policies do not apply to password attacks"],"correctIndex":1,"explanation":"One or two guesses per account never trips a threshold set at five or ten failures. Spraying trades depth for breadth precisely to stay invisible to lockouts - detection requires correlating failures ACROSS accounts. The tell: spraying = wide and shallow by design, brute force = deep and loud on one account."},
  {"id":"q219","domain":"D2","family":"indicators","question":"A SIEM alert fires: the same account logged in successfully from New York at 9:02 a.m. and from Singapore at 9:10 a.m. No VPN explains it. Which indicator of compromise is this?","options":["concurrent session usage","account lockout","impossible travel","out-of-cycle logging"],"correctIndex":2,"explanation":"Impossible travel. Two logins from locations no human could cover in the elapsed time is the impossible-travel indicator. If both sessions were active simultaneously, concurrent session usage would also fire. The tell: impossible travel = distant logins too close in time, concurrent session usage = same account live in multiple sessions at once, account lockout = repeated failures tripping the lock, out-of-cycle logging = events at abnormal times."},
  {"id":"q220","domain":"D2","family":"indicators","question":"Reconstructing a breach timeline, analysts find the security event log simply has no entries for the two hours surrounding the suspected intrusion, though logging ran normally before and after. Which indicator is this?","options":["out-of-cycle logging","blocked content","resource inaccessibility","missing logs"],"correctIndex":3,"explanation":"Missing logs. A gap in otherwise continuous logging suggests an attacker cleared or suppressed entries to hide activity. The tell: missing logs = gaps suggesting tampering, out-of-cycle logging = entries at unusual times, resource inaccessibility = services suddenly unreachable, blocked content = filtered access attempts."},
  {"id":"q221","domain":"D2","family":"indicators","question":"A nightly batch platform never runs jobs outside its 10 p.m. to midnight window, yet fresh job-log entries appear timestamped 3:14 a.m. Which indicator is this?","options":["out-of-cycle logging","missing logs","impossible travel","concurrent session usage"],"correctIndex":0,"explanation":"Out-of-cycle logging. Log entries appearing at times when the activity should never occur point to unauthorized activity, the out-of-cycle indicator. The tell: out-of-cycle logging = entries at abnormal times, missing logs = suspicious gaps, impossible travel = geographically impossible logins, concurrent session usage = simultaneous sessions on one account."},
  {"id":"q222","domain":"D2","family":"indicators","question":"At 2 p.m., every critical file share in the company becomes unreachable for all staff simultaneously, and the storage system shows the volumes intact but access failing. Which indicator is this?","options":["resource consumption","resource inaccessibility","account lockout","blocked content"],"correctIndex":1,"explanation":"Resource inaccessibility. Services or data suddenly unavailable across the board is the inaccessibility indicator, a classic early sign of ransomware or denial of service. The tell: resource inaccessibility = resources suddenly unreachable, resource consumption = CPU/disk/bandwidth spiking abnormally, account lockout = authentication lockouts, blocked content = filtered requests."},
  {"id":"q223","domain":"D2","family":"indicators","question":"A SIEM shows the same user account actively working from three IP addresses in three different cities at the same moment, all sessions live simultaneously. Which indicator is this?","options":["impossible travel","concurrent session usage","account lockout","out-of-cycle logging"],"correctIndex":1,"explanation":"Concurrent session usage. The defining detail is simultaneous active sessions on one account. Impossible travel is about sequential logins too far apart geographically for the time elapsed. The tell: concurrent session usage = one account live in multiple places at once, impossible travel = back-to-back logins from impossible distances, account lockout = failed-attempt lockouts, out-of-cycle logging = events at abnormal times."},
  {"id":"q224","domain":"D2","family":"indicators","question":"A server's CPU and outbound bandwidth sit pinned near 100 percent for hours, far above any recorded baseline, with no scheduled job or legitimate workload to explain it. Which indicator is this?","options":["resource inaccessibility","blocked content","missing logs","resource consumption"],"correctIndex":3,"explanation":"Resource consumption. Abnormal spikes in CPU, disk, or bandwidth suggest hidden activity like cryptomining or bulk exfiltration. Inaccessibility would mean the resources stopped responding. The tell: resource consumption = usage spiking abnormally, resource inaccessibility = services suddenly unreachable, missing logs = gaps in the record, blocked content = filtered access attempts."},
  {"id":"q225","domain":"D2","family":"indicators","question":"Every morning around 6 a.m., dozens of employees find their accounts locked, and logs show overnight bursts of failed logins against each account from an unknown external host. Which indicator is this?","options":["account lockout","concurrent session usage","impossible travel","blocked content"],"correctIndex":0,"explanation":"Account lockout. Repeated failed attempts tripping the lockout policy across many users is the lockout indicator, and the overnight pattern suggests automated password guessing. The tell: account lockout = failed attempts hitting the lock threshold, concurrent session usage = simultaneous live sessions, impossible travel = geographically impossible logins, blocked content = filtered requests."},
  {"id":"q226","domain":"D2","family":"indicators","question":"Proxy logs show one workstation attempting to reach a known malware command-and-control domain forty times an hour, each attempt blocked by the filter. Nothing has gotten through - yet. Which indicator is this?","options":["blocked content","impossible travel","account lockout","missing logs"],"correctIndex":0,"explanation":"Blocked content. Repeated filtered attempts to reach known-bad destinations indicate something on that host is trying to phone home - the block worked, but the host needs investigating. The tell: blocked content = denied attempts as the signal, missing logs = suspicious gaps, impossible travel = geographic login anomalies, account lockout = failed-auth lockouts."},
  {"id":"q227","domain":"D2","family":"indicators","question":"A threat intel service alerts a company that a database matching its customer records is being offered for sale on a leak forum - the first sign anything was ever taken. Which indicator of compromise is this?","options":["resource consumption","out-of-cycle logging","published/documented data","concurrent session usage"],"correctIndex":2,"explanation":"Published/documented data. Your data appearing for sale or posted externally is direct evidence a breach already happened, however silent it was internally. The tell: published/documented = the stolen data surfaces outside, resource consumption = abnormal usage spikes, out-of-cycle logging = odd-hours events, concurrent sessions = simultaneous logins."},
  {"id":"q228","domain":"D2","family":"indicators","question":"An analyst distinguishes two server symptoms: CPU and bandwidth pinned far above baseline versus file shares that suddenly stop responding entirely. Which pairing of indicator names is correct?","options":["Both are resource inaccessibility","Pinned usage = resource inaccessibility; dead shares = resource consumption","Pinned usage = resource consumption; dead shares = resource inaccessibility","Both are out-of-cycle logging"],"correctIndex":2,"explanation":"Consumption is usage spiking; inaccessibility is resources going dark. Cryptomining and exfiltration drive consumption; ransomware and DoS cause inaccessibility. The tell: resource consumption = too much activity, resource inaccessibility = no availability at all."},
  {"id":"q229","domain":"D2","family":"indicators","question":"Change logs show firewall rules modified at 2 a.m. Sunday - a time with no approved maintenance window and no on-call activity, when no legitimate change should ever occur. Which indicator is this?","options":["account lockout","out-of-cycle logging","blocked content","impossible travel"],"correctIndex":1,"explanation":"Out-of-cycle logging. Legitimate-looking events at times they should never occur - changes outside any window - are the out-of-cycle indicator. The tell: out-of-cycle = right event, impossible time, missing logs = events erased, blocked content = filtered attempts, impossible travel = location-based anomaly."},
  {"id":"q230","domain":"D2","family":"mitigations","question":"After a single phished workstation led to domain-wide compromise, the network team divides the flat LAN into separate zones for finance, HR, servers, and guests, with ACLs controlling traffic between zones. Which mitigation is this?","options":["decommissioning","isolation","segmentation","configuration enforcement"],"correctIndex":2,"explanation":"Segmentation. Splitting the network into controlled zones limits lateral movement while everything keeps functioning. Isolation would mean fully cutting something off. The tell: segmentation = split into zones with controlled paths, isolation = completely cut off, decommissioning = retiring an asset, configuration enforcement = pushing and holding a secure config."},
  {"id":"q231","domain":"D2","family":"mitigations","question":"To stop unauthorized tools and malware from ever executing, a security team configures endpoints so that ONLY the applications on an approved list will run and everything else is blocked by default. Which mitigation is this?","options":["least privilege","configuration enforcement","patching","application allow list"],"correctIndex":3,"explanation":"Application allow list. Default-deny execution where only approved applications run is allow listing, the inverse of blocking known-bad. The tell: application allow list = only approved apps execute, least privilege = minimum rights for accounts, configuration enforcement = maintain the secure baseline, patching = fixing known vulnerabilities."},
  {"id":"q232","domain":"D2","family":"mitigations","question":"An EDR alert confirms a workstation is compromised. The responder immediately cuts it off from all network connectivity - it can reach nothing and nothing can reach it - while forensics proceeds. Which mitigation is this?","options":["isolation","segmentation","decommissioning","least privilege"],"correctIndex":0,"explanation":"Isolation. Completely severing a host's connectivity during response is isolation; segmentation would still allow controlled paths. The tell: isolation = fully cut off, segmentation = zones with controlled traffic, decommissioning = permanently retiring the asset, least privilege = minimal rights, not a containment move."},
  {"id":"q233","domain":"D2","family":"mitigations","question":"A new junior analyst receives read access to exactly the two log repositories her tasks require - no admin rights, no broad shares - so a compromise of her account exposes as little as possible. Which mitigation is this?","options":["configuration enforcement","least privilege","segmentation","patching"],"correctIndex":1,"explanation":"Least privilege. Granting only the minimum rights the job requires limits the blast radius of any account compromise. The tell: least privilege = minimum rights needed, configuration enforcement = maintaining the secure baseline, segmentation = splitting the network into zones, patching = fixing known flaws."},
  {"id":"q234","domain":"D2","family":"mitigations","question":"An aging file server is powered down, its drives are securely wiped, its certificates and accounts are revoked, and it is formally removed from the asset inventory. Which mitigation is this?","options":["isolation","patching","decommissioning","hardening"],"correctIndex":2,"explanation":"Decommissioning. Securely retiring an asset - wipe, revoke, remove from inventory - is decommissioning, which prevents forgotten systems from becoming backdoors. The tell: decommissioning = securely retire the asset, isolation = cut it off but keep it, patching = fix and keep running, hardening = tighten a live system's configuration."},
  {"id":"q235","domain":"D2","family":"mitigations","question":"A vendor releases an emergency out-of-band fix for a flaw being actively exploited in the wild, and the security team pushes it to every affected server within 24 hours, ahead of the normal monthly cycle. Which mitigation is this?","options":["segmentation","application allow list","decommissioning","patching"],"correctIndex":3,"explanation":"Patching. Applying the vendor's fix removes the vulnerability itself; for actively exploited flaws, speed beats the routine cycle. The tell: patching = eliminate the flaw, segmentation = limit where attackers can go, allow list = control what runs, decommissioning = retire the system."},
  {"id":"q236","domain":"D2","family":"mitigations","question":"Building a new web server, an engineer disables every unneeded service, closes unused ports, removes sample applications, changes all default passwords, and installs a host-based firewall before go-live. Which mitigation category covers this whole checklist?","options":["hardening","isolation","decommissioning","least privilege"],"correctIndex":0,"explanation":"Hardening. Systematically shrinking a system's attack surface - services, ports, defaults, extra software - is hardening, done before exposure. The tell: hardening = reduce the attack surface of a live system, isolation = cut it off, least privilege = minimum account rights, decommissioning = retire it."},
  {"id":"q237","domain":"D2","family":"mitigations","question":"After a scan reveals the switch management interface is reachable from every desk, the network team applies an entry permitting management access ONLY from the two administrator subnets and denying all else. Which mitigation did they apply?","options":["access control list (ACL)","application allow list","patching","isolation"],"correctIndex":0,"explanation":"ACL. Permit/deny entries restricting which sources may reach the interface are an access control list - network-level access restriction. The tell: ACL = who may connect over the network, application allow list = which programs may run, isolation = cut off entirely, patching = fix code flaws."},
  {"id":"q238","domain":"D2","family":"mitigations","question":"Whenever any server's settings drift from the approved secure baseline - a service re-enabled, a registry value changed - the management platform automatically reverts it within the hour, no ticket required. Which mitigation is this?","options":["decommissioning","configuration enforcement","segmentation","application allow list"],"correctIndex":1,"explanation":"Configuration enforcement. Continuously detecting drift and forcing systems back to the secure baseline is enforcement - hardening made permanent. The tell: configuration enforcement = the baseline reasserts itself, hardening = establishing that baseline, allow list = execution control, decommissioning = retirement."},
  {"id":"q239","domain":"D3","family":"containerization","question":"A DevOps team packages an application with just its libraries and dependencies, no guest operating system. Instances share the host's kernel, start in seconds, and a hundred of them fit where a dozen VMs used to. Which technology is this?","options":["containerization","virtualization","serverless","microservices"],"correctIndex":0,"explanation":"Containerization. Sharing the host kernel and packaging only the app plus dependencies is the container model, which is why it is lighter and faster than full VMs. The tell: containerization = shared kernel, app + deps only, virtualization = full guest OS per VM on a hypervisor, serverless = provider-run functions, microservices = an app architecture of small services."},
  {"id":"q240","domain":"D3","family":"containerization","question":"A team deploys code that runs only when an upload event fires. The cloud provider manages every server, patches everything underneath, and bills per execution; the team never sees an instance. Which cloud model is this?","options":["virtualization","containerization","serverless","microservices"],"correctIndex":2,"explanation":"Serverless. Event-triggered functions on fully provider-managed infrastructure, billed per execution, define serverless computing. The tell: serverless = no server to manage, pay per run, containerization = you still run the container hosts, virtualization = full VMs you administer, microservices = the design pattern, not the hosting model."},
  {"id":"q241","domain":"D3","family":"containerization","question":"After an outage, an operations team rebuilds its entire cloud environment in an hour by re-running declarative template files stored in version control. Every subnet, server, and policy comes back identically. Which practice made this possible?","options":["virtualization","containerization","microservices","infrastructure as code (IaC)"],"correctIndex":3,"explanation":"Infrastructure as code. Provisioning infrastructure from versioned template files makes environments repeatable, auditable, and quick to rebuild. The tell: IaC = infrastructure defined in code/templates, virtualization = VMs on a hypervisor, containerization = kernel-sharing app packages, microservices = small independent services."},
  {"id":"q242","domain":"D3","family":"containerization","question":"A hosting provider runs twelve isolated customer servers on one physical machine. Each carries its own complete guest operating system, and a hypervisor allocates the hardware among them. Which technology is this?","options":["Containerization","Serverless","Microservices","Virtualization"],"correctIndex":3,"explanation":"Virtualization. A full guest OS per instance managed by a hypervisor is classic virtualization; containers would share one kernel instead. The tell: virtualization = full guest OS per VM on a hypervisor, containerization = shared kernel, app + deps only, serverless = provider-run functions, microservices = an application design pattern."},
  {"id":"q243","domain":"D3","family":"containerization","question":"An e-commerce platform is rebuilt from one monolith into small, independently deployable services - cart, payment, catalog - that communicate over APIs and scale separately when load demands. Which design is this?","options":["Microservices","Containerization","Virtualization","Serverless"],"correctIndex":0,"explanation":"Microservices. Splitting an application into small independent services with API communication is the microservices architecture; how each service is hosted (containers, VMs, serverless) is a separate choice. The tell: microservices = the app split into independent services, containerization = the packaging technology, virtualization = full VMs, serverless = provider-managed functions."},
  {"id":"q244","domain":"D3","family":"containerization","question":"Choosing between deployment approaches, an engineer notes that one is far lighter because its packaged units share the host operating system's kernel instead of each shipping a complete guest OS. Which approach is the lighter one?","options":["Virtualization","Serverless","Containerization","IaC"],"correctIndex":2,"explanation":"Containerization. Kernel sharing is what makes containers start in seconds and pack densely; each VM's full guest OS is the weight being avoided. The tell: containerization = shares the host kernel, virtualization = full guest OS each, serverless = no units to manage at all, IaC = provisioning from code, not a runtime model."},
  {"id":"q245","domain":"D3","family":"isolation-models","question":"A defense contractor's classified analysis workstation has no network cabling, its radios physically removed, and data arrives only on inspected removable media signed in through a checkpoint. Which isolation model is this?","options":["logical segmentation","SDN","on-premises","air-gapped"],"correctIndex":3,"explanation":"Air-gapped. Physical isolation with literally no network connection is the air gap, the strongest and least convenient isolation model. The tell: air-gapped = physically disconnected, logical segmentation = separated by VLANs/subnets on shared hardware, SDN = software-controlled networking, on-premises = merely hosted in your own building."},
  {"id":"q246","domain":"D3","family":"isolation-models","question":"A network engineer separates finance, engineering, and guest traffic into different VLANs and subnets that all ride the same physical switches. Nothing is physically separate. Which isolation model is this?","options":["air-gapped","SDN","logical segmentation","decentralized"],"correctIndex":2,"explanation":"Logical segmentation. Separation enforced in configuration (VLANs, subnets) over shared physical hardware is logical, not physical, isolation. The tell: logical segmentation = VLANs/subnets on shared gear, air-gapped = physically disconnected, SDN = control plane software-driven, decentralized = distributed control, not a separation method."},
  {"id":"q247","domain":"D3","family":"isolation-models","question":"A data center team stops configuring switches box by box. Instead, a central software controller programs all forwarding behavior through APIs, separating the decision-making layer from the packet-moving layer. Which technology is this?","options":["SDN","air-gapped","logical segmentation","centralized"],"correctIndex":0,"explanation":"SDN. Software-defined networking splits the control plane (the controller's decisions) from the data plane (the switches forwarding packets) and manages the network programmatically. The tell: SDN = software controller programs the network, logical segmentation = VLAN/subnet separation, air-gapped = no connection at all, centralized = a governance style, not the networking technology."},
  {"id":"q248","domain":"D3","family":"isolation-models","question":"A global retailer routes every network configuration decision and policy change through one headquarters control point that every site depends on: consistent, but a single point of failure. Which model does this describe?","options":["Decentralized","Centralized","Air-gapped","Logical segmentation"],"correctIndex":1,"explanation":"Centralized. One control point making decisions for everything is centralization, with consistency as the upside and a single point of failure as the risk. The tell: centralized = one control point, decentralized = authority spread across independent nodes, air-gapped = physically disconnected, logical segmentation = VLAN/subnet separation."},
  {"id":"q249","domain":"D3","family":"isolation-models","question":"A blockchain network spreads decision authority across thousands of independent nodes so that no single node controls the system and no single failure stops it. Which model is this?","options":["Centralized","Air-gapped","Decentralized","SDN"],"correctIndex":2,"explanation":"Decentralized. Authority distributed across independent nodes with no single controller is decentralization, trading consistency guarantees for resilience against single-point failure. The tell: decentralized = distributed control, centralized = one control point, air-gapped = no connectivity at all, SDN = software-driven network control (which is typically centralized)."},
  {"id":"q250","domain":"D3","family":"embedded-systems","question":"A water utility's control room monitors pumping stations spread across three counties, collecting telemetry and sending commands to remote sites over wide-area links. Which term BEST names this supervisory system?","options":["IoT","RTOS","ICS","SCADA"],"correctIndex":3,"explanation":"SCADA. Supervisory control and data acquisition is the wide-area monitoring and command layer sitting above industrial processes, classic for utilities. The tell: SCADA = supervisory layer over wide areas, ICS = the industrial control systems running the physical processes themselves, IoT = internet-connected smart devices, RTOS = the timing-guaranteed operating system inside devices."},
  {"id":"q251","domain":"D3","family":"embedded-systems","question":"An engineer selecting an operating system for an airbag controller needs guaranteed response within strict deadlines every single time, not best-effort scheduling. Which OS type is required?","options":["RTOS","embedded systems","IoT","ICS"],"correctIndex":0,"explanation":"RTOS. A real-time operating system guarantees deterministic timing, which safety systems like airbags and infusion pumps demand. The tell: RTOS = guaranteed timing for real-time tasks, embedded system = the special-purpose computer itself, IoT = connected consumer devices, ICS = industrial control systems."},
  {"id":"q252","domain":"D3","family":"embedded-systems","question":"A homeowner installs smart thermostats, cameras, and video doorbells that all connect to home Wi-Fi and report to a phone app through the vendor's cloud. Which category do these devices fall under?","options":["ICS","IoT","SCADA","RTOS"],"correctIndex":1,"explanation":"IoT. Internet-connected consumer smart devices are the Internet of Things, notorious for weak default credentials and rare patches. The tell: IoT = internet-connected consumer/smart devices, ICS = industrial systems running physical processes, SCADA = the wide-area supervisory layer, RTOS = the timing-guaranteed OS inside embedded gear."},
  {"id":"q253","domain":"D3","family":"embedded-systems","question":"On a factory floor, networked controllers and sensors directly operate the assembly-line machinery - starting motors, regulating temperature, halting lines on faults. Which term BEST describes these systems?","options":["IoT","RTOS","ICS","SCADA"],"correctIndex":2,"explanation":"ICS. Industrial control systems directly run physical processes on-site; SCADA would be the supervisory layer watching many such sites over a wide area. The tell: ICS = runs the physical process, SCADA = supervises ICS across distances, IoT = consumer smart devices, RTOS = the real-time OS inside controllers."},
  {"id":"q254","domain":"D3","family":"arch-considerations","question":"An architecture review praises a design that keeps serving users while individual components fail, then heals itself back to full capacity automatically. Which architectural property is being described?","options":["availability","resilience","scalability","responsiveness"],"correctIndex":1,"explanation":"Resilience. Absorbing failure, continuing to operate, and recovering is resilience; availability is the resulting uptime, but the property described is the ability to take a punch. The tell: resilience = recover and keep serving under failure, availability = uptime now, scalability = grow with load, responsiveness = latency of responses."},
  {"id":"q255","domain":"D3","family":"arch-considerations","question":"Unable to reduce a breach risk any further with controls it can afford, a company buys a cyber insurance policy so the financial impact would land on the insurer. Which consideration does this reflect?","options":["risk transference","resilience","scalability","cost"],"correctIndex":0,"explanation":"Risk transference. Shifting the financial consequences of a risk to a third party, classically via insurance, is transference. The tell: risk transference = a third party absorbs the impact, resilience = withstand and recover, cost = the budget factor itself, scalability = growth capacity."},
  {"id":"q256","domain":"D3","family":"arch-considerations","question":"A streaming platform architect designs for a live sports final: the system must smoothly add capacity to absorb a tenfold jump in concurrent viewers, then shrink back afterward. Which architecture consideration is this?","options":["Scalability","Resilience","Responsiveness","Availability"],"correctIndex":0,"explanation":"Scalability. Growing (and shrinking) to handle changing load is scalability. The tell: scalability = grow to meet load, resilience = withstand failures and recover, responsiveness = how fast each request returns, availability = the uptime itself."},
  {"id":"q257","domain":"D3","family":"arch-considerations","question":"An SLA workshop distinguishes uptime from speed: which architecture consideration specifically concerns how quickly the system returns an answer to each user request, measured as latency?","options":["Availability","Scalability","Responsiveness","Resilience"],"correctIndex":2,"explanation":"Responsiveness. Latency of responses is responsiveness; a system can be up (available) yet still painfully slow. The tell: responsiveness = latency of the response, availability = whether it responds at all, scalability = capacity growth, resilience = surviving failures."},
  {"id":"q258","domain":"D3","family":"fail-modes","question":"During an outage, a perimeter firewall loses contact with its management platform and, per its configuration, passes ALL traffic uninspected so revenue systems stay reachable. Which failure behavior is configured?","options":["fail-open","fail-closed","fail-secure","fail-safe"],"correctIndex":0,"explanation":"Fail-open. On failure the network device permits traffic, trading security for availability. The tell: fail-open/fail-closed = the network-device pair (permit vs block on failure), fail-safe/fail-secure = the door-lock pair (unlock for people vs stay locked for assets). This is a network device that permits, so fail-open."},
  {"id":"q259","domain":"D3","family":"fail-modes","question":"When a data center loses power, the electronic maglocks on its exit doors release automatically so occupants can evacuate. The design deliberately puts human life above securing the room. Which term describes this failure mode?","options":["fail-open","fail-closed","fail-secure","fail-safe"],"correctIndex":3,"explanation":"Fail-safe. For physical locks, failing to the unlocked state to protect people is fail-safe; staying locked to protect assets would be fail-secure. The tell: fail-safe = door unlocks, life safety first, fail-secure = door stays locked, assets first, fail-open/fail-closed = the equivalent pair for network devices, not doors."},
  {"id":"q260","domain":"D3","family":"fail-modes","question":"A network access control gateway is configured so that if it cannot reach its policy server, it denies all new connections rather than risk admitting an unvetted device. Which failure behavior is this?","options":["fail-open","fail-safe","fail-closed","fail-secure"],"correctIndex":2,"explanation":"Fail-closed. A network device that blocks traffic on failure fails closed, favoring security over availability. The tell: fail-closed = network device blocks on failure, fail-open = it permits, fail-secure = a door staying locked, fail-safe = a door unlocking for evacuation. Network pair = open/closed; door pair = safe/secure."},
  {"id":"q261","domain":"D3","family":"fail-modes","question":"A bank vault's electronic lock is wired so that if building power is lost, the lock stays engaged and the vault remains sealed, protecting the contents over convenience. Which failure mode is this?","options":["Fail-safe","Fail-secure","Fail-open","Fail-closed"],"correctIndex":1,"explanation":"Fail-secure. A physical lock that stays locked on failure to protect assets fails secure; unlocking to let people out would be fail-safe. The tell: fail-secure = door stays locked, assets first, fail-safe = door unlocks, life safety first, fail-open/fail-closed = the network-device pair, not door locks."},
  {"id":"q262","domain":"D3","family":"fail-modes","question":"For a network security device, which failure mode favors availability by continuing to permit traffic through when the device can no longer enforce its rules?","options":["Fail-closed","Fail-secure","Fail-safe","Fail-open"],"correctIndex":3,"explanation":"Fail-open. Permitting traffic on failure keeps the business online at the cost of inspection. The tell: fail-open = network device permits on failure (availability), fail-closed = it blocks (security), fail-safe/fail-secure = the door-lock pair for people versus assets."},
  {"id":"q263","domain":"D3","family":"fail-modes","question":"An inline content filter is configured so that if its scanning engine crashes, the device stops forwarding packets entirely rather than pass a single unfiltered byte. Which behavior is configured?","options":["Fail-open","Fail-secure","Fail-safe","Fail-closed"],"correctIndex":3,"explanation":"Fail-closed. A network device blocking all traffic on failure fails closed, choosing security over availability. The tell: fail-closed = block on failure, fail-open = permit on failure, fail-secure/fail-safe = the physical-lock pair. Network devices pair open/closed; doors pair safe/secure."},
  {"id":"q264","domain":"D3","family":"active-passive","question":"A monitoring sensor hangs off a switch SPAN port, receiving a mirrored copy of every packet. Live traffic never actually flows through the sensor itself. Which connection method is this?","options":["active","inline","passive","tap/monitor"],"correctIndex":3,"explanation":"Tap/monitor. Receiving a mirrored copy via SPAN or a tap, outside the traffic path, is the tap/monitor method, and it makes the device inherently passive. The tell: tap/monitor = gets a copy of traffic, inline = traffic flows through the device, passive = can only observe, active = can block."},
  {"id":"q265","domain":"D3","family":"active-passive","question":"A prevention appliance is installed so that every packet between the internet and the server farm must physically pass through it, letting it drop malicious packets in real time - and making it a potential single point of failure. Which deployment is this?","options":["tap/monitor","inline","passive","active"],"correctIndex":1,"explanation":"Inline. Sitting in the traffic path so all packets flow through it is inline deployment, which is what gives a device the power to block (and the risk of becoming a bottleneck). The tell: inline = in the path, tap/monitor = mirrored copy off the path, active = the blocking role inline enables, passive = observe-only."},
  {"id":"q266","domain":"D3","family":"active-passive","question":"In a design document, a sensor is labeled with the role meaning it can observe and alert on traffic but has no ability whatsoever to block or modify it. Which term is this?","options":["inline","tap/monitor","active","passive"],"correctIndex":3,"explanation":"Passive. Observation without the ability to intervene is the passive role, typical of an IDS on a SPAN port. The tell: passive = watch and alert only, active = can block or alter, inline = the in-path placement, tap/monitor = the mirrored-copy placement."},
  {"id":"q267","domain":"D3","family":"active-passive","question":"A design review labels each security device by role: one can drop or rewrite packets in real time, while another can only watch and report. Which term describes the device that can act on traffic?","options":["Active","Passive","Inline","Tap"],"correctIndex":0,"explanation":"Active. The ability to block or modify traffic is the active role; placement (inline) is what usually makes it possible. The tell: active = can block/alter, passive = observe only, inline = the in-path placement, tap = the mirrored-copy placement."},
  {"id":"q268","domain":"D3","family":"active-passive","question":"A security appliance is cabled between two network segments so that every production packet physically flows through it on the way to the other side. Which placement term describes this?","options":["Tap","Inline","Passive","Active"],"correctIndex":1,"explanation":"Inline. In-path cabling where traffic flows through the device is inline placement, the prerequisite for blocking (and a potential bottleneck). The tell: inline = traffic passes through it, tap = it receives a copy, active/passive = what the device can DO, not where it sits."},
  {"id":"q269","domain":"D3","family":"active-passive","question":"A traffic analyzer receives only a mirrored copy of packets from a SPAN session and by design can never drop or alter a single packet. In terms of its ability to act on traffic, its role is best described as what?","options":["Inline","Active","Tap","Passive"],"correctIndex":3,"explanation":"Passive. Observation without intervention is the passive role; the SPAN feed is the tap/monitor placement that enforces it. The tell: passive = watch only, active = can block, tap = the copy-of-traffic placement, inline = the in-path placement."},
  {"id":"q270","domain":"D3","family":"jump-proxy","question":"To reach production database servers, administrators must first SSH into one hardened, heavily logged gateway host and connect onward from there; direct admin connections are blocked. Which system is the gateway host?","options":["proxy server","jump server","reverse proxy","forward proxy"],"correctIndex":1,"explanation":"Jump server. A hardened admin pivot host that you connect THROUGH to manage internal systems is a jump server (jump box). A proxy brokers application requests, not admin sessions. The tell: jump server = admin access pivot, proxy = request broker/filter, reverse proxy = fronts servers for inbound clients, forward proxy = fronts clients going outbound."},
  {"id":"q271","domain":"D3","family":"jump-proxy","question":"An appliance sits in front of a company's web farm, accepts every inbound client request, filters them, caches popular content, and hides the real servers' internal addresses from the internet. Which system is this?","options":["reverse proxy","jump server","forward proxy","load balancer"],"correctIndex":0,"explanation":"Reverse proxy. Fronting servers to handle inbound client requests, with caching and shielding, is the reverse proxy role. A pure load balancer distributes load but the filtering/caching/shielding described is proxy work. The tell: reverse proxy = represents the SERVERS to inbound clients, forward proxy = represents the CLIENTS going outbound, jump server = admin pivot host, load balancer = distributes traffic across servers."},
  {"id":"q272","domain":"D3","family":"jump-proxy","question":"All employee web browsing is routed through one internal device that enforces the acceptable use policy, filters URLs, and caches common pages on the users' behalf before requests leave for the internet. Which system is this?","options":["jump server","reverse proxy","forward proxy","load balancer"],"correctIndex":2,"explanation":"Forward proxy. Handling internal clients' outbound requests with filtering and caching is the forward proxy role. The tell: forward proxy = outbound, acts for the clients, reverse proxy = inbound, acts for the servers, jump server = admin gateway host, load balancer = spreads load across servers."},
  {"id":"q273","domain":"D3","family":"jump-proxy","question":"Firewall rules block all direct management sessions to the server zone. Administrators must first log into one hardened, MFA-protected gateway host, and only from there can they reach the servers. Which system is the gateway?","options":["Forward proxy","Jump server","Reverse proxy","Proxy server"],"correctIndex":1,"explanation":"Jump server. A controlled, hardened host that admin sessions pivot through is a jump server; proxies broker application traffic, not administrative access. The tell: jump server = admin pivot into a protected zone, forward proxy = outbound client requests, reverse proxy = inbound requests to servers, proxy server = the request-broker category."},
  {"id":"q274","domain":"D3","family":"jump-proxy","question":"Which system's defining purpose is to act as a secure administrative pivot: one controlled, auditable entry point through which operators reach an isolated management network?","options":["Reverse proxy","Proxy server","Forward proxy","Jump server"],"correctIndex":3,"explanation":"Jump server. Admin access consolidation with hardening and logging is the jump server's whole reason to exist. The tell: jump server = the admin choke point, proxy server = brokers/filters application requests, forward proxy = for outbound clients, reverse proxy = for inbound service traffic."},
  {"id":"q275","domain":"D3","family":"jump-proxy","question":"A hardening guide calls for a single fortified intermediary host, sometimes called a bastion host, to serve as the one controlled choke point for administrative access into a segmented network. Which term names it?","options":["Jump server","Proxy server","Forward proxy","Reverse proxy"],"correctIndex":0,"explanation":"Jump server. Bastion host and jump box are the common aliases; the function is a hardened admin gateway. The tell: jump server = hardened admin entry point, proxy server = application request broker, forward proxy = client-side broker, reverse proxy = server-side broker."},
  {"id":"q276","domain":"D3","family":"ips-ids","question":"A security engineer wants the detection capability of the existing IDS but needs malicious packets actually stopped before they reach hosts, so she deploys the same engine inline with blocking enabled. Which control has she deployed?","options":["IDS","IPS","HIDS","HIPS"],"correctIndex":1,"explanation":"IPS. Same detection, different posture: inline placement plus the ability to drop packets turns detection into prevention. The tell: IPS = inline, detects AND blocks, IDS = out of band, detects and alerts only, HIDS/HIPS = the same pair implemented on a single host."},
  {"id":"q277","domain":"D3","family":"ips-ids","question":"A sensor attached to a SPAN port watches a copy of network traffic and raises alerts on suspicious patterns. Being out of band, it cannot stop anything it sees. Which control is this?","options":["IPS","HIPS","HIDS","IDS"],"correctIndex":3,"explanation":"IDS. Network-wide detection from a mirrored copy, alert-only, is the intrusion detection system. The tell: IDS = passive, out of band, alerts only, IPS = inline and blocks, HIDS = detection on one host, HIPS = blocking on one host."},
  {"id":"q278","domain":"D3","family":"ips-ids","question":"A HIPS agent can block attacks locally on its host. Which control likewise runs on a single host but only monitors and alerts, taking no blocking action?","options":["IPS","IDS","HIDS","HIPS"],"correctIndex":2,"explanation":"HIDS. Host-based intrusion detection watches one machine and alerts, while HIPS adds local blocking. The tell: HIDS = one host, detect only, HIPS = one host, detect and block, IDS/IPS = the same split at the network level."},
  {"id":"q279","domain":"D3","family":"ips-ids","question":"A sensor analyzes copies of network packets against attack signatures and raises alerts on matches, but by design it has no path or ability to drop or reset any connection. Which control is this?","options":["HIDS","IPS","IDS","HIPS"],"correctIndex":2,"explanation":"IDS. Network-level detection from copied traffic with alerting only is the intrusion detection system. The tell: IDS = out of band, alerts only, IPS = inline and blocks, HIDS = the detect-only version on one host, HIPS = the blocking version on one host."},
  {"id":"q280","domain":"D3","family":"ips-ids","question":"Deployed inline at the network edge, a control inspects every passing packet and automatically drops or resets connections matching malicious signatures before they touch internal hosts. Which control is it?","options":["IPS","IDS","HIDS","HIPS"],"correctIndex":0,"explanation":"IPS. Inline placement plus automatic blocking is intrusion prevention. The tell: IPS = inline, detects AND blocks, IDS = passive detection and alerts, HIDS/HIPS = the host-based equivalents of each."},
  {"id":"q281","domain":"D3","family":"ips-ids","question":"An interviewer notes that IDS and IPS share the same detection methods, then asks the candidate to state the core difference. Which statement is correct?","options":["The IDS blocks traffic inline while the IPS only alerts","Both are inline but only the IDS can modify packets","The IDS runs only on hosts while the IPS runs only on networks","The IPS is placed inline and can block traffic while the IDS is out of band and only alerts"],"correctIndex":3,"explanation":"IPS = inline and blocking; IDS = out of band and alerting. Same detection engine, different placement and response. The tell: the P is prevention (active, inline), the D is detection (passive, copy of traffic)."},
  {"id":"q282","domain":"D3","family":"firewalls","question":"A security team needs to protect one public web application specifically: inspecting HTTP requests and blocking SQL injection and cross-site scripting before they reach the app. Which device fits BEST?","options":["NGFW","WAF","UTM","Layer 4 firewall"],"correctIndex":1,"explanation":"WAF. A web application firewall specializes in HTTP-layer inspection for web attacks like SQLi and XSS in front of a specific application. An NGFW is broader network protection, not app-request-focused. The tell: WAF = protects a web app from HTTP attacks, NGFW = application-aware network firewall, UTM = all-in-one security box, Layer 4 = ports and IPs only."},
  {"id":"q283","domain":"D3","family":"firewalls","question":"A small business with no dedicated security staff wants one appliance combining firewall, antivirus, intrusion prevention, and content filtering in a single managed box. Which device type is this?","options":["UTM","WAF","NGFW","Layer 7 firewall"],"correctIndex":0,"explanation":"UTM. Unified threat management bundles many security functions into one appliance, trading best-of-breed depth for simplicity, a fit for small shops. The tell: UTM = all-in-one bundle, NGFW = advanced firewall with app awareness, WAF = web-app HTTP protection, Layer 7 firewall = the application-aware capability itself."},
  {"id":"q284","domain":"D3","family":"firewalls","question":"An architect notes the current firewall filters only by port and IP address. The replacement must recognize applications regardless of port, do deep packet inspection, and tie rules to user identity. Which firewall type meets this?","options":["WAF","UTM","NGFW","Layer 4 firewall"],"correctIndex":2,"explanation":"NGFW. Application awareness, deep packet inspection, and identity integration are the next-generation firewall's defining upgrades over Layer 4 filtering. The tell: NGFW = app-aware, DPI, identity rules, Layer 4 = ports and IPs only, WAF = HTTP protection for one web app, UTM = many functions in one box."},
  {"id":"q285","domain":"D3","family":"firewalls","question":"A legacy firewall makes allow/deny decisions purely on source and destination IP addresses and TCP/UDP port numbers, completely blind to the application data inside the packets. At which layer does it operate?","options":["Layer 7","Layer 4","WAF","NGFW"],"correctIndex":1,"explanation":"Layer 4. Ports and IP addresses are transport-layer attributes, so port/IP filtering is Layer 4 firewalling. The tell: Layer 4 = ports and IPs only, Layer 7 = sees the application payload, NGFW = the product class that adds Layer 7 awareness, WAF = HTTP-specific protection for web apps."},
  {"id":"q286","domain":"D3","family":"firewalls","question":"A next-generation firewall identifies and controls specific applications - distinguishing a chat client from a file-sharing tool on the same port - by inspecting the actual payload. At which layer does this content-aware filtering happen?","options":["UTM","Layer 4","WAF","Layer 7"],"correctIndex":3,"explanation":"Layer 7. Recognizing applications by payload content is application-layer inspection, the Layer 7 capability that defines NGFWs. The tell: Layer 7 = application-content awareness, Layer 4 = ports and IPs, UTM = the all-in-one appliance category, WAF = web-app HTTP protection."},
  {"id":"q287","domain":"D3","family":"port-auth","question":"A company requires every device plugging into an office wall jack to authenticate before the switch port passes any traffic; unauthenticated devices get nothing. Which standard provides this port-based control?","options":["EAP","802.1X","PEAP","EAP-TLS"],"correctIndex":1,"explanation":"802.1X. Port-based network access control that blocks the port until authentication succeeds is 802.1X, on both wired switches and Wi-Fi. The tell: 802.1X = the port-gatekeeping standard, EAP = the authentication framework it transports, PEAP/EAP-TLS = specific methods inside that framework."},
  {"id":"q288","domain":"D3","family":"port-auth","question":"A network engineer explains that 802.1X does not itself define how credentials are checked; it merely transports a flexible authentication framework inside which methods like PEAP and EAP-TLS run. What is that framework?","options":["802.1X","PEAP","EAP","EAP-TLS"],"correctIndex":2,"explanation":"EAP. The Extensible Authentication Protocol is the framework 802.1X carries; PEAP and EAP-TLS are methods implemented within EAP. The tell: EAP = the framework, 802.1X = the port-control standard that transports it, PEAP = EAP inside a TLS tunnel with server-side cert, EAP-TLS = certificate authentication on both sides."},
  {"id":"q289","domain":"D3","family":"port-auth","question":"A visitor's laptop plugged into a conference-room jack gets no network access at all until it authenticates. The credential exchange itself rides inside a gatekeeping standard that holds the switch port closed. Which standard is the gate?","options":["EAP","EAP-TLS","802.1X","PEAP"],"correctIndex":2,"explanation":"802.1X. Port-based access control that keeps the port shut until authentication succeeds is 802.1X; EAP is the framework it carries. The tell: 802.1X = the port gate, EAP = the authentication framework inside it, PEAP/EAP-TLS = specific EAP methods."},
  {"id":"q290","domain":"D3","family":"port-auth","question":"A wireless engineer describes EAP-TLS and PEAP as specific implementations chosen within a broader, pluggable authentication framework. Which framework are they implementations of?","options":["EAP","802.1X","EAP-TLS","PEAP"],"correctIndex":0,"explanation":"EAP. The Extensible Authentication Protocol is deliberately a framework; PEAP and EAP-TLS are methods plugged into it. The tell: EAP = the extensible framework, 802.1X = the port-control standard that transports EAP, EAP-TLS = mutual certificate authentication, PEAP = EAP tunneled in server-side TLS."},
  {"id":"q291","domain":"D3","family":"secure-tunnels","question":"Remote employees reach internal web applications through their browsers over TCP port 443 with nothing extra installed; the encryption is the same technology that protects HTTPS. Which remote-access technology is this?","options":["IPSec","TLS VPN","SD-WAN","SASE"],"correctIndex":1,"explanation":"TLS VPN. Browser-based access over 443 using TLS, with no thick client, is the TLS (SSL) VPN model, easy to deploy and firewall-friendly. The tell: TLS VPN = browser, port 443, no client install, IPSec = network-layer tunnels typically with a client or between gateways, SD-WAN = multi-link traffic steering, SASE = cloud-delivered network plus security."},
  {"id":"q292","domain":"D3","family":"secure-tunnels","question":"Two data centers are joined by a permanent site-to-site encrypted tunnel at the network layer, using ESP to provide confidentiality and integrity for everything crossing it. Which technology is this?","options":["TLS VPN","SD-WAN","SASE","IPSec"],"correctIndex":3,"explanation":"IPSec. Network-layer tunneling with ESP for encryption and integrity is IPSec, the standard for site-to-site links. The tell: IPSec = Layer 3 tunnels, ESP/AH, site-to-site, TLS VPN = browser-based application access, SD-WAN = steering across multiple links, SASE = the cloud-delivered combination of both worlds."},
  {"id":"q293","domain":"D3","family":"secure-tunnels","question":"A retail chain's branches each have MPLS, broadband, and LTE links. An overlay controller steers each application's traffic across whichever link currently offers the best performance and cost. Which technology is this?","options":["SD-WAN","SASE","IPSec","TLS VPN"],"correctIndex":0,"explanation":"SD-WAN. Software-defined steering of branch traffic across multiple transport links for performance and cost is SD-WAN's core job. The tell: SD-WAN = dynamic multi-link traffic steering, SASE = SD-WAN plus cloud-delivered security services, IPSec = the encrypted tunnel itself, TLS VPN = browser-based remote access."},
  {"id":"q294","domain":"D3","family":"secure-tunnels","question":"A company replaces its patchwork of VPNs and web filters with one cloud-delivered service combining SD-WAN connectivity with zero-trust network access, secure web gateway, and CASB functions. Which model has it adopted?","options":["SD-WAN","IPSec","SASE","TLS VPN"],"correctIndex":2,"explanation":"SASE. Secure access service edge merges SD-WAN networking with a stack of cloud-delivered security services into one offering. The tell: SASE = networking plus security from the cloud, SD-WAN = the networking piece alone, IPSec = the tunnel protocol, TLS VPN = browser-based access."},
  {"id":"q295","domain":"D3","family":"secure-tunnels","question":"Which tunneling technology operates at the network layer, using AH and ESP to authenticate and encrypt traffic, making it the classic choice for permanent site-to-site links between offices?","options":["TLS VPN","IPSec","SD-WAN","SASE"],"correctIndex":1,"explanation":"IPSec. AH and ESP at Layer 3 are IPSec's building blocks, and site-to-site tunnels are its home turf. The tell: IPSec = network-layer AH/ESP tunnels, TLS VPN = browser-based access over 443, SD-WAN = multi-link steering overlay, SASE = cloud-delivered networking plus security."},
  {"id":"q296","domain":"D3","family":"secure-tunnels","question":"A study guide asks for the general term covering any technology that builds an encrypted tunnel across an untrusted network so remote traffic behaves as if it were on the private LAN. Which term is it?","options":["SD-WAN","SASE","IPSec","VPN"],"correctIndex":3,"explanation":"VPN. Virtual private network is the umbrella term; IPSec and TLS are particular ways to build one. The tell: VPN = the general encrypted-tunnel concept, IPSec = one implementation at Layer 3, SD-WAN = traffic steering across links, SASE = the cloud-delivered service bundle."},
  {"id":"q297","domain":"D3","family":"secure-tunnels","question":"A retail chain drops its expensive dedicated circuits and adopts a centrally managed, software-defined overlay that applies traffic policies across cheap internet links to every store. No cloud-delivered security services are included. Which technology is this?","options":["IPSec","SASE","SD-WAN","VPN"],"correctIndex":2,"explanation":"SD-WAN. A software-defined overlay steering traffic across commodity links is SD-WAN; adding cloud security services on top would make it SASE, which the stem explicitly excludes. The tell: SD-WAN = the networking overlay alone, SASE = SD-WAN plus cloud security stack, IPSec = the tunnel protocol, VPN = the general tunnel concept."},
  {"id":"q298","domain":"D3","family":"data-classification","question":"A hospital's data inventory includes patient records governed by HIPAA and cardholder data governed by PCI DSS. External law and industry mandates dictate exactly how both must be stored, transmitted, and retained. Which data type BEST describes these records?","options":["regulated","trade secret","intellectual property","financial"],"correctIndex":0,"explanation":"Regulated. When external law or mandated standards dictate handling, the data is regulated data, whatever else it may also be. The tell: regulated = external rules dictate handling, trade secret = secret business advantage, intellectual property = creations you own rights to, financial = money-related records as a content category."},
  {"id":"q299","domain":"D3","family":"data-classification","question":"A beverage company's most valuable asset is its unpatented secret formula. It is kept internal precisely because publishing or patenting it would let rivals copy the recipe when protection expires. How is this information best classified?","options":["financial","intellectual property","trade secret","regulated"],"correctIndex":2,"explanation":"Trade secret. Competitive-advantage information kept deliberately secret, and unpatented so it never expires into the public domain, is a trade secret. The tell: trade secret = secret sauce guarded internally, intellectual property = the broader owned-creations category including patents that are published, regulated = law dictates handling, financial = monetary records."},
  {"id":"q300","domain":"D3","family":"data-classification","question":"During a classification review, a marketing brochure already published on the company website is assessed: its release could cause no harm whatsoever. Which classification applies?","options":["confidential","public","restricted","critical"],"correctIndex":1,"explanation":"Public. Information whose disclosure causes no harm needs no protection and is classified public. The tell: public = no harm if released, confidential = harm if released, restricted = tightly limited audience, critical = severe damage if lost or disclosed."},
  {"id":"q301","domain":"D3","family":"data-classification","question":"A software company's legal team inventories the patents on its algorithms and the copyrights on its source code, all legally protecting its developers' creations. Which data type BEST describes these assets?","options":["regulated","intellectual property","trade secret","financial"],"correctIndex":1,"explanation":"Intellectual property. Patents and copyrights are legal protections over creations, the IP category. A trade secret would be kept unregistered and hidden instead. The tell: intellectual property = legally protected creations (patents, copyrights), trade secret = valuable because it stays secret, regulated = external law dictates handling, financial = monetary records."},
  {"id":"q302","domain":"D3","family":"data-classification","question":"A business impact analysis marks one dataset as so essential that losing it would halt the organization's core functions outright. Which classification applies?","options":["confidential","public","critical","restricted"],"correctIndex":2,"explanation":"Critical. Data whose loss stops the business cold is critical, a rating about operational dependence, not secrecy. The tell: critical = the business halts without it, confidential = harm if disclosed, restricted = narrowest allowed audience, public = no harm if released."},
  {"id":"q303","domain":"D3","family":"data-states","question":"An analytics engine loads millions of customer records into server RAM and actively computes across them. A security review notes this is the stage where encryption is hardest to maintain, since the CPU must see plaintext. Which data state is this?","options":["at rest","in transit","in use","data sovereignty"],"correctIndex":2,"explanation":"In use. Data being actively processed in memory is in use, the hardest state to protect (secure enclaves exist for exactly this). The tell: in use = being processed in RAM/CPU, at rest = sitting in storage, in transit = crossing a network, data sovereignty = which country's laws apply."},
  {"id":"q304","domain":"D3","family":"data-states","question":"A cloud customer discovers that because its backups are stored in a Frankfurt region, German and EU law govern that data regardless of where the company is headquartered. Which concept is at work?","options":["in transit","geolocation","data sovereignty","at rest"],"correctIndex":2,"explanation":"Data sovereignty. Data is subject to the laws of the country where it physically resides, a core consideration when picking cloud regions. The tell: data sovereignty = local law follows the storage location, geolocation = determining where data or users physically are, at rest/in transit = protection states, not legal jurisdiction."},
  {"id":"q305","domain":"D3","family":"data-states","question":"Customer records stream across the internet from a branch office to headquarters, wrapped in TLS for the journey. Which data state are the records in while on the wire?","options":["at rest","in transit","in use","data sovereignty"],"correctIndex":1,"explanation":"In transit. Data crossing a network is in transit, which is exactly what TLS protects. The tell: in transit = moving across a network (TLS/IPSec), at rest = sitting in storage (disk encryption), in use = active in memory, data sovereignty = whose laws govern it."},
  {"id":"q306","domain":"D3","family":"data-states","question":"An inventory notes files sitting encrypted on a server's hard drive: not being read, not being sent anywhere, just stored. Which data state describes them?","options":["at rest","in transit","in use","geolocation"],"correctIndex":0,"explanation":"At rest. Stored and idle is at rest, the state disk and volume encryption protect. The tell: at rest = in storage, in transit = on the network, in use = loaded in memory being processed, geolocation = determining physical location, not a data state."},
  {"id":"q307","domain":"D3","family":"data-protection","question":"A hospital's billing system replaces each patient's national ID with a random substitute value before storing it. The real ID can be recovered only by querying a separate, tightly guarded vault. Which data protection method is this?","options":["encryption","tokenization","masking","hashing"],"correctIndex":1,"explanation":"Tokenization. A substitute value with vault-based lookup to the original is tokenization; no mathematical relationship links token to real ID, unlike encryption. The tell: tokenization = vault maps token back to the value, encryption = mathematically reversible with a key, masking = partial display, not recoverable, hashing = one-way, never recoverable."},
  {"id":"q308","domain":"D3","family":"data-protection","question":"A call-center application shows agents a customer's card number as XXXX-XXXX-XXXX-1234. The hidden digits are not present in the display layer at all, so no agent action can reveal them. Which data protection technique is shown?","options":["masking","tokenization","obfuscation","encryption"],"correctIndex":0,"explanation":"Masking. Displaying only a partial value with the remainder irrecoverably hidden is data masking, standard for support screens. The tell: masking = partial display (XXXX-1234), tokenization = substitute value recoverable via a vault, encryption = reversible with a key, obfuscation = the umbrella category these all belong to."},
  {"id":"q309","domain":"D3","family":"data-protection","question":"A streaming service checks each viewer's location and refuses to serve licensed content to IP addresses outside approved countries, allowing or denying purely by where the user is. Which data protection method is this?","options":["permission restrictions","geographic restrictions","masking","tokenization"],"correctIndex":1,"explanation":"Geographic restrictions. Access decisions keyed to the user's physical location are geo-restrictions (geofencing). The tell: geographic restrictions = where you are decides access, permission restrictions = who you are and your rights decide, masking = partial display of values, tokenization = vault-mapped substitutes."},
  {"id":"q310","domain":"D3","family":"data-protection","question":"To let users confirm a downloaded installer was not tampered with, the vendor publishes a one-way fingerprint of the file; comparing fingerprints proves integrity, and the fingerprint cannot be reversed into the file. Which method is this?","options":["hashing","encryption","masking","tokenization"],"correctIndex":0,"explanation":"Hashing. A one-way integrity fingerprint that cannot be reversed is a hash; matching digests prove the file is unaltered. The tell: hashing = one-way integrity check, encryption = reversible confidentiality, masking = hiding displayed digits, tokenization = substitute values via a vault."},
  {"id":"q311","domain":"D3","family":"load-balancing","question":"A device in front of a pool of identical web servers assigns each incoming user request to one of them, raising total throughput and keeping any single server from being overwhelmed during peaks. Which technique is the device performing?","options":["clustering","load balancing","active-passive configuration","active-active configuration"],"correctIndex":1,"explanation":"Load balancing. Distributing incoming requests across a server pool for throughput and headroom is load balancing. The tell: load balancing = spread requests across servers, clustering = servers grouped to act as one system with failover, active-active/active-passive = whether all nodes or only one carry load."},
  {"id":"q312","domain":"D3","family":"load-balancing","question":"Several database nodes are grouped so they present to applications as one system. When one node dies mid-transaction, another instantly assumes its role and clients never notice. Which technique is this?","options":["load balancing","active-active configuration","active-passive configuration","clustering"],"correctIndex":3,"explanation":"Clustering. Nodes grouped to act as a single system with seamless failover form a cluster; the emphasis is unified identity and takeover, not request distribution. The tell: clustering = many nodes, one logical system, load balancing = distributing requests, active-active/active-passive = the load-sharing modes a cluster can run in."},
  {"id":"q313","domain":"D3","family":"load-balancing","question":"In a high-availability firewall pair, the primary node handles 100 percent of traffic while an identical standby sits idle, ready to take over only if the primary fails. Which configuration is this?","options":["active-active configuration","active-passive configuration","load balancing","clustering"],"correctIndex":1,"explanation":"Active-passive. One node works, the twin waits; capacity is idle but failover is simple and predictable. Active-active would have both nodes sharing load. The tell: active-passive = standby waits idle, active-active = all nodes carry traffic simultaneously, load balancing = the distribution function, clustering = the grouping itself."},
  {"id":"q314","domain":"D3","family":"load-balancing","question":"Two identical VPN concentrators both carry live user traffic simultaneously, sharing the load. When one fails, the survivor absorbs the full load until its twin returns. Which configuration is this?","options":["active-passive configuration","active-active configuration","clustering","load balancing"],"correctIndex":1,"explanation":"Active-active. Both nodes working at once, with the survivor absorbing everything on a failure, is active-active: full capacity use, but each node must be sized for the whole load. The tell: active-active = all nodes live, active-passive = one works while one waits, clustering = the grouping mechanism, load balancing = the distribution function."},
  {"id":"q315","domain":"D3","family":"load-balancing","question":"A high-availability pair is documented as active-passive. How does the second node behave during normal operation?","options":["It distributes incoming requests across a server pool.","It groups with the first node to act as one system.","It shares the live traffic load with the first node.","It sits idle on standby and takes over only if the first node fails."],"correctIndex":3,"explanation":"The passive node waits. It carries nothing until the active node fails, then assumes the load: simple and predictable, at the cost of idle capacity. The tell: active-passive = hot standby doing nothing, active-active = both nodes working, load balancing = spreading requests, clustering = acting as one system."},
  {"id":"q316","domain":"D3","family":"load-balancing","question":"An architect asks for the technique whose purpose is failover and high availability: multiple nodes joined to behave as a single system, rather than a device merely spreading requests for throughput. Which technique is it?","options":["load balancing","clustering","active-active configuration","active-passive configuration"],"correctIndex":1,"explanation":"Clustering. Joining nodes into one logical system for failover is clustering; load balancing distributes work but the pool members stay individual systems. The tell: clustering = one logical system, high availability, load balancing = request distribution for throughput, active-active/active-passive = the modes a cluster or pair can run in."},
  {"id":"q317","domain":"D3","family":"sites","question":"An online retailer's continuity requirement says order processing must resume within 15 minutes of losing a data center. It maintains a second facility with live, fully configured servers and continuously synchronized data, ready for near-immediate cutover. Which recovery site is this?","options":["hot site","warm site","cold site","geographic dispersion"],"correctIndex":0,"explanation":"Hot site. Running systems plus continuously current data means failover in minutes, the hot site's defining (and most expensive) promise. The tell: hot = live systems, synced data, minutes, warm = equipment ready but data must be restored, hours, cold = empty powered space, days to weeks, geographic dispersion = distance between facilities."},
  {"id":"q318","domain":"D3","family":"sites","question":"A nonprofit with a tiny budget decides it can tolerate two weeks of downtime after a disaster. It leases an empty facility offering power, cooling, and floor space only - no hardware, no data, nothing installed. Which site type is this?","options":["hot site","warm site","geographic dispersion","cold site"],"correctIndex":3,"explanation":"Cold site. A powered empty shell that everything must be brought into is a cold site: cheapest option, slowest recovery. The tell: cold = space and power only, days to weeks, warm = hardware waiting but data restore needed, hot = running and synchronized, geographic dispersion = the distance principle, not a site type."},
  {"id":"q319","domain":"D3","family":"sites","question":"A company's recovery facility is stocked with racked servers, network gear, and live connectivity, but the systems hold no current data; backups must be restored first, making recovery a matter of hours. Which site type is this?","options":["hot site","warm site","cold site","geographic dispersion"],"correctIndex":1,"explanation":"Warm site. Equipment ready, data not loaded, recovery in hours: the warm site is the middle option on cost and speed. The tell: warm = hardware ready, restore data first, hours, hot = synchronized and running, minutes, cold = empty shell, weeks, geographic dispersion = spacing sites apart."},
  {"id":"q320","domain":"D3","family":"sites","question":"A continuity planner insists the new backup facility be located hundreds of miles from headquarters specifically so one hurricane, earthquake, or regional grid failure cannot take out both facilities at once. Which recovery concept is this?","options":["hot site","warm site","geographic dispersion","cold site"],"correctIndex":2,"explanation":"Geographic dispersion. Separating facilities beyond a single disaster's reach is dispersion, a principle that applies whatever the site temperature. The tell: geographic dispersion = distance defeats regional disasters, hot/warm/cold = how ready the site is, not where it sits."},
  {"id":"q321","domain":"D3","family":"sites","question":"Two firms compare recovery postures. Firm A's facility has racks, connectivity, and hardware waiting, though no current data loaded; Firm B's is only a powered empty shell. Which type is Firm A's facility?","options":["cold site","hot site","geographic dispersion","warm site"],"correctIndex":3,"explanation":"Warm site. Hardware and connectivity in place with data still to restore is warm; Firm B's empty shell is the cold site. The tell: warm = equipped, awaiting data, cold = empty space, hot = running with synchronized data, geographic dispersion = the distance principle."},
  {"id":"q322","domain":"D3","family":"sites","question":"An auditor's report labels a facility a hot site. Which statement best describes what the auditor found?","options":["Fully equipped and running with synchronized data, failover in minutes","Hardware and connectivity ready but data must be restored first, recovery in hours","Only powered floor space, everything must be brought in, recovery in days to weeks","Backup facilities spread far apart to survive a regional disaster"],"correctIndex":0,"explanation":"Hot = running now. Live systems with continuously synchronized data and failover in minutes define the hot site. The tell: hot = minutes, warm = hours, cold = days to weeks, and dispersion is about distance, not readiness."},
  {"id":"q323","domain":"D3","family":"sites","question":"A trading firm calculates that even minutes of lost transactions would be catastrophic, so it pays a steep premium for a standby facility whose systems stay powered on with data kept continuously current with production. Which site did it choose?","options":["cold site","warm site","hot site","geographic dispersion"],"correctIndex":2,"explanation":"Hot site. Near-zero data loss and instant readiness only come from a hot site's live, synchronized systems, which is what the premium buys. The tell: hot = powered on, continuously current, warm = ready hardware, stale data, cold = empty space, geographic dispersion = distance between sites."},
  {"id":"q324","domain":"D3","family":"sites","question":"A regional insurer rules out a continuously synchronized recovery facility as unaffordable, but also cannot accept weeks of downtime buying equipment after a disaster. It selects the option in the middle on both cost and recovery time. Which site type is this?","options":["cold site","warm site","hot site","geographic dispersion"],"correctIndex":1,"explanation":"Warm site. Explicitly the compromise: cheaper than hot, far faster than cold, recovery in hours once backups are restored. The tell: warm = the middle path, hot = expensive and instant, cold = cheap and slow, geographic dispersion = a siting principle, not a readiness tier."},
  {"id":"q325","domain":"D3","family":"sites","question":"After declaring a disaster, a company arrives at its alternate facility to find bare floor space. Staff must purchase and install servers and network gear, then restore everything from offsite media, before any operations resume. Which site type does it operate?","options":["hot site","warm site","geographic dispersion","cold site"],"correctIndex":3,"explanation":"Cold site. Bring-everything-yourself recovery measured in days to weeks is the cold site experience; the low lease cost is paid back in downtime. The tell: cold = empty shell, longest recovery, warm = gear waiting, hot = running and current, geographic dispersion = how far apart sites are."},
  {"id":"q326","domain":"D3","family":"sites","question":"A cloud architect deliberately places the primary region and the replica region several hundred miles apart so that no single earthquake, flood, or grid collapse can destroy both. Which principle is being applied?","options":["geographic dispersion","hot site","warm site","cold site"],"correctIndex":0,"explanation":"Geographic dispersion. Distance between facilities is the control; readiness level is a separate decision. The tell: geographic dispersion = spacing defeats regional disasters, hot/warm/cold = readiness tiers of the site itself."},
  {"id":"q327","domain":"D3","family":"sites","question":"A DR consultant describes a recovery option offering only conditioned floor space, electrical power, and cooling: no servers, no network gear, no data on hand. Getting operations running there after a disaster takes days to weeks. Which site type is this?","options":["hot","warm","cold","geographic dispersion"],"correctIndex":2,"explanation":"Cold. Space, power, and cooling only, with everything else still to procure, is the cold site: lowest cost, longest recovery. The tell: cold = empty shell, days to weeks, warm = equipment ready, restore data, hours, hot = live and synchronized, minutes, geographic dispersion = distance, not readiness."},
  {"id":"q328","domain":"D3","family":"sites","question":"A vendor pitches your company a cold site contract for disaster recovery. Which expectation should you set with management before signing?","options":["It is bare space with power and cooling; you must bring in and configure all hardware and data, so recovery takes days to weeks.","It has racked hardware and connectivity but data must be restored, giving recovery in hours to days.","It runs live duplicate systems with current data for failover in minutes to hours.","It is a principle of placing sites far apart, not an actual recovery facility."],"correctIndex":0,"explanation":"Cold = bring everything yourself. Management must understand the recovery window is days to weeks; the low price buys space, not readiness. The tell: cold = empty shell, warm = equipped but data must load, hot = running and current, dispersion = a siting principle, not a facility."},
  {"id":"q329","domain":"D3","family":"sites","question":"Comparing two DR proposals: Option A has racks, connectivity, and hardware in place but no current data; Option B is nothing but powered, cooled floor space with all equipment still to be purchased. Which site type is Option B?","options":["warm","hot","geographic dispersion","cold"],"correctIndex":3,"explanation":"Cold. Powered empty space awaiting everything is the cold site; Option A, equipped but data-less, is warm. The tell: cold = shell only, warm = hardware waiting for data, hot = running with synchronized data, geographic dispersion = the distance principle."},
  {"id":"q330","domain":"D3","family":"sites","question":"Your organization has contracted a warm site. When you activate it after an outage, what should you realistically expect to find?","options":["Fully running duplicate systems with continuously current data, ready in minutes to hours.","Racked servers and network connectivity already in place, but recent data must be restored first, taking hours to days.","Only conditioned space with power and cooling, requiring days to weeks to equip.","Two facilities placed far apart so a single disaster cannot strike both."],"correctIndex":1,"explanation":"Warm = equipped, awaiting data. Hardware and links are ready, but restoring backups sets the recovery clock at hours to days. The tell: warm = restore data first, hot = already current, cold = still empty, dispersion = about distance."},
  {"id":"q331","domain":"D3","family":"sites","question":"A firm's recovery facility keeps servers racked and network links live, but current data must be loaded from backups before operations resume, so several hours of recent work could be lost in a failover. Which site type is this?","options":["hot","cold","warm","geographic dispersion"],"correctIndex":2,"explanation":"Warm. Ready hardware plus stale data is the warm site signature, and the data-restore step is exactly where the hours of loss come from. The tell: warm = equipment live, data behind, hot = data continuously current, cold = no equipment at all, dispersion = distance between sites."},
  {"id":"q332","domain":"D3","family":"sites","question":"A manufacturer wants operations restored within roughly a day of a disaster but refuses to pay for a continuously running duplicate facility. It leases a site already stocked with servers and connectivity and plans to restore data after declaring an event. Which site type fits?","options":["warm","hot","cold","geographic dispersion"],"correctIndex":0,"explanation":"Warm. Recovery within about a day, without hot-site cost, is precisely the warm compromise: gear ready, data restored on activation. The tell: warm = the cost/speed middle ground, hot = premium for minutes, cold = cheap but weeks, dispersion = siting distance."},
  {"id":"q333","domain":"D3","family":"sites","question":"A hospital determines that losing access to electronic health records for more than a few minutes endangers patients. Which recovery site option provides near-immediate failover because it is already powered on and running with current data?","options":["warm","cold","geographic dispersion","hot"],"correctIndex":3,"explanation":"Hot. Only a hot site's live, synchronized systems deliver failover measured in minutes, which the clinical requirement demands regardless of cost. The tell: hot = running now with current data, warm = hours to restore, cold = weeks to build, dispersion = distance, not readiness."},
  {"id":"q334","domain":"D3","family":"sites","question":"A cloud provider keeps a standby facility permanently powered on while production replicates data to it continuously; a failover loses only seconds of work and completes within minutes. Which site type is this?","options":["cold","hot","warm","geographic dispersion"],"correctIndex":1,"explanation":"Hot. Always-on systems plus continuous replication equals seconds of data loss and minutes of downtime: the hot site's definition. The tell: hot = powered on, continuously current, warm = equipped but restoring, cold = empty space, dispersion = how far apart the sites are."},
  {"id":"q335","domain":"D3","family":"sites","question":"A continuity standard lists a recovery concept that has nothing to do with how well-equipped any one facility is: it requires facilities be placed far enough apart that one regional event cannot disable them all. Which concept is this?","options":["hot","warm","geographic dispersion","cold"],"correctIndex":2,"explanation":"Geographic dispersion. Distance between facilities is its whole content; readiness tiers are a separate axis entirely. The tell: geographic dispersion = where sites are relative to each other, hot/warm/cold = what state each site is in."},
  {"id":"q336","domain":"D3","family":"sites","question":"An auditor flags that a company's primary data center and its recovery site sit eight miles apart in the same river valley, warning that one flood could destroy both. Which resilience principle did the company fail to apply?","options":["hot","warm","cold","geographic dispersion"],"correctIndex":3,"explanation":"Geographic dispersion. However capable the recovery site is, co-locating it within the same disaster footprint defeats its purpose; the fix is distance. The tell: geographic dispersion = separate the sites beyond one event's reach, hot/warm/cold = readiness of a site, irrelevant if both drown together."},
  {"id":"q337","domain":"D3","family":"resilience-planning","question":"After a single vendor's firmware flaw took down every firewall in the fleet simultaneously, an architect proposes deliberately mixing vendors and operating systems so one flaw can never again hit everything at once. Which resilience approach is this?","options":["multi-cloud","platform diversity","capacity planning","continuity of operations"],"correctIndex":1,"explanation":"Platform diversity. Mixing vendors, operating systems, and technologies prevents a single defect from being a monoculture-wide event. The tell: platform diversity = different tech so one flaw cannot hit all, multi-cloud = the same idea applied to cloud providers, capacity planning = forecasting people/tech/infrastructure needs, continuity of operations = keeping the mission running through disruption."},
  {"id":"q338","domain":"D3","family":"resilience-planning","question":"Ahead of a major product launch, a firm forecasts the additional support staff, server capacity, and bandwidth it will need to absorb the projected surge, and provisions them in advance. Which resilience activity is this?","options":["capacity planning","platform diversity","multi-cloud","continuity of operations"],"correctIndex":0,"explanation":"Capacity planning. Forecasting and provisioning the people, technology, and infrastructure future demand requires is capacity planning. The tell: capacity planning = will we have enough people/tech/infrastructure, platform diversity = avoid a single-vendor monoculture, multi-cloud = spread across providers, continuity of operations = keep functioning during disruption."},
  {"id":"q339","domain":"D3","family":"resilience-planning","question":"Burned by a region-wide outage at its sole cloud provider, a company re-architects to run workloads across Amazon, Microsoft, and Google simultaneously so no single provider failure takes everything down. Which resilience approach is this?","options":["platform diversity","multi-cloud","continuity of operations (COOP)","capacity planning"],"correctIndex":1,"explanation":"Multi-cloud. Spreading workloads across multiple cloud providers removes the single-provider dependency. It is platform diversity's cloud-specific cousin. The tell: multi-cloud = multiple cloud providers, platform diversity = mixed vendors/OS/tech generally, COOP = keeping essential functions running through disruption, capacity planning = forecasting needed resources."},
  {"id":"q340","domain":"D3","family":"resilience-planning","question":"A government agency maintains a formal plan describing exactly how its essential functions will keep operating during and after a major disruption, from alternate facilities to succession of leadership. Which resilience approach is this?","options":["capacity planning","multi-cloud","continuity of operations (COOP)","platform diversity"],"correctIndex":2,"explanation":"Continuity of operations. COOP is the documented plan for keeping mission-essential functions alive through a disruption. The tell: COOP = keep essential functions running no matter what, capacity planning = forecasting resources for demand, multi-cloud = spreading across providers, platform diversity = avoiding a tech monoculture."},
  {"id":"q341","domain":"D3","family":"continuity-testing","question":"An incident response team gathers in a conference room and talks through a ransomware scenario step by step - who calls whom, what gets isolated, when legal is engaged - without touching a single live system. Which test is this?","options":["tabletop exercise","failover test","simulation","parallel processing"],"correctIndex":0,"explanation":"Tabletop exercise. A discussion-based walkthrough with no systems touched is the tabletop: cheap, safe, and great for finding plan gaps. The tell: tabletop = talk through it, simulation = act out the scenario with real response steps, failover test = actually cut production over, parallel processing = run the recovery site alongside production."},
  {"id":"q342","domain":"D3","family":"continuity-testing","question":"To prove its DR plan is more than paper, an organization deliberately shuts down the primary system during a scheduled window and cuts production over to the backup site for real. Which test is this?","options":["tabletop exercise","simulation","failover test","parallel processing"],"correctIndex":2,"explanation":"Failover test. Actually switching live production to the recovery system is the failover test: the most convincing proof and the most disruptive if it goes wrong. The tell: failover = really cut over, parallel processing = recovery runs alongside production untouched, simulation = realistic actions without cutover, tabletop = discussion only."},
  {"id":"q343","domain":"D3","family":"continuity-testing","question":"A bank validates its recovery site by running it alongside live production with the same workload, confirming it keeps up - while production itself is never taken offline. Which continuity test is this?","options":["failover test","parallel processing","simulation","tabletop exercise"],"correctIndex":1,"explanation":"Parallel processing. Running the recovery environment beside production proves capacity with zero production risk. The tell: parallel processing = both run at once, failover = production actually switches, simulation = acted-out scenario, tabletop = conversation in a conference room."},
  {"id":"q344","domain":"D3","family":"continuity-testing","question":"During a scheduled exercise, responders receive a realistic injected breach scenario and perform their actual response procedures - isolating test hosts, paging on-call, drafting comms - but production is never cut over. Which test is this?","options":["tabletop exercise","failover test","parallel processing","simulation"],"correctIndex":3,"explanation":"Simulation. Acting out the response with real steps in a controlled setting, short of an actual cutover, is a simulation: more realistic than a tabletop, less risky than failover. The tell: simulation = perform the steps, tabletop = discuss the steps, failover = flip production for real, parallel processing = run both sites simultaneously."},
  {"id":"q345","domain":"D3","family":"continuity-testing","question":"A continuity manager wants the cheapest, lowest-impact first test of a brand-new DR plan: stakeholders around a table, walking through their roles in a scenario as a structured discussion, no systems involved. Which test is this?","options":["tabletop","simulation","failover","parallel processing"],"correctIndex":0,"explanation":"Tabletop. Discussion-only walkthroughs cost little, risk nothing, and expose plan gaps early, which is why new plans start there. The tell: tabletop = talk it through, simulation = act it out, failover = actually cut over, parallel processing = run both environments at once."},
  {"id":"q346","domain":"D3","family":"continuity-testing","question":"The audit committee asks which continuity test is the most disruptive option on the schedule. Which is it, given that it forces an actual cutover of live operations to the alternate system to prove the switch truly works?","options":["parallel processing","tabletop","failover","simulation"],"correctIndex":2,"explanation":"Failover. Deliberately switching live production to the backup is the strongest proof and the biggest operational risk, so it is scheduled with care. The tell: failover = production really moves, parallel processing = recovery site runs alongside untouched production, simulation = realistic actions without cutover, tabletop = discussion only."},
  {"id":"q347","domain":"D3","family":"continuity-testing","question":"One continuity test goes beyond a discussion: the team physically executes its response actions in a controlled scenario. Yet unlike a failover test, production is never actually cut over. Which test is this?","options":["failover","tabletop","parallel processing","simulation"],"correctIndex":3,"explanation":"Simulation. Real actions, controlled scope, no production cutover: the middle rung between talking (tabletop) and switching (failover). The tell: simulation = do the steps without the cutover, tabletop = words only, failover = the real switch, parallel processing = both sites running side by side."},
  {"id":"q348","domain":"D3","family":"backups","question":"Minutes before applying a risky hypervisor patch, a virtualization admin captures the exact current state of the VM so one click can return it to this instant if the patch goes wrong. Which backup method fits?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":0,"explanation":"Snapshot. A point-in-time image you can revert to instantly is a snapshot, the standard pre-change safety net for VMs. The tell: snapshot = frozen point-in-time image, replication = continuous mirror of writes, journaling = log of changes replayed to a moment, offsite = where a copy lives."},
  {"id":"q349","domain":"D3","family":"backups","question":"A database team's recovery requirement is to restore to any exact transaction - say, the moment before a bad deployment - by replaying a log of every change made since the last full backup. Which technique provides this?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":2,"explanation":"Journaling. Recording every change in a log so you can replay to a precise point delivers transaction-level recovery granularity. The tell: journaling = change log replayed to an exact moment, snapshot = discrete point-in-time images only, replication = a continuously current mirror (which faithfully copies mistakes too), offsite = location."},
  {"id":"q350","domain":"D3","family":"backups","question":"A company ships encrypted backup media to a facility in another city each week, so a fire that destroys headquarters cannot also destroy the backups. This copy is best described as which?","options":["snapshot","journaling","replication","offsite backup"],"correctIndex":3,"explanation":"Offsite backup. A copy kept at a separate geographic location survives building-level disasters; that placement is its whole point. The tell: offsite = separate facility, onsite = same building, fast but shares the building's fate, snapshot/journaling/replication = how copies are made, not where they live."},
  {"id":"q351","domain":"D3","family":"backups","question":"A storage engineer configures the primary array to copy every write to a second array at a partner site in near real time, keeping the two nearly identical at every moment. Which technique is this?","options":["snapshot","replication","journaling","onsite backup"],"correctIndex":1,"explanation":"Replication. Continuously mirroring writes so the copy stays current is replication, built for minimal data loss on failover. The tell: replication = continuous near-real-time mirror, snapshot = periodic frozen images, journaling = a replayable change log, onsite backup = a local copy."},
  {"id":"q352","domain":"D3","family":"backups","question":"A change-control document requires capturing \"a point-in-time image of the volume that can be reverted to exactly as it existed at that instant.\" Which term is being defined?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":0,"explanation":"Snapshot. Point-in-time image plus exact revert is the snapshot definition. The tell: snapshot = frozen instant you can return to, replication = live mirror, journaling = replayable change log, offsite backup = a copy stored elsewhere."},
  {"id":"q353","domain":"D3","family":"backups","question":"An admin's priority is that the secondary copy stay constantly current with production, so a failover loses almost nothing - not a periodic image from hours ago. Which approach fits?","options":["snapshot","journaling","onsite backup","replication"],"correctIndex":3,"explanation":"Replication. Constant currency of the copy is replication's promise, minimizing the recovery point. Snapshots by definition age between captures. The tell: replication = always current mirror, snapshot = as fresh as the last capture, journaling = replay log for precision recovery, onsite backup = local copy."},
  {"id":"q354","domain":"D3","family":"backups","question":"A vendor proposal describes its backup strategy as journaling. What does that strategy actually do?","options":["Captures a single point-in-time image you can revert to","Continuously mirrors writes to a second location in near real time","Records every change in a log so transactions can be replayed to a precise point","Keeps a copy in a separate geographic facility"],"correctIndex":2,"explanation":"Journaling = the change log. Every transaction is recorded so recovery can replay to an exact moment. The tell: journaling = replayable log of changes, snapshot = point-in-time image, replication = live mirroring, offsite = geographic separation."},
  {"id":"q355","domain":"D3","family":"backups","question":"A team captures an image of the file server every night at midnight and formally accepts that a failure at 11 p.m. will lose that entire day's changes. Which backup method are they relying on?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":0,"explanation":"Snapshot. Nightly point-in-time captures mean the recovery point is the most recent snapshot, and everything since is lost, exactly the accepted trade-off. The tell: snapshot = periodic frozen images, data since the last one is gone, replication = continuously current, journaling = replay to any point, offsite = storage location."},
  {"id":"q356","domain":"D3","family":"backups","question":"An architect notes that backups kept on local storage in the same building restore fastest, but a fire or flood that destroys the building destroys them too. This copy is best described as which?","options":["offsite backup","onsite backup","snapshot","replication"],"correctIndex":1,"explanation":"Onsite backup. Local copies trade disaster survival for restore speed; that is why strategies pair them with offsite copies. The tell: onsite = same building, fast restore, shared fate, offsite = another facility, survives the building, snapshot/replication = techniques, not locations."},
  {"id":"q357","domain":"D3","family":"backups","question":"A DR workshop explains that one backup attribute sets the maximum data you can lose between copies and therefore directly drives the recovery point objective: how often the backups run. What is this attribute called?","options":["replication","journaling","encryption","frequency"],"correctIndex":3,"explanation":"Frequency. The interval between backups bounds worst-case data loss, tying frequency directly to the RPO. The tell: frequency = how often copies are made, drives RPO, replication = continuous mirroring, journaling = replayable change log, encryption = protects the backup's confidentiality, not its currency."},
  {"id":"q358","domain":"D3","family":"backups","question":"A database team explicitly rejects a plain live mirror: they need to replay every individual change since the last full backup so they can recover to the exact moment before a bad transaction. Which technique provides this?","options":["replication","journaling","snapshots","recovery"],"correctIndex":1,"explanation":"Journaling. The change log replayed forward gives point-precise recovery; a mirror would have faithfully copied the bad transaction too. The tell: journaling = replay the log to an exact point, replication = continuously current copy, mistakes included, snapshots = discrete points in time, recovery = the restore act itself."},
  {"id":"q359","domain":"D3","family":"backups","question":"A storage proposal promises the secondary copy will be continuously updated in near real time so it stays almost identical to the source at every moment. Which backup technique is being proposed?","options":["replication","snapshots","journaling","frequency"],"correctIndex":0,"explanation":"Replication. Continuous near-real-time copying keeping source and copy in step is replication, the minimal-data-loss option. The tell: replication = always-current mirror, snapshots = periodic frozen images, journaling = a replayable change log, frequency = how often periodic backups run."},
  {"id":"q360","domain":"D3","family":"backups","question":"A junior admin asks what a snapshot actually captures. Which answer is correct?","options":["A continuous near real-time copy kept identical to the source.","A log of every change that can be replayed to a precise point.","A copy stored in the same building for the fastest restore.","A point-in-time image of the volume that you can revert to exactly as it was at that instant."],"correctIndex":3,"explanation":"A snapshot freezes an instant. You can revert to exactly that moment, and anything after it is lost. The tell: snapshot = point-in-time image, replication = continuous mirror, journaling = replayable log, onsite = a location, not a method."},
  {"id":"q361","domain":"D3","family":"backups","question":"Each Friday a courier moves the week's encrypted backup media to a secured vault in a distant state, so a regional disaster at headquarters cannot claim both production and its backups. The firm accepts slower retrieval in exchange. Which copy is this?","options":["onsite","offsite","replication","snapshots"],"correctIndex":1,"explanation":"Offsite. Geographic separation is what buys survival of a site-wide or regional disaster, at the price of retrieval time. The tell: offsite = distant location, survives the disaster, onsite = same building, fast but shares its fate, replication/snapshots = techniques, not locations."},
  {"id":"q362","domain":"D3","family":"backups","question":"An architect notes one backup location choice restores fastest because the media sits in the same building as production, but a fire or flood that takes the building takes the backups too. Which choice is this?","options":["onsite","offsite","encryption","frequency"],"correctIndex":0,"explanation":"Onsite. Same-building storage minimizes restore time and maximizes shared risk, which is why it is paired with offsite copies rather than trusted alone. The tell: onsite = fast restore, shared fate, offsite = survives the site loss, encryption/frequency = protection and scheduling attributes, not locations."},
  {"id":"q363","domain":"D3","family":"backups","question":"A compliance officer worries that backup tapes could be stolen in transit to the offsite vault and read by whoever takes them. Which backup safeguard directly renders stolen tape data unreadable without the key?","options":["offsite","frequency","encryption","replication"],"correctIndex":2,"explanation":"Encryption. Encrypting backup media makes physical theft a nuisance instead of a breach; possession without the key yields nothing. The tell: encryption = confidentiality of the media, offsite = where it is stored, frequency = how often backups run, replication = continuous copying."},
  {"id":"q364","domain":"D3","family":"backups","question":"After a near-miss, a team moves from one backup per day to one every four hours, specifically to shrink the window of data that could be lost between backups and tighten the recovery point objective. Which backup attribute did they change?","options":["recovery","replication","journaling","frequency"],"correctIndex":3,"explanation":"Frequency. The interval between backups bounds the worst-case loss, so raising frequency directly tightens the RPO. The tell: frequency = how often, drives RPO, recovery = the restore act, replication = continuous mirroring, journaling = replayable change log."},
  {"id":"q365","domain":"D3","family":"backups","question":"Ransomware encrypts the production file servers. The response team wipes the systems and restores clean data from the most recent unaffected backups, returning services to a working state. Which backup activity is this?","options":["recovery","replication","snapshots","journaling"],"correctIndex":0,"explanation":"Recovery. Restoring data from backup to return systems to operation is the recovery step, the payoff for every other backup decision. The tell: recovery = restoring from the copies, replication/snapshots/journaling = the ways the copies got made."},
  {"id":"q366","domain":"D3","family":"backups","question":"A cloud administrator schedules the storage array to capture a read-only point-in-time image of each volume every hour, letting any of the past several hours be restored exactly as the volume looked then. Which backup method is in use?","options":["replication","snapshots","journaling","offsite"],"correctIndex":1,"explanation":"Snapshots. Hourly point-in-time images with exact revert are snapshots on a schedule; granularity is bounded by the capture interval. The tell: snapshots = frozen images at intervals, replication = continuous mirror, journaling = replay-any-moment log, offsite = a storage location."},
  {"id":"q367","domain":"D3","family":"backups","question":"Two data centers must stay within seconds of each other so that if one fails, the survivor holds essentially identical data. Every write at the primary is copied to the partner continuously as it happens. Which technique keeps them in step?","options":["snapshots","journaling","replication","onsite"],"correctIndex":2,"explanation":"Replication. Continuous per-write copying is what holds two sites within seconds of each other; periodic methods cannot. The tell: replication = continuous, near-zero lag, snapshots = as stale as the last capture, journaling = a log to replay, onsite = a location."},
  {"id":"q368","domain":"D3","family":"power","question":"A hospital's server rack cannot tolerate even a momentary power gap. When utility power blips, a battery instantly carries the load for the seconds to minutes needed for longer-term power to come online. Which device provides this instant ride-through?","options":["generator","UPS","power distribution unit","dual power supply"],"correctIndex":1,"explanation":"UPS. The uninterruptible power supply's battery bridges outages instantly but only briefly, buying time for the generator. The tell: UPS = instant battery, short duration, generator = seconds to start, runs for days on fuel, PDU = distributes power within the rack, dual power supply = redundancy inside one device."},
  {"id":"q369","domain":"D3","family":"power","question":"During a six-hour utility outage, a facility stays up on a fuel-powered unit that needed several seconds to start after the failure and can keep producing power for as long as fuel is delivered. Which device is this?","options":["UPS","power distribution unit","generator","dual power supply"],"correctIndex":2,"explanation":"Generator. Fuel-driven, slow to start, effectively unlimited runtime: the generator handles the long haul after the UPS bridges the startup gap. The tell: generator = long-duration fuel power with a startup delay, UPS = instant but brief battery, PDU = power distribution hardware, dual power supply = component redundancy in a single chassis."},
  {"id":"q370","domain":"D3","family":"power","question":"Utility power drops at a hospital data center. For the first 20 seconds, a battery unit instantly carries the full server load until the fuel-powered unit spins up and takes over for the remaining hours. Which device carried the load in those first seconds?","options":["generator","UPS","power distribution unit","dual power supply"],"correctIndex":1,"explanation":"UPS. The battery's job is the instant bridge: zero-gap power for seconds to minutes while the generator starts. The tell: UPS = instant, brief battery ride-through, generator = slow-starting long-haul fuel power, PDU = distributes power in the rack, dual power supply = redundancy within one device."},
  {"id":"q371","domain":"D3","family":"power","question":"A facility relies on a diesel generator to survive extended outages. Which inherent limitation must its power design compensate for?","options":["It only routes power to rack equipment and provides no backup itself.","It offers redundancy inside one device but no outage protection.","It gives instant battery power but only for seconds to minutes.","It takes several seconds to start, so a battery unit must bridge the gap until it runs."],"correctIndex":3,"explanation":"Generators start slow. Those several seconds of startup are a hard gap that a UPS battery must cover, which is why the two are always paired. The tell: generator = long duration, delayed start, UPS = instant, short duration; each covers the other's weakness."},
  {"id":"q372","domain":"D4","family":"baselines","question":"A security team writes down the approved hardened configuration - services disabled, password policy, logging settings - that every new server must match before it may enter production. Which step of the baseline process is this?","options":["Establish","Deploy","Maintain","Decommission"],"correctIndex":0,"explanation":"Establish. Defining and documenting the approved secure configuration is establishing the baseline; rolling it out and keeping systems on it come later. The tell: establish = define the standard, deploy = push it onto systems, maintain = keep systems matching it over time, decommission = retire it."},
  {"id":"q373","domain":"D4","family":"baselines","question":"Months after rollout, a team keeps patching systems, watches for configuration drift, and re-applies settings whenever a server slips out of line with the approved configuration. Which baseline activity is this?","options":["Deploy","Maintain","Establish","Decommission"],"correctIndex":1,"explanation":"Maintain. Drift detection, patching, and re-applying settings keep systems aligned with the baseline over time, the ongoing maintain phase. The tell: maintain = keep systems on the standard, deploy = the initial rollout, establish = writing the standard, decommission = retiring it."},
  {"id":"q374","domain":"D4","family":"baselines","question":"With the golden image approved, the endpoint team uses its configuration management tool to push that exact secure configuration onto all 400 new workstations before they ship to users. Which baseline activity is this?","options":["Establish","Maintain","Configuration enforcement","Deploy"],"correctIndex":3,"explanation":"Deploy. Rolling the approved baseline out onto systems is the deploy phase; keeping them compliant afterward is maintain. The tell: deploy = push the standard out, establish = define it, maintain = hold systems to it over time, configuration enforcement = the mechanism maintain uses."},
  {"id":"q375","domain":"D4","family":"baselines","question":"In the three-phase baseline process, what does the maintain phase primarily involve?","options":["Writing the initial secure reference configuration","Pushing the approved configuration out to new systems","Continuously enforcing the configuration and correcting drift over time","Selecting which systems the baseline applies to"],"correctIndex":2,"explanation":"Maintain = fight drift forever. Continuous enforcement, drift detection, and correction keep systems matching the baseline long after rollout. The tell: establish = write it, deploy = push it, maintain = keep it true over time."},
  {"id":"q376","domain":"D4","family":"wireless-install","question":"Before mounting a single access point in a new warehouse, a wireless engineer walks the floor with measurement gear, recording signal propagation, interference sources, and dead zones to decide where each AP belongs. What is this activity?","options":["Heat map","WPA3","Site survey","RADIUS"],"correctIndex":2,"explanation":"Site survey. The physical walkthrough measuring coverage and interference is the site survey; the heat map is the color-coded coverage picture the survey produces. The tell: site survey = the measuring activity, heat map = the visual output, WPA3 = the encryption standard, RADIUS = the authentication server."},
  {"id":"q377","domain":"D4","family":"wireless-install","question":"An enterprise requires each Wi-Fi user to sign in with their own domain username and password, checked against a central authentication server, instead of everyone sharing one passphrase. Which component provides this?","options":["RADIUS","WPA3","Heat map","Site survey"],"correctIndex":0,"explanation":"RADIUS. Per-user enterprise authentication (802.1X/WPA-Enterprise) is brokered by a RADIUS server checking individual credentials. The tell: RADIUS = central per-user authentication, WPA3 = the encryption protocol, site survey = planning walkthrough, heat map = coverage visualization."},
  {"id":"q378","domain":"D4","family":"wireless-install","question":"After finishing the warehouse walkthrough, the wireless engineer delivers a color-coded floor plan showing measured signal strength in every zone, with red patches marking weak coverage. What is this deliverable?","options":["Site survey","Heat map","WPA3","RADIUS"],"correctIndex":1,"explanation":"Heat map. The color-coded coverage visualization is the heat map, produced from site survey measurements. The tell: heat map = the visual output, site survey = the measuring walkthrough that produced it, WPA3 = encryption, RADIUS = per-user authentication."},
  {"id":"q379","domain":"D4","family":"wireless-install","question":"A wireless hardening checklist requires the current-generation standard that encrypts traffic on the enterprise WLAN, replacing its predecessor's weaker handshake. Which element is this?","options":["RADIUS","Site survey","WPA3","Heat map"],"correctIndex":2,"explanation":"WPA3. The current Wi-Fi protected access standard secures wireless traffic confidentiality, improving on WPA2's handshake weaknesses. The tell: WPA3 = the encryption standard, RADIUS = the authentication server behind enterprise mode, site survey/heat map = planning activity and its output."},
  {"id":"q380","domain":"D4","family":"mobile-deployment","question":"Sales staff read company email on their own personal phones. The company never bought the hardware and accepts it has only limited say over what else runs on those devices. Which deployment model is this?","options":["COPE","CYOD","BYOD","MDM"],"correctIndex":2,"explanation":"BYOD. Bring your own device: employee-owned hardware, minimal organizational control, maximum privacy friction. The tell: BYOD = user owns it, COPE = company owns it, personal use allowed, CYOD = user picks from a company-approved list, MDM = the management platform, not an ownership model."},
  {"id":"q381","domain":"D4","family":"mobile-deployment","question":"A firm buys smartphones, issues them to staff, and explicitly allows personal apps and use on these company-owned devices. Which deployment model is this?","options":["COPE","BYOD","CYOD","MDM"],"correctIndex":0,"explanation":"COPE. Corporate-owned, personally enabled: the company owns and controls the device but sanctions personal use. The tell: COPE = corporate-owned, personal use permitted, BYOD = employee-owned, CYOD = employee chooses from an approved catalog, MDM = the management tooling."},
  {"id":"q382","domain":"D4","family":"mobile-deployment","question":"Whatever the ownership model, the security team needs one platform to push configuration policies, enforce device encryption, and remotely wipe any phone reported lost. What is this platform?","options":["BYOD","CYOD","COPE","MDM"],"correctIndex":3,"explanation":"MDM. Mobile device management is the control plane - policy push, encryption enforcement, remote wipe - layered on top of whichever ownership model is chosen. The tell: MDM = the management platform, BYOD/CYOD/COPE = who owns and picks the hardware."},
  {"id":"q383","domain":"D4","family":"mobile-deployment","question":"New hires choose their work phone from a short list of approved, company-purchased models - iPhone or one of two Androids - and IT manages whichever they pick. Which deployment model is this?","options":["BYOD","CYOD","COPE","MDM"],"correctIndex":1,"explanation":"CYOD. Choose your own device: the employee picks from a company-approved, company-purchased catalog, giving IT standardization with user choice. The tell: CYOD = pick from the approved list, BYOD = bring your personal phone, COPE = company device with personal use allowed, MDM = the management platform."},
  {"id":"q384","domain":"D4","family":"mobile-deployment","question":"Field technicians use phones they personally bought and own. The company reimburses part of the bill for work use but cannot dictate what else gets installed on the devices. Which deployment model is this?","options":["CYOD","COPE","BYOD","MDM"],"correctIndex":2,"explanation":"BYOD. Personal ownership with limited corporate control is bring your own device, whatever the reimbursement arrangement. The tell: BYOD = employee-owned hardware, CYOD = company-bought from an approved list, COPE = company-owned with personal use, MDM = the management tooling."},
  {"id":"q385","domain":"D4","family":"mobile-deployment","question":"An exam glossary defines one model with the phrase \"company-owned, personally enabled\": the organization owns and fully manages the device while sanctioning personal use. Which model is it?","options":["MDM","CYOD","BYOD","COPE"],"correctIndex":3,"explanation":"COPE. The phrase is the acronym: corporate-owned, personally enabled. The tell: COPE = company owns, personal use blessed, CYOD = user chooses from the approved catalog, BYOD = user owns the device, MDM = the platform managing any of them."},
  {"id":"q386","domain":"D4","family":"app-security","question":"A developer fixes a web form so every submission is checked first: entries containing SQL keywords or script tags are rejected before the application ever processes them. Which secure coding practice is this?","options":["Input validation","Secure cookies","Code signing","Sandboxing"],"correctIndex":0,"explanation":"Input validation. Checking and rejecting untrusted input before processing is the front-line defense against injection and XSS. The tell: input validation = vet what comes in, code signing = prove where software came from, sandboxing = run code in a contained space, secure cookies = protect session tokens in transit."},
  {"id":"q387","domain":"D4","family":"app-security","question":"A vendor attaches a cryptographic signature to each installer it ships, letting customers verify the package really came from the vendor and was not modified since signing. Which practice is this?","options":["Sandboxing","Static code analysis","Code signing","Input validation"],"correctIndex":2,"explanation":"Code signing. Signing binaries proves origin and integrity, the defense that makes malicious-update attacks detectable. The tell: code signing = authenticity and integrity of shipped software, static analysis = examining source for flaws, sandboxing = contained execution, input validation = filtering untrusted input."},
  {"id":"q388","domain":"D4","family":"app-security","question":"A SOC policy requires suspicious email attachments to be opened only inside a disposable, isolated virtual environment, so anything malicious detonates where it can reach nothing real. Which practice is this?","options":["Static code analysis","Input validation","Secure cookies","Sandboxing"],"correctIndex":3,"explanation":"Sandboxing. Running untrusted content in a contained, throwaway environment keeps any malice away from production. The tell: sandboxing = isolated execution space, static analysis = reading code without running it, input validation = filtering user input, secure cookies = protecting session tokens."},
  {"id":"q389","domain":"D4","family":"app-security","question":"A developer sets the HttpOnly and Secure flags on the application's session tokens, so scripts cannot read them and browsers refuse to send them over cleartext connections. Which application security practice is this?","options":["Secure cookies","Code signing","Sandboxing","Static code analysis"],"correctIndex":0,"explanation":"Secure cookies. HttpOnly and Secure flags harden session cookies against script theft (XSS) and cleartext exposure. The tell: secure cookies = protecting session tokens with flags, code signing = proving software origin, sandboxing = contained execution, static analysis = code review by tool."},
  {"id":"q390","domain":"D4","family":"asset-management","question":"A security tool sweeps the network ranges every night, discovering every connected device - including a dozen that appear on no official list. Which asset-management activity is the tool performing?","options":["Inventory","Enumeration","Acquisition","Classification"],"correctIndex":1,"explanation":"Enumeration. Actively discovering what is really on the network, including unknown devices, is enumeration; the inventory is the maintained record it feeds. The tell: enumeration = active discovery of what exists, inventory = the kept list, acquisition = the purchasing process, classification = labeling by sensitivity."},
  {"id":"q391","domain":"D4","family":"asset-management","question":"An administrator tags each server according to the sensitivity of the data it stores - public, internal, confidential - so the correct handling and protection rules apply to each. Which asset-management activity is this?","options":["Classification","Assignment","Enumeration","Ownership"],"correctIndex":0,"explanation":"Classification. Labeling assets by data sensitivity drives how each must be protected and handled. The tell: classification = sensitivity labels, assignment/ownership = naming who is accountable for the asset, enumeration = discovering what exists."},
  {"id":"q392","domain":"D4","family":"asset-management","question":"An auditor asks for the maintained master record of every hardware and software asset the organization owns, with owner and location for each. Which asset-management element is being requested?","options":["Enumeration","Acquisition","Assignment","Inventory"],"correctIndex":3,"explanation":"Inventory. The maintained master list of assets is the inventory; enumeration is the discovery activity that keeps it honest. The tell: inventory = the kept record, enumeration = actively finding what exists, acquisition = the buying process, assignment = naming who owns each asset."},
  {"id":"q393","domain":"D4","family":"asset-management","question":"Purchasing completes the order for a new database server and the machine formally enters the company's possession, kicking off its lifecycle records. Which asset lifecycle stage is this?","options":["Assignment","Ownership","Acquisition","Enumeration"],"correctIndex":2,"explanation":"Acquisition. Procuring the asset and taking possession is acquisition, the lifecycle's first stage. The tell: acquisition = obtaining the asset, assignment/ownership = designating who is accountable for it, enumeration = discovering assets already on the network."},
  {"id":"q394","domain":"D4","family":"asset-disposal","question":"Laptops rotating out of the executive team will be reissued to another department, so IT wipes the drives with a verified erasure tool while keeping the hardware in service. Which disposal step is this?","options":["Destruction","Sanitization","Certification","Data retention"],"correctIndex":1,"explanation":"Sanitization. Removing all data while the asset survives for reuse is sanitization; destruction would end the hardware's life too. The tell: sanitization = data gone, hardware reusable, destruction = the asset is physically destroyed, certification = the signed proof of disposal, data retention = how long data must be kept."},
  {"id":"q395","domain":"D4","family":"asset-disposal","question":"Failed drives that once held classified material are fed through an industrial shredder, reducing them to fragments no lab could ever recover data from. Which disposal method is this?","options":["Sanitization","Certification","Destruction","Data retention"],"correctIndex":2,"explanation":"Destruction. Physically destroying the media guarantees the data dies with it, the standard for the most sensitive material. The tell: destruction = the media is physically gone, sanitization = wiped but intact for reuse, certification = the paperwork proving it happened, data retention = the keep-it policy."},
  {"id":"q396","domain":"D4","family":"asset-disposal","question":"After destroying a batch of retired drives, the disposal vendor hands over a signed document listing every serial number and attesting each was destroyed. What is this document?","options":["Certification","Sanitization","Destruction","Data retention"],"correctIndex":0,"explanation":"Certification. The signed attestation of what was destroyed, and when, is the certificate of destruction that auditors ask to see. The tell: certification = the proof document, destruction = the act itself, sanitization = wiping for reuse, data retention = the policy on keeping data."},
  {"id":"q397","domain":"D4","family":"asset-disposal","question":"A regulation obliges the company to keep financial records for seven full years before they may be disposed of, and legal holds can extend that. Which concept dictates how long the data must be kept?","options":["Sanitization","Data retention","Destruction","Certification"],"correctIndex":1,"explanation":"Data retention. Retention rules define how long data must be preserved before disposal is even permitted. The tell: data retention = the mandatory keep period, sanitization = wiping for reuse, destruction = physically eliminating media, certification = the signed proof of disposal."},
  {"id":"q398","domain":"D4","family":"asset-disposal","question":"At contract end, a colocation provider degausses every tenant drive and then pulverizes the platters, guaranteeing nothing is recoverable by any means. Which disposal method is this?","options":["Certification","Sanitization","Destruction","Data retention"],"correctIndex":2,"explanation":"Destruction. Degaussing plus physical pulverizing ends the media's existence along with its data. The tell: destruction = the media is physically gone, sanitization = data removed, media survives, certification = the attestation document, data retention = the keep-it-first rule."},
  {"id":"q399","domain":"D4","family":"asset-disposal","question":"An asset-disposal standard lists sanitization as one approved method. Sanitization is best described as which of the following?","options":["Physically shredding or degaussing media so it is gone","Removing data so the media can be safely reused","A signed document proving data was destroyed","The required period data must be kept before disposal"],"correctIndex":1,"explanation":"Sanitization = wipe and reuse. Data is verifiably removed while the hardware lives on for redeployment or resale. The tell: sanitization = data gone, media survives, destruction = media gone too, certification = the paperwork, retention = the schedule."},
  {"id":"q400","domain":"D4","family":"analysis-types","question":"A pipeline tool inspects an application's source code for insecure functions, hardcoded secrets, and injection flaws - all without ever executing the program. Which analysis type is this?","options":["Package monitoring","Sandboxing","Dynamic analysis","Static analysis"],"correctIndex":3,"explanation":"Static analysis. Examining code without running it is static analysis (SAST), typically wired into the build pipeline. The tell: static = read the code, never run it, dynamic = observe it while running, package monitoring = watch dependencies for new CVEs, sandboxing = the contained place you run things."},
  {"id":"q401","domain":"D4","family":"analysis-types","question":"Malware analysts detonate a suspicious binary inside an instrumented, isolated environment, recording every file write, registry change, and network call it makes as it runs. Which analysis type is this?","options":["Package monitoring","Code signing","Static analysis","Dynamic analysis"],"correctIndex":3,"explanation":"Dynamic analysis. Observing behavior during execution is dynamic analysis; the instrumented sandbox is where it safely happens. The tell: dynamic = run it and watch, static = examine without running, package monitoring = dependency vulnerability alerts, code signing = proving software origin."},
  {"id":"q402","domain":"D4","family":"analysis-types","question":"A DevOps team subscribes to a service that pages them whenever any open-source library in their build acquires a newly disclosed vulnerability, so they can bump versions fast. Which activity is this?","options":["Package monitoring","Static analysis","Dynamic analysis","Input validation"],"correctIndex":0,"explanation":"Package monitoring. Watching third-party dependencies for new vulnerabilities is package monitoring, the guard against inheriting someone else's flaw. The tell: package monitoring = track dependency CVEs, static analysis = scan your own code, dynamic analysis = observe running behavior, input validation = filter untrusted input."},
  {"id":"q403","domain":"D4","family":"analysis-types","question":"A security lead explains the difference between the two main testing approaches. Static analysis differs from dynamic analysis in that static analysis does which of the following?","options":["Examines the code or binary without executing it","Runs the program and observes its runtime behavior","Watches third-party dependencies for disclosed vulnerabilities","Feeds malformed inputs to a live running process"],"correctIndex":0,"explanation":"Static = no execution. It reads source or binaries for flaws; anything involving running the program is dynamic. The tell: static = examine at rest, dynamic = observe while running, package monitoring = watch the dependencies, fuzzing = a dynamic technique using malformed input."},
  {"id":"q404","domain":"D4","family":"analysis-types","question":"On every commit, the CI server launches the freshly built application, bombards it with malformed inputs, and watches for crashes, hangs, and unexpected system calls. Which analysis type is running?","options":["Static analysis","Dynamic analysis","Package monitoring","Reverse engineering"],"correctIndex":1,"explanation":"Dynamic analysis. The application is executing and being observed - fuzzing malformed inputs at a running build is dynamic testing. The tell: dynamic = the program runs, static = it never runs, package monitoring = dependency CVE alerts, reverse engineering = deconstructing a binary's logic."},
  {"id":"q405","domain":"D4","family":"analysis-types","question":"A team is confident in its own code but worries about the dozens of open-source libraries its build pulls in. It wants alerts when any of those inherited components acquires a known vulnerability. Which activity addresses this?","options":["Static analysis","Dynamic analysis","Package monitoring","Fuzzing"],"correctIndex":2,"explanation":"Package monitoring. Tracking third-party dependencies for newly disclosed vulnerabilities covers the code you did not write. The tell: package monitoring = watch inherited components, static/dynamic analysis = test your own application, fuzzing = malformed-input testing of running code."},
  {"id":"q406","domain":"D4","family":"threat-intel","question":"A threat analyst builds a daily briefing entirely from free public sources: vendor blogs, security researchers on social media, and government advisories. Which intelligence source type is this?","options":["Proprietary threat feed","Information-sharing organization","Dark web monitoring","OSINT"],"correctIndex":3,"explanation":"OSINT. Open-source intelligence is anything gathered from freely available public sources. The tell: OSINT = free public sources, proprietary feed = paid vendor intelligence, information-sharing organization = a formal peer community (ISAC), dark web monitoring = watching criminal forums and markets."},
  {"id":"q407","domain":"D4","family":"threat-intel","question":"Hospitals across a region exchange fresh indicators of compromise through a formal healthcare industry community, warning each other about campaigns targeting their sector. Which threat-intelligence source is this?","options":["Dark web monitoring","OSINT","Information-sharing organization","Proprietary threat feed"],"correctIndex":2,"explanation":"Information-sharing organization. Sector-based communities (ISACs/ISAOs) formally exchanging indicators among peers are sharing organizations. The tell: information-sharing organization = formal industry peer exchange, OSINT = public sources, proprietary feed = purchased intel, dark web monitoring = watching criminal marketplaces."},
  {"id":"q408","domain":"D4","family":"threat-intel","question":"A bank pays a security vendor for a curated subscription feed of indicators, malware analysis, and actor profiles that is unavailable to the public. Which threat-intelligence source is this?","options":["OSINT","Information-sharing organization","Dark web","Proprietary third-party feed"],"correctIndex":3,"explanation":"Proprietary third-party feed. Paid, curated, non-public intelligence from a vendor is the proprietary feed. The tell: proprietary feed = purchased and curated, OSINT = free public sources, information-sharing organization = peer exchange in a sector community, dark web = watching criminal venues directly."},
  {"id":"q409","domain":"D4","family":"threat-intel","question":"An intel team maintains personas on hidden criminal marketplaces and closed forums, watching for the company's customer credentials being offered for sale. Which threat-intelligence source is this?","options":["Dark web","OSINT","Information-sharing organization","Proprietary third-party feed"],"correctIndex":0,"explanation":"Dark web. Monitoring criminal marketplaces and hidden forums for your own stolen data is dark web intelligence. The tell: dark web = watching the criminal underground, OSINT = open public sources, information-sharing organization = peer community exchange, proprietary feed = vendor subscription."},
  {"id":"q410","domain":"D4","family":"security-assessments","question":"A company launches a public program paying external researchers a reward for each valid vulnerability they responsibly disclose through the program's rules. Which assessment approach is this?","options":["Penetration testing","Bug bounty","Process audit","System audit"],"correctIndex":1,"explanation":"Bug bounty. Crowdsourced, pay-per-finding vulnerability discovery under disclosure rules is a bug bounty, ongoing rather than a scoped engagement. The tell: bug bounty = open crowd, paid per valid bug, penetration test = a hired team on a defined scope and timeframe, audits = reviews against requirements, not exploitation."},
  {"id":"q411","domain":"D4","family":"security-assessments","question":"An organization signs a rules-of-engagement document and hires an authorized team to actively exploit its systems for three weeks, proving which weaknesses are actually reachable and damaging. Which assessment is this?","options":["System audit","Bug bounty","Penetration testing","Process audit"],"correctIndex":2,"explanation":"Penetration testing. A scoped, authorized engagement that exploits weaknesses to demonstrate real impact is a pen test. The tell: penetration test = authorized active exploitation on a defined scope, bug bounty = open-ended crowd program, system/process audit = checking conformance to requirements without attacking."},
  {"id":"q412","domain":"D4","family":"security-assessments","question":"An assessor spends a week comparing the company's access-control procedures and change tickets against a required framework, confirming the documented controls are actually followed in practice. Which assessment is this?","options":["Penetration testing","Bug bounty","System and process audit","Responsible disclosure"],"correctIndex":2,"explanation":"System and process audit. Verifying conformance of systems and procedures against requirements, via records and interviews rather than attacks, is an audit. The tell: audit = check against requirements, penetration test = actively exploit, bug bounty = crowd-paid findings, responsible disclosure = the reporting etiquette."},
  {"id":"q413","domain":"D4","family":"security-assessments","question":"A security manager explains the budget line items to finance. How does a penetration test differ from a bug bounty program?","options":["A pen test is an authorized engagement by a specific hired team, while a bug bounty pays any external researcher per valid finding","A pen test pays per finding, while a bug bounty is a single fixed engagement","Both only review documentation without touching any systems","A pen test never requires authorization from the target"],"correctIndex":0,"explanation":"Pen test = scoped hired team; bounty = open crowd paid per bug. One is a bounded engagement under rules of engagement, the other a standing invitation with per-finding rewards. The tell: pen test = defined team, scope, and window, bug bounty = anyone, anytime, per valid disclosure."},
  {"id":"q414","domain":"D4","family":"false-pos-neg","question":"An IDS raises a data-exfiltration alert overnight. Investigation shows the traffic was a routine, authorized offsite backup job. The alert fired, but nothing malicious happened. What is this outcome called?","options":["False negative","False positive","True positive","True negative"],"correctIndex":1,"explanation":"False positive. The system alerted on benign activity: alarm without a real event. Noisy but visible. The tell: false positive = alert, no real attack, false negative = attack, no alert, true positive = alert on a real attack, true negative = silence on benign activity."},
  {"id":"q415","domain":"D4","family":"false-pos-neg","question":"Post-incident review reveals malware ran on a host for six weeks while the antivirus stayed completely silent about it the entire time. What does this missed detection represent?","options":["False positive","True negative","False negative","True positive"],"correctIndex":2,"explanation":"False negative. Real malicious activity that produced no alert is the false negative, the most dangerous outcome because nobody knows to respond. The tell: false negative = missed real attack, false positive = false alarm, true positive = caught real attack, true negative = correctly quiet."},
  {"id":"q416","domain":"D4","family":"false-pos-neg","question":"Drowning in noisy alerts, an analyst dials down the sensitivity of the detection rules so they fire far less often. Which outcome does this over-tuning primarily risk increasing?","options":["True positives","False positives","True negatives","False negatives"],"correctIndex":3,"explanation":"False negatives. Lowering sensitivity trades noise for blindness: fewer false alarms, but real attacks start slipping through unalerted. The tell: sensitivity down = false positives drop, false negatives rise; sensitivity up = the reverse. Tuning is choosing which error you can live with."},
  {"id":"q417","domain":"D4","family":"false-pos-neg","question":"A monitoring platform flags a legitimate scheduled data sync as malicious exfiltration, raising an incident when no real threat exists. What is this outcome called?","options":["False negative","False positive","True positive","True negative"],"correctIndex":1,"explanation":"False positive. An alert on benign activity is the false alarm: it costs analyst time but hides nothing. The tell: false positive = alert without a threat, false negative = threat without an alert, true positive = alert on a real threat, true negative = correct silence."},
  {"id":"q418","domain":"D4","family":"false-pos-neg","question":"A vulnerability scan declares a server clean, but the server actually carries an unpatched, exploitable flaw the scanner simply failed to find. What is this result?","options":["True negative","False negative","False positive","True positive"],"correctIndex":1,"explanation":"False negative. The scan said safe when it was not - a real weakness went unreported. The tell: false negative = missed real problem, true negative = correctly reported clean, false positive = flagged a non-issue, true positive = correctly found a real issue."},
  {"id":"q419","domain":"D4","family":"false-pos-neg","question":"A detection engineering course argues the false negative is more dangerous than the false positive. What makes the false negative worse?","options":["A real threat went undetected and unaddressed","An analyst wasted time investigating a harmless alert","A benign event was correctly ignored","A genuine threat was correctly blocked"],"correctIndex":0,"explanation":"A real threat slipped through silently. False positives waste time; false negatives let attacks proceed with no one aware a response is needed. The tell: false positive = costs attention, false negative = costs the breach nobody saw."},
  {"id":"q420","domain":"D4","family":"cve-cvss","question":"A vulnerability advisory references one specific, publicly known flaw by its unique catalog identifier so every vendor and tool can point at the same issue. Which element is the identifier?","options":["CVSS","CVE","Exposure factor","Vulnerability classification"],"correctIndex":1,"explanation":"CVE. Common Vulnerabilities and Exposures entries are unique catalog IDs naming one specific public vulnerability. The tell: CVE = the name/ID of the flaw, CVSS = the 0-10 severity score, exposure factor = percent of asset value lost, vulnerability classification = grouping findings by type."},
  {"id":"q421","domain":"D4","family":"cve-cvss","question":"A remediation dashboard sorts findings by a standardized number from 0 to 10 expressing each vulnerability's severity. Which element supplies that number?","options":["CVSS","CVE","Environmental variables","Risk tolerance"],"correctIndex":0,"explanation":"CVSS. The Common Vulnerability Scoring System produces the 0-10 severity rating used for prioritization. The tell: CVSS = the score, CVE = the identifier, environmental variables = your customization of the score, risk tolerance = how much deviation you will absorb before acting."},
  {"id":"q422","domain":"D4","family":"cve-cvss","question":"In a war-room briefing an analyst says, \"the flaw is tracked as CVE-2021-44228.\" In that sentence, the string CVE-2021-44228 is functioning as which element?","options":["CVE","CVSS","Exposure factor","Environmental variables"],"correctIndex":0,"explanation":"CVE. The string is a catalog identifier naming exactly one public vulnerability (Log4Shell); it says nothing about severity. The tell: CVE = the ID being cited, CVSS = the severity number that would accompany it, exposure factor = loss percentage, environmental variables = score adjustments."},
  {"id":"q423","domain":"D4","family":"cve-cvss","question":"A patch team sees a new finding rated 9.8 and immediately classifies it critical, jumping it to the front of the queue. Which element produced that 9.8?","options":["Exposure factor","Risk tolerance","CVSS","CVE"],"correctIndex":2,"explanation":"CVSS. A 9.8 is a CVSS base score in the critical band, which is exactly what drives patch prioritization. The tell: CVSS = the numeric severity, CVE = the flaw's name, exposure factor = percent of asset value at risk, risk tolerance = the deviation you will accept before acting."},
  {"id":"q424","domain":"D4","family":"cve-cvss","question":"Building a quantitative model, a risk analyst estimates a successful ransomware hit would wipe out 60 percent of a server's asset value. In risk terminology, that 60 percent figure is the what?","options":["Exposure factor","Environmental variables","CVSS","Vulnerability classification"],"correctIndex":0,"explanation":"Exposure factor. The percentage of an asset's value lost in one incident is the EF, which multiplies asset value to give SLE. The tell: exposure factor = percent of value lost, CVSS = vulnerability severity, environmental variables = CVSS customization, vulnerability classification = grouping by type."},
  {"id":"q425","domain":"D4","family":"cve-cvss","question":"Two companies score the identical vulnerability differently: one adjusted the base metrics to reflect that the affected system is internet-facing and business-critical in ITS network. Which CVSS element permits this adjustment?","options":["Exposure factor","CVE","Risk tolerance","Environmental variables"],"correctIndex":3,"explanation":"Environmental variables. The environmental metric group tailors the base score to your own deployment's exposure and asset criticality, so the same flaw can rate differently in different shops. The tell: environmental variables = your context adjusting the score, CVSS base = the universal number, CVE = the identifier, exposure factor = loss percentage in risk math."},
  {"id":"q426","domain":"D4","family":"cve-cvss","question":"A vulnerability manager groups the quarter's findings by type - injection, misconfiguration, missing patch - and by severity band before assigning them to remediation teams. What is this grouping called?","options":["CVE","CVSS","Vulnerability classification","Exposure factor"],"correctIndex":2,"explanation":"Vulnerability classification. Sorting findings into categories by type and severity for handling is classification. The tell: vulnerability classification = grouping the findings, CVE = one flaw's identifier, CVSS = one flaw's score, exposure factor = the loss percentage."},
  {"id":"q427","domain":"D4","family":"cve-cvss","question":"A junior analyst asks for the \"CVE score\" of a new finding. The senior corrects the phrasing: the CVE entry itself carries no severity number - that comes from a different element entirely. Which element actually supplies the severity number?","options":["CVE","CVSS","Exposure factor","Environmental variables"],"correctIndex":1,"explanation":"CVSS. The CVE names the flaw; the CVSS scores it. Conflating them is the classic twin-term trap this family exists to kill. The tell: CVE = identity, CVSS = severity. An ID cannot be critical; a score cannot be exploited."},
  {"id":"q428","domain":"D4","family":"cve-cvss","question":"Two scanners report the same flaw under their own product-specific names, confusing the ticket queue. Which element gives analysts one standard, vendor-neutral name so every tool, advisory, and ticket refers to the same vulnerability?","options":["CVSS","Exposure factor","CVE","Vulnerability classification"],"correctIndex":2,"explanation":"CVE. The shared catalog identifier is precisely what lets different tools and advisories converge on one name for one flaw. The tell: CVE = the universal identifier, CVSS = the severity score, vulnerability classification = local grouping, exposure factor = loss percentage."},
  {"id":"q429","domain":"D4","family":"cve-cvss","question":"A bank normally allows 30 days to fix medium-severity findings, but a new flaw on its payment platform pushes the risk further from that baseline than the bank is prepared to absorb, so it patches immediately. The amount of deviation an organization will absorb on a specific risk before acting is its what?","options":["CVSS","Exposure factor","Environmental variables","Risk tolerance"],"correctIndex":3,"explanation":"Risk tolerance. Tolerance is the acceptable deviation around the norm for a specific risk; exceed it and action triggers regardless of standard timelines. The tell: risk tolerance = how far past the line you will let one risk drift, CVSS = the flaw's severity, environmental variables = score tailoring, exposure factor = loss percentage."},
  {"id":"q430","domain":"D4","family":"cve-cvss","question":"During a CISA advisory briefing, an analyst points out that the flaw under discussion carries a standardized, vendor-neutral label so every bulletin, scanner, and vendor advisory can point to the same catalog entry. Which element is this label?","options":["CVSS","Vulnerability classification","CVE","Environmental variables"],"correctIndex":2,"explanation":"CVE. The vendor-neutral catalog label naming one specific flaw is the CVE entry. The tell: CVE = the universal name, CVSS = the severity number, vulnerability classification = local grouping by type, environmental variables = score adjustments for one environment."},
  {"id":"q431","domain":"D4","family":"cve-cvss","question":"In a vulnerability management program, what does a CVE entry actually function as?","options":["A 0 to 10 score expressing how severe the flaw is","The unique vendor-neutral identifier naming one specific known vulnerability","The percentage of an asset's value lost when the flaw is exploited","The set of local modifiers that adjust a published score for one environment"],"correctIndex":1,"explanation":"CVE = the identifier. It names exactly one publicly known vulnerability and carries no severity of its own. The tell: CVE = identity, CVSS = the 0-10 severity, exposure factor = the loss percentage, environmental variables = the local score modifiers."},
  {"id":"q432","domain":"D4","family":"cve-cvss","question":"A scoring framework combines base, temporal, and environmental metric groups into one number that expresses how severe a vulnerability is. Which element is this?","options":["Exposure factor","Vulnerability classification","Risk tolerance","CVSS"],"correctIndex":3,"explanation":"CVSS. Base, temporal, and environmental metric groups are the CVSS structure, producing the 0-10 severity score. The tell: CVSS = the scoring framework, exposure factor = risk-math loss percentage, vulnerability classification = grouping findings, risk tolerance = acceptable deviation before acting."},
  {"id":"q433","domain":"D4","family":"cve-cvss","question":"A finding in a scan report carries a CVSS rating. That rating is best described as which of the following?","options":["A 0 to 10 numeric severity score for the vulnerability","A catalog identifier that uniquely names the vulnerability","A grouping of findings by weakness type and severity band","The share of asset value expected to be lost in one event"],"correctIndex":0,"explanation":"CVSS = the 0-10 severity score. It quantifies how bad the flaw is, not what it is called. The tell: CVSS = severity number, CVE = the name, vulnerability classification = the grouping, exposure factor = the loss share in risk calculations."},
  {"id":"q434","domain":"D4","family":"cve-cvss","question":"In quantitative risk analysis, which term names the percentage of an asset's value that is lost when a particular threat is actually realized?","options":["Environmental variables","Exposure factor","CVSS","Risk tolerance"],"correctIndex":1,"explanation":"Exposure factor. The EF is the loss percentage per event, multiplied by asset value to yield single loss expectancy. The tell: exposure factor = percent of value lost, CVSS = vulnerability severity, environmental variables = CVSS tailoring, risk tolerance = acceptable deviation."},
  {"id":"q435","domain":"D4","family":"cve-cvss","question":"A team raises a flaw's score above the vendor's published base value because the vulnerable database in THEIR deployment stores regulated health records, raising the confidentiality requirement. Which CVSS element reflects such local security requirements?","options":["CVE","Vulnerability classification","Environmental variables","Exposure factor"],"correctIndex":2,"explanation":"Environmental variables. The environmental metrics adjust the base score to one organization's deployment - asset criticality and security requirements included. The tell: environmental variables = your context reshaping the score, base CVSS = the universal published value, CVE = the name, exposure factor = risk-math loss percentage."},
  {"id":"q436","domain":"D4","family":"cve-cvss","question":"A vulnerability manager sorts each new finding into a category - improper input handling, broken authentication, missing patch - so similar weaknesses are tracked and fixed together. Which activity is this?","options":["Vulnerability classification","CVSS scoring","CVE assignment","Setting the exposure factor"],"correctIndex":0,"explanation":"Vulnerability classification. Categorizing findings by weakness type for collective management is classification. The tell: classification = sorting into categories, CVSS scoring = assigning the severity number, CVE assignment = giving the flaw its public ID, exposure factor = estimating loss percentage."},
  {"id":"q437","domain":"D4","family":"cve-cvss","question":"A hospital board accepts only minimal variance from its patch-timeline targets on systems tied to patient safety, and demands immediate action the moment a finding exceeds that variance. That acceptable amount of variance on a specific risk is the hospital's what?","options":["Exposure factor","Environmental variables","Risk tolerance","Vulnerability classification"],"correctIndex":2,"explanation":"Risk tolerance. Tolerance is the deviation from the norm an organization will absorb on a given risk before it must act. The tell: risk tolerance = the acceptable wiggle room per risk, exposure factor = loss percentage, environmental variables = CVSS context adjustments, classification = grouping findings."},
  {"id":"q438","domain":"D4","family":"cve-cvss","question":"Before publicly disclosing a newly discovered flaw, a researcher asks the numbering authority to reserve a unique identifier in the public catalog so all future advisories reference the same entry. Which element is being reserved?","options":["CVE","CVSS","Exposure factor","Environmental variables"],"correctIndex":0,"explanation":"CVE. Researchers reserve a CVE ID pre-disclosure so the flaw has one public name from day one; no score exists yet. The tell: CVE = the reservable identifier, CVSS = the score assigned when analyzed, exposure factor and environmental variables = risk and scoring adjustments, not names."},
  {"id":"q439","domain":"D4","family":"cve-cvss","question":"Deciding whether a finding lands in the high or the critical remediation band, an analyst simply reads the single numeric value assigned to the flaw. Which element produced that value?","options":["Vulnerability classification","CVE","Risk tolerance","CVSS"],"correctIndex":3,"explanation":"CVSS. The numeric value that maps to severity bands (critical 9.0-10.0, high 7.0-8.9) is the CVSS score. The tell: CVSS = the number that sets the band, CVE = the flaw's identity, vulnerability classification = the banding exercise itself, risk tolerance = when you must act."},
  {"id":"q440","domain":"D4","family":"vuln-response","question":"A legacy application server runs software its vendor stopped patching, and the business cannot retire it this year. Unable to fix the flaws, the team wraps the server in strict network access rules and enhanced monitoring as alternate protection. What is this response called?","options":["Patching","Compensating control","Exception","Insurance"],"correctIndex":1,"explanation":"Compensating control. When the primary fix (patching) is impossible, alternate safeguards that reduce the same risk are compensating controls. An exception would be formally accepting the risk without adding protection. The tell: compensating control = substitute protection, exception = documented acceptance, patching = the unavailable primary fix, insurance = transferring financial impact."},
  {"id":"q441","domain":"D4","family":"vuln-response","question":"A critical finding is marked remediated after the patch deploys. Before closing the ticket, the analyst runs the vulnerability scanner against the host once more to confirm the finding no longer appears. Which validation step is this?","options":["Audit","Segmentation","Insurance","Rescanning"],"correctIndex":3,"explanation":"Rescanning. Re-running the scan to verify the fix actually removed the finding is the standard remediation validation. The tell: rescanning = re-test to confirm the fix, audit = independent review of the process, segmentation = a mitigation, not a validation, insurance = risk transfer."},
  {"id":"q442","domain":"D4","family":"vuln-response","question":"A low-severity flaw sits in a rarely used system that would cost more to fix than it is worth. Management instead purchases a cyber insurance policy to absorb any financial loss if the flaw is ever exploited. Which vulnerability response is this?","options":["insurance","patching","segmentation","exception"],"correctIndex":0,"explanation":"Insurance. Transferring the financial impact of the risk to an insurer is the insurance response, a form of risk transference. The tell: insurance = someone else pays if it happens, patching = eliminate the flaw, segmentation = contain the exposure, exception = formally accept it as-is."},
  {"id":"q443","domain":"D4","family":"vuln-response","question":"After remediation, instead of an automated rescan, an independent reviewer manually examines the system's controls, configurations, and procedures against requirements to confirm the fix is real and durable. Which validation method is this?","options":["rescanning","audit","verification","patching"],"correctIndex":1,"explanation":"Audit. A human review of controls and procedures against requirements is an audit, the manual counterpart to a rescan. The tell: audit = independent review against requirements, rescanning = automated re-test, verification = the general goal both serve, patching = the fix itself."},
  {"id":"q444","domain":"D4","family":"monitoring","question":"A SOC drowning in low-value alerts adjusts SIEM rule thresholds and suppresses known-benign patterns, cutting noise while preserving true detections. What is this activity called?","options":["Log aggregation","Archiving","Quarantine","Alert tuning"],"correctIndex":3,"explanation":"Alert tuning. Adjusting rules and thresholds to reduce false positives without losing real detections is tuning, an ongoing SOC discipline. The tell: alert tuning = refine what fires, log aggregation = collect logs centrally, archiving = long-term retention, quarantine = isolating a suspicious item."},
  {"id":"q445","domain":"D4","family":"monitoring","question":"A platform continuously pulls log data from firewalls, domain controllers, servers, and endpoints into one central searchable repository where analysts run correlation queries. Which function is this?","options":["Log aggregation","Alerting","Reporting","Archiving"],"correctIndex":0,"explanation":"Log aggregation. Centralizing logs from many sources into one repository is aggregation, the foundation a SIEM's correlation and alerting build on. The tell: log aggregation = gather it all in one place, alerting = fire on matches, reporting = summarize for humans, archiving = retain long term."},
  {"id":"q446","domain":"D4","family":"monitoring","question":"A two-year log retention requirement forces the team to move older log data into compressed long-term storage, where it remains retrievable for audits but no longer burdens the active analysis platform. Which function is this?","options":["archiving","log aggregation","alerting","quarantine"],"correctIndex":0,"explanation":"Archiving. Long-term retention storage outside the hot analysis path is archiving, driven by compliance retention rules. The tell: archiving = long-term cold retention, log aggregation = central collection for analysis, alerting = firing on matches, quarantine = isolating suspicious items."},
  {"id":"q447","domain":"D4","family":"monitoring","question":"When an endpoint tool flags a downloaded file as suspicious, it immediately moves the file into an isolated store where it cannot execute, pending analyst review. Which monitoring action is this?","options":["alerting","scanning","quarantine","archiving"],"correctIndex":2,"explanation":"Quarantine. Isolating a suspicious item so it cannot run while awaiting review is quarantine. The tell: quarantine = sealed off but preserved, alerting = telling humans, scanning = looking for problems, archiving = long-term storage of old data."},
  {"id":"q448","domain":"D4","family":"monitoring","question":"The moment a SIEM correlation rule matches - five failed logins followed by a success from a new country - the platform pages the on-call analyst automatically. Which monitoring function fired?","options":["archiving","log aggregation","alerting","quarantine"],"correctIndex":2,"explanation":"Alerting. Automatically notifying humans when a detection rule matches is the alerting function - aggregation feeds it, tuning refines it. The tell: alerting = notify on match, log aggregation = collect centrally first, archiving = long-term storage, quarantine = isolate a suspicious item."},
  {"id":"q449","domain":"D4","family":"monitoring","question":"Each month the security team compiles dashboards summarizing incident counts, mean response times, and top attack categories for leadership review. Which monitoring function is this?","options":["reporting","alert tuning","scanning","log aggregation"],"correctIndex":0,"explanation":"Reporting. Summarizing security activity into digestible metrics for stakeholders is reporting - the human-consumption layer above raw alerts. The tell: reporting = summaries for people, alerting = real-time notification, alert tuning = refining what fires, log aggregation = the underlying collection."},
  {"id":"q450","domain":"D4","family":"security-tools","question":"Investigating suspected exfiltration, an engineer needs records showing which internal hosts talked to which external addresses, when, and how much data moved - but does not need full packet contents. Which tool provides exactly this?","options":["SIEM","NetFlow","SNMP traps","DLP"],"correctIndex":1,"explanation":"NetFlow. Flow records capture conversation metadata - endpoints, timing, volume - without payloads, ideal for spotting exfiltration patterns. The tell: NetFlow = who talked to whom and how much, SIEM = central log correlation, SNMP traps = device fault alerts, DLP = blocking sensitive data leaving."},
  {"id":"q451","domain":"D4","family":"security-tools","question":"Compliance requires that employees be prevented from emailing files containing credit card numbers outside the company, with attempts detected and blocked automatically. Which tool enforces this?","options":["DLP","SIEM","Vulnerability scanner","NetFlow"],"correctIndex":0,"explanation":"DLP. Data loss prevention inspects outbound content for sensitive patterns like card numbers and blocks the transfer. The tell: DLP = stop sensitive data leaving, SIEM = correlate and alert on logs, vulnerability scanner = find unpatched flaws, NetFlow = traffic metadata."},
  {"id":"q452","domain":"D4","family":"security-tools","question":"When a switch's temperature crosses a threshold, the switch itself immediately sends an unsolicited alert message to the network management station without being polled. Which mechanism is this?","options":["NetFlow","SCAP","SNMP traps","SIEM"],"correctIndex":2,"explanation":"SNMP traps. A trap is the device-initiated, unsolicited notification to the manager, unlike normal SNMP polling where the manager asks. The tell: SNMP trap = device pushes the alert, SNMP polling = manager pulls status, NetFlow = traffic metadata, SIEM = log correlation platform."},
  {"id":"q453","domain":"D4","family":"security-tools","question":"An organization runs security tools from three vendors and wants their configuration and vulnerability checks automated and comparable through one common machine-readable format. Which standard enables this?","options":["SIEM","DLP","Antivirus","SCAP"],"correctIndex":3,"explanation":"SCAP. The Security Content Automation Protocol standardizes how tools express and exchange configuration and vulnerability checks, making multi-vendor results comparable. The tell: SCAP = the common automation format, SIEM = log platform, DLP = data-leak blocking, antivirus = malware detection."},
  {"id":"q454","domain":"D4","family":"security-tools","question":"A SOC needs one platform that ingests logs from firewalls, servers, and applications enterprise-wide, correlates events across them, and raises an alert when the combined pattern looks like an attack no single log would reveal. Which tool is this?","options":["SIEM","NetFlow","SNMP traps","vulnerability scanner"],"correctIndex":0,"explanation":"SIEM. Centralized ingestion plus cross-source correlation and alerting is the security information and event management platform. The tell: SIEM = correlate everything, alert on patterns, NetFlow = traffic metadata, SNMP traps = device fault notifications, vulnerability scanner = finds weaknesses, not events."},
  {"id":"q455","domain":"D4","family":"security-tools","question":"Which tool actively probes hosts and applications for known weaknesses - missing patches, insecure configurations, default credentials - and produces a prioritized findings report?","options":["antivirus","vulnerability scanner","SIEM","DLP"],"correctIndex":1,"explanation":"Vulnerability scanner. Active probing for known weaknesses with a findings report is the scanner's function. The tell: vulnerability scanner = finds flaws before attackers, antivirus = catches malware on hosts, SIEM = correlates events, DLP = stops data leaving."},
  {"id":"q456","domain":"D4","family":"security-tools","question":"A hardening project measures every server against a consensus-developed set of recommended secure configuration settings, such as the CIS guides. What is this resource called?","options":["SCAP","NetFlow","SIEM","benchmarks"],"correctIndex":3,"explanation":"Benchmarks. Consensus secure-configuration guides like the CIS Benchmarks are the measuring stick for hardening. The tell: benchmarks = the recommended settings themselves, SCAP = the automation format for checking them, SIEM = event correlation, NetFlow = traffic metadata."},
  {"id":"q457","domain":"D4","family":"security-tools","question":"On each workstation, software scans files against known-malware signatures and heuristics, blocking and quarantining anything that matches before it executes. Which tool is this?","options":["SIEM","antivirus","NetFlow","SCAP"],"correctIndex":1,"explanation":"Antivirus. Host-based signature and heuristic malware blocking is the antivirus/anti-malware role - the endpoint's baseline defense. The tell: antivirus = block known malware on the host, SIEM = correlate logs centrally, NetFlow = traffic metadata, SCAP = the automation format for checks."},
  {"id":"q458","domain":"D4","family":"security-tools","question":"With no packet contents available, an analyst notices one workstation's flow records show gigabytes streaming nightly to an IP no other host talks to - volume and destination alone reveal the exfiltration. Which tool produced the records?","options":["DLP","vulnerability scanner","antivirus","NetFlow"],"correctIndex":3,"explanation":"NetFlow. Flow records - endpoints, volumes, timing, no payloads - are exactly enough to spot who talks to whom and how much, exposing exfiltration patterns. The tell: NetFlow = conversation metadata, DLP = content inspection and blocking, vulnerability scanner = finds flaws, antivirus = catches malware."},
  {"id":"q459","domain":"D4","family":"firewall-config","question":"A network architect places the public web and mail servers on a separate buffer network sandwiched between the internet and the internal LAN, so internet users can reach those services without ever touching the internal network. What is this design element?","options":["Access list","Screened subnet","Firewall rule","Signature"],"correctIndex":1,"explanation":"Screened subnet. The buffer network hosting public-facing services between the internet and the LAN is the screened subnet (the SY0-701 term for the older perimeter-network concept). The tell: screened subnet = the buffer zone itself, access list/firewall rule = the filtering entries protecting it, signature = a detection pattern."},
  {"id":"q460","domain":"D4","family":"firewall-config","question":"An IPS drops a packet because its contents exactly match a stored pattern for a specific known exploit. What is this detection method called?","options":["Signature","Trend","Firewall rule","Screened subnet"],"correctIndex":0,"explanation":"Signature. Matching traffic against stored patterns of known attacks is signature-based detection: precise on known threats, blind to novel ones. The tell: signature = known-pattern match, trend = deviation from behavioral baselines, firewall rule = port/address policy, screened subnet = the buffer network."},
  {"id":"q461","domain":"D4","family":"firewall-config","question":"Instead of matching stored exploit patterns, a sensor learns weeks of normal traffic volume and flags activity that deviates sharply from that baseline. Which detection method is this?","options":["signature","trend","screened subnet","access list"],"correctIndex":1,"explanation":"Trend. Baseline-and-deviation detection is trend (anomaly) analysis, able to spot novel attacks that signatures miss - at the price of more false positives. The tell: trend = deviation from learned normal, signature = match to a known pattern, access list = static filter rules, screened subnet = the buffer network."},
  {"id":"q462","domain":"D4","family":"firewall-config","question":"A router's configuration holds an ordered set of permit and deny statements evaluated top-down against each packet's source, destination, and port to decide what passes. What is this construct called?","options":["signature","trend","access list","screened subnet"],"correctIndex":2,"explanation":"Access list. The ordered permit/deny statements filtering packets by address and port are an ACL, evaluated first-match. The tell: access list = the rule list itself, signature = an attack pattern, trend = baseline deviation, screened subnet = the network zone the rules often protect."},
  {"id":"q463","domain":"D4","family":"web-filter","question":"To keep users off malware domains, the security team configures the company resolver to simply refuse to return IP addresses for any domain on a known-bad list; the connection dies before it starts. Which filtering technique is this?","options":["Centralized proxy","Content categorization","DNS filtering","Reputation"],"correctIndex":2,"explanation":"DNS filtering. Blocking at name resolution - no answer, no connection - is DNS filtering, cheap and effective at scale. The tell: DNS filtering = block the lookup, centralized proxy = traffic routes through a filtering middlebox, content categorization = classify sites by topic, reputation = score-based blocking."},
  {"id":"q464","domain":"D4","family":"web-filter","question":"Remote laptops need web filtering that works at airports and home offices, far from the corporate network, so the team installs filtering software directly on every device. Which approach is this?","options":["Agent-based","Centralized proxy","Content categorization","DNS filtering"],"correctIndex":0,"explanation":"Agent-based. Filtering software installed on each endpoint travels with the device, working wherever it connects. The tell: agent-based = filtering lives on the device, centralized proxy = filtering lives on the network path, DNS filtering = blocking lookups, content categorization = the site-classification engine any of them may use."},
  {"id":"q465","domain":"D4","family":"web-filter","question":"The web filter blocks any site classified under the gambling or adult topics, no matter the specific URL, because policy bans whole classes of content rather than individual addresses. Which technique is this?","options":["content categorization","reputation","centralized proxy","DNS filtering"],"correctIndex":0,"explanation":"Content categorization. Classifying sites by topic and blocking whole categories enforces policy by content class. The tell: content categorization = blocked by topic, reputation = blocked by risk score, centralized proxy = the on-path architecture, DNS filtering = blocking the name lookup."},
  {"id":"q466","domain":"D4","family":"web-filter","question":"Every employee web request is forced through one on-network appliance that inspects, filters, and logs it before forwarding to the internet; devices cannot bypass it. Which web-filter architecture is this?","options":["reputation","URL scanning","content categorization","centralized proxy"],"correctIndex":3,"explanation":"Centralized proxy. Forcing all traffic through one inspecting middlebox is the centralized proxy architecture, powerful on-network but useless for roaming laptops (that is what agents are for). The tell: centralized proxy = one on-path filter point, agent-based = filtering on each device, categorization/reputation = the classification engines either can use."},
  {"id":"q467","domain":"D4","family":"os-hardening","question":"A Windows administrator must push a standardized security configuration - password policy, disabled services, audit settings - to thousands of domain-joined workstations from one central point, reapplied automatically. Which mechanism does this?","options":["SELinux","Group Policy","AppArmor","Local Security Policy"],"correctIndex":1,"explanation":"Group Policy. Centralized, domain-wide Windows configuration enforcement is Group Policy's job. The tell: Group Policy = central control of domain-joined Windows, Local Security Policy = one standalone machine, SELinux/AppArmor = Linux mandatory access control."},
  {"id":"q468","domain":"D4","family":"os-hardening","question":"A Linux hardening standard requires mandatory access control: every process is confined to a security context restricting exactly which files and ports it may touch, constraints even root cannot override. Which mechanism, using labeled security contexts, is this?","options":["Group Policy","Local Security Policy","SELinux","AppArmor"],"correctIndex":2,"explanation":"SELinux. Label-based security contexts enforcing mandatory access control on Linux is SELinux; AppArmor achieves similar confinement using path-based profiles instead. The tell: SELinux = labels/contexts, AppArmor = path-based profiles, Group Policy = Windows domains, Local Security Policy = a standalone Windows box."},
  {"id":"q469","domain":"D4","family":"os-hardening","question":"A kiosk PC runs Windows but is deliberately not joined to any domain. Since no domain-level configuration reaches it, which tool enforces its password and audit policy?","options":["Group Policy","SELinux","Local Security Policy","AppArmor"],"correctIndex":2,"explanation":"Local Security Policy. A standalone Windows machine gets its security settings from Local Security Policy; Group Policy requires domain membership to apply centrally. The tell: Local Security Policy = one non-domain Windows machine, Group Policy = centralized domain enforcement, SELinux/AppArmor = Linux MAC frameworks."},
  {"id":"q470","domain":"D4","family":"os-hardening","question":"On a Red Hat web server, the admin confines the web daemon inside a labeled security context: even fully compromised, it cannot read files outside its label, and root cannot lift the confinement. Which mechanism is this?","options":["Group Policy","SELinux","AppArmor","Local Security Policy"],"correctIndex":1,"explanation":"SELinux. Labeled security contexts enforcing mandatory access control on Red Hat systems is SELinux. The tell: SELinux = label/context-based MAC (Red Hat family), AppArmor = path-based profiles (Ubuntu/SUSE), Group Policy = Windows domain management, Local Security Policy = standalone Windows."},
  {"id":"q471","domain":"D4","family":"os-hardening","question":"In Active Directory, an admin links a configuration object to an organizational unit, and every computer in that OU automatically receives the same password policy and disabled-services settings. Which mechanism does this?","options":["Local Security Policy","SELinux","AppArmor","Group Policy"],"correctIndex":3,"explanation":"Group Policy. GPOs linked to OUs delivering centralized settings across domain-joined machines is Group Policy at work. The tell: Group Policy = domain-wide central enforcement, Local Security Policy = one standalone machine, SELinux/AppArmor = Linux MAC systems."},
  {"id":"q472","domain":"D4","family":"os-hardening","question":"On an Ubuntu server, an admin restricts an application with path-based profiles spelling out exactly which files and capabilities the program may touch - the profile-per-program alternative to label-based Linux mandatory access control. Which mechanism is this?","options":["SELinux","Group Policy","AppArmor","Local Security Policy"],"correctIndex":2,"explanation":"AppArmor. Path-based per-program profiles are AppArmor's model, versus SELinux's system-wide labels. The tell: AppArmor = path-based profiles, common on Ubuntu, SELinux = label-based contexts, common on Red Hat, Group Policy/Local Security Policy = Windows mechanisms."},
  {"id":"q473","domain":"D4","family":"os-hardening","question":"A Linux engineer explains the two mandatory access control options: one confines programs using security labels attached to every file and process; the other uses per-program profiles listing allowed file paths. Which pairing is correct?","options":["SELinux = path profiles; AppArmor = labels","SELinux = labels; AppArmor = path-based profiles","Both use Group Policy objects","Both only run on Windows"],"correctIndex":1,"explanation":"SELinux labels everything; AppArmor profiles programs by path. Same mandatory access control goal, different models - labels are more thorough, paths are simpler to manage. The tell: SELinux = label/context-based (Red Hat family), AppArmor = path-based profiles (Ubuntu/SUSE), Group Policy = Windows domains."},
  {"id":"q474","domain":"D4","family":"email-security","question":"A domain owner publishes a DNS record listing the only mail servers authorized to send for the domain. Receiving servers check each arriving message's source IP against that list. Which mechanism is this?","options":["SPF","DKIM","DMARC","Secure email gateway"],"correctIndex":0,"explanation":"SPF. The Sender Policy Framework is the DNS-published list of authorized sending IPs, checked by receivers. The tell: SPF = authorized sender IPs in DNS, DKIM = cryptographic signature on the message, DMARC = the policy tying both together, secure email gateway = the filtering appliance."},
  {"id":"q475","domain":"D4","family":"email-security","question":"Every outbound message from a domain carries a header containing a cryptographic signature generated with the domain's private key. Receivers verify it with a public key from DNS, proving the message body was not altered and genuinely came from the domain. Which mechanism is this?","options":["DMARC","SPF","DKIM","Secure email gateway"],"correctIndex":2,"explanation":"DKIM. DomainKeys Identified Mail signs messages cryptographically, giving integrity and domain authenticity that travel with the message itself. The tell: DKIM = signature in the headers, SPF = source-IP check against DNS, DMARC = policy and reporting over both, gateway = the filtering box."},
  {"id":"q476","domain":"D4","family":"email-security","question":"Messages relayed through a third-party forwarding service keep failing the recipient's IP-based sender check, because the forwarder's IP is not on the origin domain's list. Yet a second authentication check still passes, since its verification data travels inside the message headers. Which mechanism provides the second check?","options":["Secure email gateway","DMARC","SPF","DKIM"],"correctIndex":3,"explanation":"DKIM. Its signature rides in the headers and survives forwarding, while SPF breaks because the forwarder's IP is not authorized. This survival difference is a classic SPF-vs-DKIM discriminator. The tell: DKIM = travels with the message, SPF = tied to the sending IP, DMARC = the policy layer, gateway = perimeter filtering."},
  {"id":"q477","domain":"D4","family":"email-security","question":"An appliance at the mail perimeter scans every inbound and outbound message for spam, malicious attachments, and sensitive data leaks before anything reaches a mailbox or leaves the company. Which component is this?","options":["Secure email gateway","DMARC","DKIM","SPF"],"correctIndex":0,"explanation":"Secure email gateway. The inline scanning appliance or service at the mail boundary is the gateway; the DNS-based records authenticate senders but scan nothing. The tell: secure email gateway = the filtering box, SPF/DKIM/DMARC = DNS-published authentication and policy records."},
  {"id":"q478","domain":"D4","family":"email-security","question":"Which email mechanism validates a message purely by comparing the sending server's IP address against an authorized list published in DNS, while doing nothing to verify the message's content?","options":["DKIM","DMARC","SPF","Secure email gateway"],"correctIndex":2,"explanation":"SPF. It answers exactly one question: did this message arrive from an IP the domain authorized? Content integrity is DKIM's department. The tell: SPF = IP check only, DKIM = content signature, DMARC = what to do with failures, gateway = perimeter scanning."},
  {"id":"q479","domain":"D4","family":"email-security","question":"One mechanism takes the SPF and DKIM results, applies domain alignment, and tells receiving servers whether to deliver, quarantine, or reject mail that fails - publishing that instruction in DNS. Which mechanism is this?","options":["DMARC","DKIM","SPF","Secure email gateway"],"correctIndex":0,"explanation":"DMARC. It is the policy layer over SPF and DKIM: alignment plus a published none/quarantine/reject instruction for failures. The tell: DMARC = the decision policy and reporting, SPF = IP authorization, DKIM = message signature, gateway = the filtering appliance."},
  {"id":"q480","domain":"D4","family":"email-security","question":"A receiving server recomputes a hash of an arriving message and compares it against a value that was signed with the sender domain's private key, verifying with the public key fetched from DNS. Which mechanism is in use?","options":["SPF","DKIM","Secure email gateway","DMARC"],"correctIndex":1,"explanation":"DKIM. Hash plus private-key signature verified via a DNS-published public key is the DKIM verification flow, proving integrity and origin. The tell: DKIM = the cryptographic check, SPF = the IP list check, DMARC = policy over both, gateway = content filtering."},
  {"id":"q481","domain":"D4","family":"email-security","question":"A security team knows attackers spoof its domain but has zero visibility into the scale. It wants recurring aggregate reports from receiving servers worldwide about all mail claiming to come from the domain. Which mechanism delivers those reports?","options":["SPF","DKIM","Secure email gateway","DMARC"],"correctIndex":3,"explanation":"DMARC. Its reporting function (aggregate RUA reports) is the only mechanism here that sends the domain owner feedback about mail claiming its name. The tell: DMARC = policy plus reporting back to the owner, SPF/DKIM = checks with no feedback loop, gateway = local filtering."},
  {"id":"q482","domain":"D4","family":"email-security","question":"A domain already publishes SPF and DKIM, yet spoofed mail failing both checks still lands in recipients' inboxes because receivers have no instruction for handling failures. Which mechanism must be added so receivers are told to reject it?","options":["SPF","DMARC","DKIM","Secure email gateway"],"correctIndex":1,"explanation":"DMARC. SPF and DKIM only produce pass/fail results; without a DMARC policy, receivers decide for themselves. Publishing p=reject supplies the missing instruction. The tell: DMARC = tells receivers what to DO with failures, SPF/DKIM = merely generate the results."},
  {"id":"q483","domain":"D4","family":"email-security","question":"Of the major email security controls, which one is an inline filtering appliance or cloud service, rather than an authentication record published in DNS?","options":["SPF","DKIM","DMARC","Secure email gateway"],"correctIndex":3,"explanation":"Secure email gateway. It is a scanning device or service in the mail path; SPF, DKIM, and DMARC are all DNS-published mechanisms. The tell: gateway = hardware/service that filters content, the other three = records that authenticate senders and set policy."},
  {"id":"q484","domain":"D4","family":"email-security","question":"A marketing team adopts a cloud email platform that must send campaigns as the corporate domain. An admin edits one DNS text record, adding the vendor's outbound mail servers to the set of hosts permitted to send for the domain. Which mechanism is being updated?","options":["SPF","DKIM","DMARC","secure email gateway"],"correctIndex":0,"explanation":"SPF. The DNS record listing which hosts may send for the domain is the SPF record; authorizing a new sender means adding its addresses there. The tell: SPF = the authorized-senders list in DNS, DKIM = the message signature, DMARC = policy over both, gateway = the filtering appliance."},
  {"id":"q485","domain":"D4","family":"email-security","question":"A security team wants spoofed mail that fails authentication to be actively rejected by receivers, and wants to name the mailbox where receivers send their feedback reports. Which single DNS policy record controls both the enforcement action and the reporting destination?","options":["SPF","DKIM","DMARC","secure email gateway"],"correctIndex":2,"explanation":"DMARC. The p=reject enforcement instruction and the rua reporting address both live in the DMARC record. The tell: DMARC = failure handling plus reporting, SPF = who may send, DKIM = the signature, gateway = the scanning box."},
  {"id":"q486","domain":"D4","family":"email-security","question":"Every inbound message is routed through an appliance that detonates attachments in a sandbox, rewrites embedded links through a safe redirect, and strips messages flagged as phishing before delivery. Which component performs this?","options":["SPF","DKIM","DMARC","secure email gateway"],"correctIndex":3,"explanation":"Secure email gateway. Sandboxing, URL rewriting, and phishing filtering are inline content-security functions of the gateway; DNS records authenticate but never scan. The tell: gateway = active content inspection in the mail path, SPF/DKIM/DMARC = authentication and policy records."},
  {"id":"q487","domain":"D4","family":"email-security","question":"A mailing list server appends a footer to every message it relays. Because the message body changed after the origin domain generated its verification data, the receiver's check now fails. Which mechanism does the body modification break?","options":["SPF","DKIM","DMARC","secure email gateway"],"correctIndex":1,"explanation":"DKIM. Its signature covers the message body, so any modification - even an appended footer - invalidates it. SPF does not care about content, only the sending IP. The tell: DKIM = breaks when content changes, SPF = breaks when the sending host changes, DMARC = judges the combined result."},
  {"id":"q488","domain":"D4","family":"email-security","question":"After migrating the outbound mail relay to a new IP block, the team forgot one DNS update. Receivers now flag the company's own mail as coming from an unauthorized host. Which record must be updated with the new relay addresses?","options":["DMARC","SPF","DKIM","secure email gateway"],"correctIndex":1,"explanation":"SPF. Receivers compare the connecting IP to the SPF record's authorized list; a relay move without an SPF update makes legitimate mail look spoofed. The tell: SPF = tied to sending IPs, so infrastructure moves break it, DKIM = tied to the signature, survives IP changes, DMARC = the policy on failures."},
  {"id":"q489","domain":"D4","family":"email-security","question":"A domain already runs both underlying email authentication methods. Which capability does DMARC itself add that SPF and DKIM do not provide on their own?","options":["A cryptographic signature over the message so tampering is detectable","A DNS list of IP addresses permitted to send for the domain","A published policy with alignment telling receivers to quarantine or reject failures and where to send reports","An inline appliance that scans and filters the mail stream"],"correctIndex":2,"explanation":"DMARC adds the decision layer: alignment with the visible From domain, a quarantine/reject instruction for failures, and reporting back to the owner. The tell: SPF = the IP list, DKIM = the signature, DMARC = what receivers should DO about the results, and the feedback loop."},
  {"id":"q490","domain":"D4","family":"email-security","question":"The mail team needs somewhere to build rules that quarantine suspicious inbound messages and force TLS on all mail to a specific partner domain. Which component hosts these mail-flow rules?","options":["SPF","DKIM","DMARC","secure email gateway"],"correctIndex":3,"explanation":"Secure email gateway. Quarantine rules and per-domain TLS enforcement are mail-flow policies configured on the gateway; DNS authentication records have no rule engine. The tell: gateway = configurable mail-flow filtering and routing, SPF/DKIM/DMARC = published authentication records."},
  {"id":"q491","domain":"D4","family":"email-security","question":"To validate an arriving message, the receiving server queries a public key stored at a named selector under the sending domain's DNS, then checks the signature attached to the message against it. Which mechanism relies on this selector-based key lookup?","options":["DKIM","SPF","DMARC","secure email gateway"],"correctIndex":0,"explanation":"DKIM. The selector-based public key in DNS validating a message signature is the DKIM verification flow. The tell: DKIM = selector, public key, signature, SPF = plain list of allowed IPs, DMARC = policy record, gateway = the appliance."},
  {"id":"q492","domain":"D4","family":"email-security","question":"Receivers keep accepting spoofed mail with the company's domain in the envelope sender because nothing tells them which hosts are allowed to send for it. Which record should the company publish FIRST so receivers can check sending IPs against an authorized set?","options":["DMARC","DKIM","secure email gateway","SPF"],"correctIndex":3,"explanation":"SPF. The immediate gap is an authorized-sender list, which is exactly SPF; DKIM and DMARC build on top of it. The tell: SPF = the foundational who-may-send record, DKIM = adds a signature, DMARC = adds policy once the checks exist, gateway = filtering, not authentication."},
  {"id":"q493","domain":"D4","family":"email-security","question":"A message passes both underlying authentication checks, yet it is still treated as failing because the domain in the visible From header does not match the domain that actually authenticated. Which mechanism enforces that From-header matching requirement?","options":["SPF","DKIM","DMARC","secure email gateway"],"correctIndex":2,"explanation":"DMARC. Alignment is DMARC's signature requirement: the authenticated domain must match the From header the user sees, closing the loophole where attackers pass checks on a domain they control while displaying yours. The tell: DMARC = alignment with the visible From, SPF/DKIM = raw pass/fail with no alignment concept."},
  {"id":"q494","domain":"D4","family":"endpoint-detection","question":"Before any laptop gets a network connection, a control checks that it carries current patches, running antivirus, and disk encryption; failures land the device in a quarantine VLAN for remediation. Which technology is this?","options":["EDR","FIM","UBA","NAC"],"correctIndex":3,"explanation":"NAC. Network access control gates admission on device health posture and quarantines the non-compliant. The tell: NAC = health check at the network door, EDR = continuous endpoint activity monitoring and response, FIM = watching critical files for changes, UBA = modeling user behavior for anomalies."},
  {"id":"q495","domain":"D4","family":"endpoint-detection","question":"An agent on every workstation continuously records process launches, file activity, and network connections, and when it recognizes ransomware behavior it automatically isolates the host from the network. Which technology is this?","options":["EDR","XDR","NAC","DLP"],"correctIndex":0,"explanation":"EDR. Endpoint detection and response continuously monitors endpoint activity and can respond automatically, including host isolation. The tell: EDR = deep endpoint recording and response, XDR = the same correlation extended across endpoint, network, email, and cloud, NAC = admission control, DLP = blocking data leaving."},
  {"id":"q496","domain":"D4","family":"endpoint-detection","question":"A vendor platform stitches together detections from endpoints, network sensors, email security, and cloud workloads into one correlated investigation view, so an attack crossing all four shows as one incident. Which technology is this?","options":["EDR","FIM","XDR","UBA"],"correctIndex":2,"explanation":"XDR. Extended detection and response correlates telemetry across multiple layers beyond the endpoint, unifying the investigation. The tell: XDR = cross-layer correlation, EDR = endpoint-only depth, FIM = file change alerts, UBA = user behavior anomalies."},
  {"id":"q497","domain":"D4","family":"endpoint-detection","question":"After a breach involving altered system binaries, a team deploys a control that alerts the moment any critical system or configuration file deviates from its known-good state. Which technology is this?","options":["DLP","UBA","NAC","FIM"],"correctIndex":3,"explanation":"FIM. File integrity monitoring baselines critical files and alerts on any change from known-good. The tell: FIM = watch files for unauthorized change, DLP = stop data exfiltration, NAC = gate network admission, UBA = flag anomalous user behavior."},
  {"id":"q498","domain":"D4","family":"endpoint-detection","question":"A platform learns each user's normal working pattern - login times, locations, data touched - then flags a finance user who suddenly downloads gigabytes of records at 3 a.m. from a new country. Which technology is this?","options":["EDR","NAC","UBA","FIM"],"correctIndex":2,"explanation":"UBA. User behavior analytics baselines normal per-user activity and flags anomalies, catching compromised accounts and insiders that signature tools miss. The tell: UBA = anomalous user behavior, EDR = endpoint process/file/network monitoring, NAC = admission health checks, FIM = file change detection."},
  {"id":"q499","domain":"D4","family":"endpoint-detection","question":"Endpoint software inspects every file being copied to USB storage and blocks any containing data tagged sensitive, logging the attempt for review. Which technology enforces this?","options":["FIM","EDR","DLP","UBA"],"correctIndex":2,"explanation":"DLP. Blocking tagged sensitive data from leaving via removable media is data loss prevention at the endpoint. The tell: DLP = stop sensitive data exfiltration, FIM = alert on file changes, EDR = detect malicious behavior, UBA = flag abnormal user patterns."},
  {"id":"q500","domain":"D4","family":"endpoint-detection","question":"An agent records a trusted baseline of a server's configuration files and registry keys, then reports the instant any monitored item drifts from that known-good state. Which technology is this?","options":["DLP","FIM","EDR","XDR"],"correctIndex":1,"explanation":"FIM. Baseline-and-alert on critical file and registry changes is file integrity monitoring, a staple for detecting tampering and meeting compliance. The tell: FIM = watch known-good files for change, DLP = block data leaving, EDR = behavioral endpoint detection, XDR = correlation across layers."},
  {"id":"q501","domain":"D4","family":"endpoint-detection","question":"A SOC lead complains their endpoint tool sees each host deeply but cannot connect an email lure, the endpoint infection it caused, and the cloud-account abuse that followed into one story. Which technology closes that gap?","options":["XDR","FIM","NAC","DLP"],"correctIndex":0,"explanation":"XDR. Extended detection and response correlates endpoint, email, network, and cloud telemetry into one linked incident - the cross-layer story EDR alone cannot tell. The tell: XDR = correlation across layers, EDR = depth on the endpoint only, NAC = admission control, FIM = file change alerts, DLP = data leaving."},
  {"id":"q502","domain":"D4","family":"endpoint-detection","question":"Minutes after a web server is defaced, the security team is alerted - not by traffic analysis, but because index.html no longer matches its known-good baseline hash. Which technology raised the alert?","options":["UBA","NAC","FIM","DLP"],"correctIndex":2,"explanation":"FIM. File integrity monitoring compares critical files against known-good baselines and fires the instant one changes - defacement is its showcase catch. The tell: FIM = a watched file changed, UBA = a user acted out of pattern, NAC = a device failed admission, DLP = data tried to leave."},
  {"id":"q503","domain":"D4","family":"identity-lifecycle","question":"Every quarter, managers receive a report of their team members' system access and must confirm each entitlement is still needed, revoking anything no longer justified by the person's role. Which identity process is this?","options":["Provisioning","Attestation","Identity proofing","Federation"],"correctIndex":1,"explanation":"Attestation. Periodic managerial review and confirmation that access remains appropriate is access attestation (recertification). The tell: attestation = recurring confirm-or-revoke review, provisioning = granting access at start, identity proofing = verifying a person is who they claim, federation = trusting another organization's authentication."},
  {"id":"q504","domain":"D4","family":"identity-lifecycle","question":"The moment HR records a termination, an automated workflow disables the employee's account, revokes every access right, and reclaims licenses - all before the person reaches the parking lot. Which process is this?","options":["Provisioning","Identity proofing","De-provisioning","Attestation"],"correctIndex":2,"explanation":"De-provisioning. Removing accounts and access at separation is de-provisioning, and speed matters: lingering access is a classic insider risk. The tell: de-provisioning = access removed at exit, provisioning = access granted at entry, attestation = periodic review in between, identity proofing = verifying identity up front."},
  {"id":"q505","domain":"D4","family":"identity-lifecycle","question":"On a new hire's first morning, an automated workflow has already created her accounts and granted exactly the access her role requires - nothing requested manually. Which identity process is this?","options":["provisioning","de-provisioning","attestation","identity proofing"],"correctIndex":0,"explanation":"Provisioning. Creating accounts and granting role-appropriate access at onboarding is provisioning. The tell: provisioning = access granted at entry, de-provisioning = removed at exit, attestation = periodically re-confirmed, identity proofing = proving the person is who they claim before any of it."},
  {"id":"q506","domain":"D4","family":"identity-lifecycle","question":"After one sign-in to the corporate identity provider, a user opens the HR app, the expense tool, and email without ever being prompted to log in again. Which capability is this?","options":["federation","identity proofing","provisioning","single sign-on"],"correctIndex":3,"explanation":"Single sign-on. One authentication unlocking many applications is SSO. Federation extends the idea across organizational boundaries, but everything here lives under one identity provider. The tell: SSO = one login, many apps, federation = trusting another org's login, provisioning = granting access, identity proofing = verifying the human."},
  {"id":"q507","domain":"D4","family":"identity-lifecycle","question":"Before issuing credentials to a new remote hire nobody has met in person, HR requires a government ID scan matched against a live selfie video to confirm the applicant is a real person who is who they claim. Which identity process is this?","options":["attestation","identity proofing","provisioning","de-provisioning"],"correctIndex":1,"explanation":"Identity proofing. Verifying that a claimed identity belongs to a real, present person BEFORE any account exists is proofing - the step that defeats fake-applicant fraud. The tell: identity proofing = prove the human first, provisioning = then grant the access, attestation = periodically re-confirm it, de-provisioning = remove it at exit."},
  {"id":"q508","domain":"D4","family":"identity-lifecycle","question":"A supplier's engineers open your company's ordering portal using their OWN company's corporate logins - your portal trusts their employer's identity provider to vouch for them, and you never issue them accounts. Which capability is this?","options":["single sign-on","identity proofing","federation","provisioning"],"correctIndex":2,"explanation":"Federation. Trusting another organization's identity provider across a company boundary is federation; SSO within one organization is the same convenience without the cross-boundary trust. The tell: federation = trust another org's logins, single sign-on = one login for many apps under one provider, provisioning = creating accounts yourself, identity proofing = verifying the human."},
  {"id":"q509","domain":"D4","family":"federation-protocols","question":"A user clicks \"Log in with corporate SSO\" on a cloud HR application. The browser bounces to the company identity provider, authenticates, and returns carrying a signed XML assertion that the HR app accepts as proof of identity. Which protocol is in use?","options":["LDAP","OAuth","OpenID Connect","SAML"],"correctIndex":3,"explanation":"SAML. The signed XML assertion passed from identity provider to service provider is SAML's fingerprint, the classic enterprise web-SSO flow. The tell: SAML = XML assertions for SSO, OAuth = delegated access tokens, OpenID Connect = JSON/OAuth-based login, LDAP = directory lookups."},
  {"id":"q510","domain":"D4","family":"federation-protocols","question":"A photo-printing app requests access to a user's cloud storage. The user approves the request at the storage provider, which hands the app a scoped token to fetch photos on the user's behalf - the user's password is never shared with the app. Which protocol enables this delegated access?","options":["OAuth","SAML","LDAP","OpenID Connect"],"correctIndex":0,"explanation":"OAuth. Delegated, scoped access via tokens without sharing credentials is OAuth's exact purpose - authorization, not login. The tell: OAuth = app acts on your behalf with a token, OpenID Connect = proves who you are on top of OAuth, SAML = XML SSO assertions, LDAP = directory queries."},
  {"id":"q511","domain":"D4","family":"federation-protocols","question":"An in-house application needs to look up user accounts, group memberships, and phone attributes from on-premises Active Directory. Which protocol does it use to query the directory?","options":["OAuth","SAML","LDAP","OpenID Connect"],"correctIndex":2,"explanation":"LDAP. Querying a directory service for accounts, groups, and attributes is LDAP's job. The tell: LDAP = directory lookups, SAML/OpenID Connect = web SSO flows, OAuth = delegated authorization tokens."},
  {"id":"q512","domain":"D4","family":"federation-protocols","question":"An identity architect describes a protocol that exchanges XML-based security assertions between an identity provider and a service provider to deliver browser single sign-on across enterprise web applications. Which protocol is it?","options":["OAuth","SAML","LDAP","OpenID Connect"],"correctIndex":1,"explanation":"SAML. XML assertions between IdP and SP for browser SSO is the SAML definition. The tell: SAML = XML assertions, enterprise SSO, OpenID Connect = the JSON-era login layer on OAuth, OAuth = delegated authorization, LDAP = directory queries."},
  {"id":"q513","domain":"D4","family":"federation-protocols","question":"A troubleshooting session shows an application binding to a directory server on port 389 and retrieving a user's account details and group memberships from on-premises Active Directory. Which protocol is it using?","options":["SAML","OAuth","LDAP","OpenID Connect"],"correctIndex":2,"explanation":"LDAP. Port 389 directory binds pulling accounts and groups are LDAP queries (636 for LDAPS). The tell: LDAP = directory lookups on 389/636, SAML/OpenID Connect = web SSO, OAuth = delegated access tokens."},
  {"id":"q514","domain":"D4","family":"federation-protocols","question":"A third-party scheduling app needs to write events into a user's calendar at a different provider. The user consents once; the provider issues the app a token scoped to calendar-write only, and the user's password is never revealed to the app. Which protocol provides this delegated authorization?","options":["OAuth","SAML","OpenID Connect","LDAP"],"correctIndex":0,"explanation":"OAuth. Consent-based, scope-limited tokens letting one app act on a user's behalf at another service is OAuth's core flow. The tell: OAuth = delegated authorization via scoped tokens, OpenID Connect = authentication built on it, SAML = XML SSO, LDAP = directory access."},
  {"id":"q515","domain":"D4","family":"access-control-models","question":"On a military network, every file and every user carries a classification label. The operating system itself - never the file's owner - grants or denies access by comparing clearance to classification, and no user can override the labels. Which model is this?","options":["discretionary access control","role-based access control","rule-based access control","mandatory access control"],"correctIndex":3,"explanation":"Mandatory access control. System-enforced labels that owners cannot override are MAC, the military-grade model. The tell: mandatory = system decides via labels, discretionary = the owner decides, role-based = job group decides, rule-based = a fixed rule set (like ACL conditions) decides."},
  {"id":"q516","domain":"D4","family":"access-control-models","question":"On a shared file server, whoever creates a folder can personally grant or revoke other users' access to it, entirely at their own discretion. Which access control model is this?","options":["discretionary access control","mandatory access control","attribute-based access control","role-based access control"],"correctIndex":0,"explanation":"Discretionary access control. The resource owner controlling who gets in is DAC, flexible and typical of standard file systems. The tell: discretionary = owner's choice, mandatory = system labels the owner cannot change, role-based = permissions follow job groups, attribute-based = multi-condition evaluation."},
  {"id":"q517","domain":"D4","family":"access-control-models","question":"A document opens only when the requester is in the finance department AND on a corporate-managed device AND connecting from an approved country - the system evaluates all three conditions about the user, device, and context together. Which model is this?","options":["role-based access control","rule-based access control","attribute-based access control","mandatory access control"],"correctIndex":2,"explanation":"Attribute-based access control. Decisions combining attributes of the user, device, and environment are ABAC, the most granular model. The tell: attribute-based = many contextual conditions evaluated together, role-based = job group alone, rule-based = fixed system-wide rules, mandatory = classification labels."},
  {"id":"q518","domain":"D4","family":"access-control-models","question":"A hospital grants permissions to the \"nurse\" group and the \"billing\" group; individual users get access purely by being placed into the job group that matches their position. Which model is this?","options":["attribute-based access control","role-based access control","discretionary access control","rule-based access control"],"correctIndex":1,"explanation":"Role-based access control. Permissions attach to job roles and users inherit them by membership, simplifying administration at scale. The tell: role-based = access follows the job group, attribute-based = contextual conditions, discretionary = owner grants, rule-based = fixed rules like time-of-day restrictions."},
  {"id":"q519","domain":"D4","family":"access-control-models","question":"A network policy denies ALL connections outside 8 a.m. to 6 p.m. on weekdays. The rule fires on the clock, identically for every user, no matter who they are or what role they hold. Which access control model enforces this?","options":["role-based access control","rule-based access control","attribute-based access control","mandatory access control"],"correctIndex":1,"explanation":"Rule-based access control. A fixed system-wide rule applied uniformly regardless of identity - time windows, ACL conditions - is rule-based. The tell: rule-based = same rule for everyone, role-based = depends on your job group, attribute-based = evaluates multiple contextual attributes, mandatory = classification labels."},
  {"id":"q520","domain":"D4","family":"access-control-models","question":"An access decision engine evaluates several characteristics of each request together - the user's department, the device's compliance state, the connection's geographic origin - and grants access only when the combination satisfies policy. Which model is this?","options":["rule-based access control","discretionary access control","attribute-based access control","role-based access control"],"correctIndex":2,"explanation":"Attribute-based access control. Combining user, device, and environment attributes per decision is ABAC, the model underlying most zero-trust policy engines. The tell: attribute-based = multi-attribute contextual evaluation, rule-based = one fixed rule for all, role-based = job group only, discretionary = the owner decides."},
  {"id":"q521","domain":"D4","family":"access-control-models","question":"On a Linux server, a file's owner runs chmod and setfacl to decide which users and groups may read or write that file, entirely at the owner's own judgment. Which access control model does this reflect?","options":["discretionary access control","role-based access control","mandatory access control","rule-based access control"],"correctIndex":0,"explanation":"Discretionary access control. Standard Unix permissions put access in the owner's hands, the definition of DAC. The tell: discretionary = owner sets permissions, mandatory = the system's labels override owners (SELinux), role-based = job-group driven, rule-based = uniform fixed rules."},
  {"id":"q522","domain":"D4","family":"mfa","question":"A banking login requires a password followed by a fingerprint scan on the user's device. In factor terms, what does the fingerprint satisfy?","options":["something you know","something you have","somewhere you are","something you are"],"correctIndex":3,"explanation":"Something you are. Biometrics - fingerprints, face, iris - are inherence factors. Combined with the password (something you know), this makes true two-factor authentication. The tell: are = biometric traits, know = passwords/PINs, have = tokens/phones/cards, somewhere you are = location."},
  {"id":"q523","domain":"D4","family":"mfa","question":"After entering a password, the user must type the rotating six-digit code displayed by an authenticator app on their phone. Which authentication factor does the code represent?","options":["something you have","something you are","something you know","somewhere you are"],"correctIndex":0,"explanation":"Something you have. The code proves possession of the enrolled device generating it; the fact you type it does not make it knowledge - it changes every 30 seconds. The tell: have = possession of a token/device, know = a memorized secret, are = biometrics, somewhere you are = location context."},
  {"id":"q524","domain":"D4","family":"mfa","question":"An engineer authenticates with a small physical USB device: tap or insert, and it completes a cryptographic challenge automatically - there is no code to read or type. Which term BEST describes this device?","options":["soft token","hard token","security key","biometric"],"correctIndex":2,"explanation":"Security key. A physical device performing challenge-response authentication (FIDO2/U2F style) with no displayed code is a security key. A hard token traditionally displays a code you type. The tell: security key = cryptographic tap/insert, hard token = physical code display, soft token = app-generated code, biometric = a body trait."},
  {"id":"q525","domain":"D4","family":"mfa","question":"A conditional access policy verifies the user's physical geographic position - GPS coordinates or network region - before permitting the login. Which authentication factor is this?","options":["something you know","something you have","something you are","somewhere you are"],"correctIndex":3,"explanation":"Somewhere you are. Location-based verification is its own factor, typically used to supplement rather than replace the classic three. The tell: somewhere you are = location, know = memorized secret, have = possessed device/token, are = biometric trait."},
  {"id":"q526","domain":"D4","family":"mfa","question":"A legacy system requires a password and then the answer to a personal security question. An auditor rules this is NOT multifactor authentication. Why?","options":["Both inputs are the 'something you know' factor","The two inputs are 'something you have' and 'something you are'","A security question counts as 'something you are'","Passwords are never accepted as an authentication factor"],"correctIndex":0,"explanation":"Both are knowledge. A password and a security-question answer are two memorized secrets - the same factor twice. Multifactor requires different factor TYPES, not two prompts. The tell: two of the same factor = single-factor with extra steps, know + have or know + are = true MFA."},
  {"id":"q527","domain":"D4","family":"password-security","question":"A directory policy blocks users from changing their password again until the current one has been in place at least three days, defeating the trick of cycling through changes to return to an old favorite. Which password setting is this?","options":["expiration","age","complexity","length"],"correctIndex":1,"explanation":"Age. Minimum password age forces a password to live a set time before it can be changed, blocking rapid cycling past history checks. The tell: age = minimum time before change, expiration = maximum time before forced change, complexity = required character mix, length = minimum characters."},
  {"id":"q528","domain":"D4","family":"password-security","question":"A breach postmortem finds that one leaked password unlocked an employee's accounts on five separate systems, because the identical password was used on every one. Which password weakness does this illustrate?","options":["expiration","length","complexity","reuse"],"correctIndex":3,"explanation":"Reuse. One password across many systems turns a single leak into five compromises, the exact failure credential-stuffing attacks feed on. The tell: reuse = same password everywhere, length/complexity = how strong one password is, expiration = how long it lives."},
  {"id":"q529","domain":"D4","family":"password-security","question":"Citing research that the number of characters matters more than symbol requirements, a security team raises the minimum from 8 to 16 characters as the biggest single upgrade against brute forcing. Which password setting did they strengthen?","options":["complexity","expiration","age","length"],"correctIndex":3,"explanation":"Length. Every added character multiplies the brute-force keyspace, making length the dominant strength driver. The tell: length = how many characters, complexity = which character classes, expiration = how long it lives, age = how soon it may be changed."},
  {"id":"q530","domain":"D4","family":"password-security","question":"A company eliminates typed secrets entirely: users authenticate with a fingerprint or a hardware security key, and there is no passphrase to remember, leak, or phish. Which approach is this?","options":["expiration","complexity","passwordless","password manager"],"correctIndex":2,"explanation":"Passwordless. Authentication via biometrics or security keys with no typed secret removes the phishable password altogether. The tell: passwordless = no secret phrase exists, password manager = a vault for the secrets you still have, complexity/expiration = rules governing traditional passwords."},
  {"id":"q531","domain":"D4","family":"pam","question":"An administrator's account normally carries standard user rights. When a privileged task arises, the PAM system elevates the account to admin for exactly 30 minutes, then strips the elevation automatically. Which PAM technique is this?","options":["just-in-time permissions","password vaulting","ephemeral credentials","privileged session management"],"correctIndex":0,"explanation":"Just-in-time permissions. Elevating rights only when needed and auto-revoking them afterward is JIT, eliminating standing privilege. The tell: just-in-time = temporary elevation of an existing account, password vaulting = checking secrets out of a store, ephemeral credentials = short-lived throwaway credentials, session management = monitored privileged sessions."},
  {"id":"q532","domain":"D4","family":"pam","question":"No administrator knows the actual root password to any server. To use it, they check it out from a secured central store, which logs who took it and rotates the password immediately after each use. Which PAM capability is this?","options":["just-in-time permissions","ephemeral credentials","privileged session management","password vaulting"],"correctIndex":3,"explanation":"Password vaulting. Privileged credentials held in a controlled, audited store with checkout and rotation is the vault. The tell: password vaulting = the secrets live in the vault, not in heads, just-in-time = temporary elevation, ephemeral credentials = born-to-expire credentials, session management = recording the privileged session itself."},
  {"id":"q533","domain":"D4","family":"pam","question":"A cloud PAM design issues access credentials that exist only for the moments they are needed and expire automatically after a single use, leaving no standing secret for an attacker to steal later. Which approach is this?","options":["password vaulting","just-in-time permissions","ephemeral credentials","privileged session management"],"correctIndex":2,"explanation":"Ephemeral credentials. Short-lived, single-use, self-expiring credentials mean there is nothing durable to steal. The tell: ephemeral credentials = the credential itself is temporary, just-in-time = the permission on an account is temporary, vaulting = long-lived secrets locked up, session management = oversight of the session."},
  {"id":"q534","domain":"D4","family":"pam","question":"A PAM platform keeps every administrative password in a protected repository. Admins check credentials out for a task, every checkout is logged, and the password rotates immediately after return - nobody memorizes anything. Which capability is this?","options":["ephemeral credentials","password vaulting","just-in-time permissions","privileged access management"],"correctIndex":1,"explanation":"Password vaulting. The audited store with checkout and post-use rotation is the vault, removing privileged secrets from human memory. The tell: vaulting = secrets locked in the repository, ephemeral credentials = secrets that expire after one use, just-in-time = temporary elevation of rights, PAM = the umbrella program."},
  {"id":"q535","domain":"D4","family":"pam","question":"A security engineer is explaining just-in-time permissions to an auditor. Which description is correct?","options":["Granting elevated rights only for the brief moment a task needs them, then automatically revoking them","Storing and rotating shared privileged passwords checked out from a vault","Issuing credentials that self-expire seconds after a single use","Managing all privileged accounts as a broad governance program"],"correctIndex":0,"explanation":"JIT = elevation on demand, revocation on schedule. Rights exist only during the task, eliminating standing privilege. The tell: just-in-time = temporary rights on an account, vaulting = stored rotating secrets, ephemeral credentials = the credential itself is disposable, PAM = the whole program."},
  {"id":"q536","domain":"D4","family":"pam","question":"A deployment pipeline requests a credential that lives just minutes - long enough for one deployment - then self-invalidates, so even an intercepted copy is worthless afterward. Which PAM technique produced it?","options":["password vaulting","ephemeral credentials","just-in-time permissions","privileged access management"],"correctIndex":1,"explanation":"Ephemeral credentials. Machine-issued, minutes-long, single-use credentials are ephemeral by design - nothing standing to steal. The tell: ephemeral credentials = the secret itself is short-lived, just-in-time = an account's rights are short-lived, vaulting = durable secrets under lock, PAM = the umbrella."},
  {"id":"q537","domain":"D4","family":"automation","question":"An automated provisioning pipeline is hard-constrained: no matter what a request says, it can never expose a storage bucket to the public internet or exceed the monthly spending cap. What are these built-in constraints called?","options":["ticket creation","guard rails","escalation","single point of failure"],"correctIndex":1,"explanation":"Guard rails. Hard limits that keep automation inside policy no matter the input are guard rails, protecting against both mistakes and abuse at machine speed. The tell: guard rails = boundaries on what automation may do, ticket creation = an automation use case, escalation = routing to humans, single point of failure = the concentration risk."},
  {"id":"q538","domain":"D4","family":"automation","question":"A team automates all onboarding through one orchestration script on one server. The day that server fails, no account can be created anywhere in the company until it is restored. Which risk of automation does this illustrate?","options":["guard rails","single point of failure","escalation","ticket creation"],"correctIndex":1,"explanation":"Single point of failure. Concentrating a critical process in one automation means its failure halts everything that depended on it. The tell: single point of failure = one broken piece stops the whole process, guard rails = safety limits, escalation = handing off to humans, ticket creation = a task automation handles."},
  {"id":"q539","domain":"D4","family":"automation","question":"When monitoring detects a failed backup job at 2 a.m., a workflow automatically opens a tracked work item in the service desk, pre-filled and assigned, so the failure is owned and followed to closure by morning. Which automation capability is this?","options":["escalation","guard rails","continuous integration","ticket creation"],"correctIndex":3,"explanation":"Ticket creation. Automatically opening tracked work items from events guarantees problems enter the queue with no human noticing required. The tell: ticket creation = the item gets opened automatically, escalation = it gets pushed up a tier when stuck, guard rails = limits on automation's actions, continuous integration = the dev-pipeline practice."},
  {"id":"q540","domain":"D4","family":"automation","question":"A service desk workflow watches every open item; anything unacknowledged past its SLA is automatically routed up to the next support tier with an alert to that tier's lead. Which automation capability is this?","options":["ticket creation","guard rails","escalation","continuous integration"],"correctIndex":2,"explanation":"Escalation. Automatically pushing stalled or overdue items to a higher tier is escalation, enforcing that nothing quietly rots in the queue. The tell: escalation = up the chain when stuck, ticket creation = into the queue at the start, guard rails = boundaries on automated actions, CI = code integration practice."},
  {"id":"q541","domain":"D4","family":"ir-process","question":"Confirming ransomware is spreading between file shares, the response team immediately disables the infected VLAN's uplinks and blocks the malware's ports at every switch - stopping movement while the malware itself remains on the infected hosts. Which incident response phase is this?","options":["eradication","containment","recovery","preparation"],"correctIndex":1,"explanation":"Containment. Stopping the spread while the threat still exists inside is containment; removal comes next as eradication. The tell: containment = limit the damage radius, eradication = remove the threat, recovery = restore service, preparation = the readiness beforehand."},
  {"id":"q542","domain":"D4","family":"ir-process","question":"A certification prep drill asks for the correct ORDER of the incident response lifecycle. Which sequence is right?","options":["detection, preparation, containment, analysis, recovery, eradication, lessons learned","preparation, detection, analysis, containment, eradication, recovery, lessons learned","containment, detection, analysis, preparation, eradication, lessons learned, recovery","preparation, analysis, detection, eradication, containment, recovery, lessons learned"],"correctIndex":1,"explanation":"Preparation, detection, analysis, containment, eradication, recovery, lessons learned. Ready first, notice it, understand it, stop its spread, remove it, restore service, then learn. The tell: preparation can only come first and lessons learned only last; containment must precede eradication - you stop the bleeding before you operate."},
  {"id":"q543","domain":"D4","family":"ir-process","question":"An incident response team has just cut the infected hosts off from the network, stopping the malware's spread. According to the standard incident response lifecycle, which phase comes NEXT?","options":["eradication","recovery","detection","lessons learned"],"correctIndex":0,"explanation":"Eradication. Containment is done; next the threat itself is removed - malware deleted, persistence cleared, the entry vulnerability closed. The lifecycle: preparation, detection, analysis, containment, eradication, recovery, lessons learned. The tell: containment = stop the spread, eradication = remove the cause, recovery = restore operations."},
  {"id":"q544","domain":"D4","family":"ir-process","question":"After an alert fires, responders confirm the event is a genuine incident, then scope it: how many systems, which accounts, what data. No action to stop it has been taken yet. Which incident response phase is this?","options":["detection","analysis","containment","preparation"],"correctIndex":1,"explanation":"Analysis. Confirming the incident is real and determining its scope is analysis; detection was the alert itself, and containment has not begun. The tell: detection = noticing something, analysis = confirming and scoping it, containment = stopping the spread, preparation = everything done before any incident."},
  {"id":"q545","domain":"D4","family":"ir-process","question":"The malware is removed, persistence mechanisms are cleared, and the vulnerability that let it in is patched - systems are clean but not yet back in service. Per the incident response lifecycle, which phase follows?","options":["containment","lessons learned","recovery","eradication"],"correctIndex":2,"explanation":"Recovery. With eradication complete, recovery restores systems to production - rebuilding, restoring data, monitoring for recurrence. The tell: eradication = threat removed, recovery = business restored, lessons learned = the retrospective after normality returns."},
  {"id":"q546","domain":"D4","family":"ir-process","question":"Two weeks after operations returned to normal, the whole team meets to document what worked, what failed, and which playbooks and tools need improvement before the next incident. Which phase is this?","options":["preparation","recovery","analysis","lessons learned"],"correctIndex":3,"explanation":"Lessons learned. The post-incident retrospective converts the incident into better preparation, closing the lifecycle loop. The tell: lessons learned = the look-back that improves the process, preparation = where its outputs get applied, recovery = restoring service, analysis = scoping during the incident."},
  {"id":"q547","domain":"D4","family":"ir-process","question":"Long before any alert fires, a security team writes response playbooks, stocks a forensic jump kit, defines call trees, and trains staff in their roles. Which incident response phase is this work?","options":["detection","preparation","analysis","recovery"],"correctIndex":1,"explanation":"Preparation. Everything done in advance - playbooks, tools, training - is the preparation phase, and it determines how well every later phase goes. The tell: preparation = before any incident, detection = the moment one is noticed, analysis = scoping it, recovery = restoring afterward."},
  {"id":"q548","domain":"D4","family":"ir-process","question":"At 3:40 a.m., a monitoring alert flags unusual outbound traffic from a database server - the first moment anyone realizes something might be wrong. Which incident response phase does this alert represent?","options":["preparation","analysis","detection","containment"],"correctIndex":2,"explanation":"Detection. The initial recognition that something may be wrong is detection; confirming and scoping it comes next as analysis. The tell: detection = noticing, analysis = confirming and sizing, containment = stopping the spread, preparation = the readiness built beforehand."},
  {"id":"q549","domain":"D4","family":"ir-process","question":"Every affected system has been fully restored, validated, and returned to normal production; the incident is operationally over. According to the incident response lifecycle, which phase comes NEXT?","options":["lessons learned","containment","eradication","detection"],"correctIndex":0,"explanation":"Lessons learned. After recovery completes, the retrospective closes the loop: what failed, what worked, what changes before next time. The tell: recovery = back to normal, lessons learned = the mandatory look-back that follows, containment/eradication = already behind you by then."},
  {"id":"q550","domain":"D4","family":"ir-testing","question":"No alerts have fired, but analysts spend the week proactively combing the environment - odd persistence mechanisms, unusual lateral connections - for an attacker who may have slipped past every detection tool. What is this activity?","options":["threat hunting","root cause analysis","tabletop","simulation"],"correctIndex":0,"explanation":"Threat hunting. Proactively searching for intrusions that generated no alerts assumes the tools missed something. The tell: threat hunting = look for what detection missed, root cause analysis = explain an incident you already found, tabletop/simulation = exercises testing the response plan."},
  {"id":"q551","domain":"D4","family":"ir-testing","question":"After restoring service from a breach-driven outage, the team works backward through logs and evidence to identify the single underlying failure - an unpatched gateway - that made the whole incident possible. Which activity is this?","options":["threat hunting","simulation","root cause analysis","tabletop"],"correctIndex":2,"explanation":"Root cause analysis. Tracing an incident back to the fundamental failure that enabled it is RCA, feeding fixes that prevent recurrence. The tell: root cause analysis = why did this happen at bottom, threat hunting = is something here we have not seen, tabletop/simulation = practicing the response."},
  {"id":"q552","domain":"D4","family":"ir-testing","question":"An incident response exercise consists entirely of discussion: participants around a table talk through their actions in a scripted scenario, and no live system is touched at any point. Which exercise is this?","options":["simulation","threat hunting","root cause analysis","tabletop"],"correctIndex":3,"explanation":"Tabletop. Discussion-only plan walkthroughs are tabletops: lowest cost, zero operational risk, great for exposing gaps in the plan. The tell: tabletop = talk through it, simulation = act it out against real or staged systems, threat hunting = searching for real intruders, RCA = explaining a real incident."},
  {"id":"q553","domain":"D4","family":"ir-testing","question":"To test true readiness, the team runs a controlled mock intrusion: injects realistic artifacts into a staging environment and has responders actually execute their playbook steps, not merely describe them. Which exercise is this?","options":["tabletop","root cause analysis","simulation","threat hunting"],"correctIndex":2,"explanation":"Simulation. Executing real response steps against a controlled scenario is a simulation, the hands-on step past the tabletop. The tell: simulation = do the steps, tabletop = say the steps, threat hunting = hunt real adversaries, root cause analysis = post-incident why."},
  {"id":"q554","domain":"D4","family":"forensics","question":"Defense counsel discovers a four-hour window where nobody documented who possessed the seized drive between the field collection and the lab. The judge is asked to exclude the evidence entirely. Which failure created this risk?","options":["a broken chain of custody","a missing legal hold","incomplete e-discovery","an unsigned report"],"correctIndex":0,"explanation":"A broken chain of custody. Any undocumented gap in possession invites the claim that evidence was altered, and courts may toss it - the chain's value is its unbroken continuity. The tell: chain of custody = every handoff logged, no gaps, legal hold = the preservation order, e-discovery = production for litigation, reporting = the findings document."},
  {"id":"q555","domain":"D4","family":"forensics","question":"Immediately after imaging a drive, the examiner computes a SHA-256 of both original and copy, stores the image on write-protected media, and re-verifies the hash before every later examination to prove nothing changed since collection. Which forensic activity is this discipline?","options":["acquisition","e-discovery","legal hold","preservation"],"correctIndex":3,"explanation":"Preservation. Everything after collection - hashing, write protection, re-verification - exists to keep the evidence provably unaltered, which is preservation. The tell: preservation = protecting evidence post-collection, acquisition = the imaging itself, legal hold = the order not to delete, e-discovery = producing records for litigation."},
  {"id":"q556","domain":"D4","family":"forensics","question":"Every time a seized laptop drive changes hands - collector to examiner to evidence locker - each person signs a log recording who took custody, when, and why, keeping the trail unbroken for court. What is this record?","options":["legal hold","chain of custody","acquisition","e-discovery"],"correctIndex":1,"explanation":"Chain of custody. The unbroken, signed record of who held the evidence and when is what keeps it admissible; a gap invites the tampering argument. The tell: chain of custody = the handling trail, legal hold = the do-not-delete order, acquisition = collecting the evidence, e-discovery = producing it for litigation."},
  {"id":"q557","domain":"D4","family":"forensics","question":"Anticipating litigation, the legal team directs that all emails and files of certain employees must not be deleted or altered - even where normal retention schedules would purge them. What is this directive?","options":["legal hold","preservation","chain of custody","acquisition"],"correctIndex":0,"explanation":"Legal hold. The formal directive suspending deletion because litigation is anticipated is the legal hold, which overrides retention schedules. The tell: legal hold = the binding do-not-delete order, preservation = the general practice of protecting evidence, chain of custody = the handling record, acquisition = the collection step."},
  {"id":"q558","domain":"D4","family":"forensics","question":"An examiner attaches a write blocker and creates a bit-for-bit forensic image of the suspect drive, hashing both to prove the copy is exact. Which forensic step is this?","options":["e-discovery","reporting","legal hold","acquisition"],"correctIndex":3,"explanation":"Acquisition. Actually collecting the evidence - the verified bit-for-bit image - is acquisition. The tell: acquisition = gathering the evidence itself, legal hold = the order to preserve it, e-discovery = producing it in litigation, reporting = documenting the findings."},
  {"id":"q559","domain":"D4","family":"forensics","question":"During active litigation, the organization must locate, collect, and hand over relevant electronic records - emails, chat logs, documents - to the opposing party's legal team. Which forensic process is this?","options":["legal hold","chain of custody","preservation","e-discovery"],"correctIndex":3,"explanation":"E-discovery. Identifying, collecting, and producing electronic records for litigation is electronic discovery. The tell: e-discovery = produce it for the lawsuit, legal hold = the earlier do-not-delete order, preservation = keeping evidence intact, chain of custody = the handling trail."},
  {"id":"q560","domain":"D4","family":"forensics","question":"After evidence is collected, which forensic activity ensures it stays protected from any alteration, tampering, or degradation - hashed, write-protected, and properly stored - until it is needed?","options":["acquisition","reporting","preservation","e-discovery"],"correctIndex":2,"explanation":"Preservation. Protecting collected evidence from change is preservation, proven later by matching hashes. The tell: preservation = keep it pristine after collection, acquisition = the collecting itself, chain of custody = who held it, reporting = documenting conclusions."},
  {"id":"q561","domain":"D4","family":"forensics","question":"With the investigation complete, the forensic analyst compiles a formal document detailing the methods used, the evidence examined, and the conclusions reached, written to survive courtroom scrutiny. Which forensic step is this?","options":["reporting","acquisition","chain of custody","legal hold"],"correctIndex":0,"explanation":"Reporting. The formal write-up of methods, evidence, and conclusions is the reporting step that carries the investigation into court. The tell: reporting = the final document, acquisition = collecting, chain of custody = the custody log, legal hold = the preservation order."},
  {"id":"q562","domain":"D4","family":"log-sources","question":"Investigating failed purchases, an analyst reads a log of stack traces, payment-gateway timeouts, and per-transaction error codes written by the e-commerce software itself. Which log source is this?","options":["OS security log","firewall log","application log","packet capture"],"correctIndex":2,"explanation":"Application log. Events written by the application about its own operations - errors, transactions, timeouts - are application logs, invisible to OS and network logging. The tell: application log = the app narrating itself, OS security log = host logons and audit events, firewall log = boundary permit/deny, packet capture = raw traffic."},
  {"id":"q563","domain":"D4","family":"log-sources","question":"To reconstruct exactly what a compromised laptop did locally - which processes launched, what files were touched, which USB devices mounted - the analyst pulls the record generated by the device's own monitoring agent. Which log source is this?","options":["endpoint log","network log","metadata","firewall log"],"correctIndex":0,"explanation":"Endpoint log. Host-local activity - processes, files, devices - lives in endpoint logs from the OS and EDR agent; no network source saw any of it. The tell: endpoint log = what happened ON the machine, network/firewall logs = what crossed the wire, metadata = descriptive data about communications."},
  {"id":"q564","domain":"D4","family":"log-sources","question":"To reconstruct exactly what data left the network during a breach, an analyst needs every raw byte of the traffic itself, not summaries of it. Which source provides this?","options":["metadata","packet capture","firewall log","network log"],"correctIndex":1,"explanation":"Packet capture. Full packet capture preserves complete traffic contents, byte for byte - the only source that shows exactly what was transferred. The tell: packet capture = the whole conversation, metadata = data about the data, firewall/network logs = events and flows, not payloads."},
  {"id":"q565","domain":"D4","family":"log-sources","question":"An investigator examines an email's headers, timestamps, sender and recipient fields, and routing path - everything about the message except the message body itself. Which source is being used?","options":["packet capture","endpoint log","metadata","firewall log"],"correctIndex":2,"explanation":"Metadata. Data describing the communication - headers, timestamps, participants - rather than its content is metadata, often enough to map an incident without reading a single body. The tell: metadata = about the message, packet capture = the message itself, endpoint/firewall logs = device and traffic events."},
  {"id":"q566","domain":"D4","family":"log-sources","question":"An analyst reconstructing an intrusion needs to see which connections were permitted or denied, by source address, destination, and port, at the network boundary. Which log source records this?","options":["endpoint log","firewall log","application log","metadata"],"correctIndex":1,"explanation":"Firewall log. Permit/deny decisions with addresses and ports are exactly what the firewall records at the boundary. The tell: firewall log = allow/deny by address and port, endpoint log = host activity, application log = app-level events, metadata = descriptive data about communications."},
  {"id":"q567","domain":"D4","family":"log-sources","question":"To trace an account compromise, an analyst pulls the record of successful and failed sign-ins, privilege use, and account changes from one server's operating system. Which log source is this?","options":["network log","firewall log","OS security log","packet capture"],"correctIndex":2,"explanation":"OS security log. Authentication and audit events on a specific host live in the operating system's security log (Windows Security log, Linux auth logs). The tell: OS security log = logons and account changes on the host, firewall log = boundary decisions, network log = traffic events, packet capture = raw contents."},
  {"id":"q568","domain":"D5","family":"governance-hierarchy","question":"A security document reads: \"Step 1 - open the admin console. Step 2 - navigate to Users. Step 3 - disable the account and record the ticket number.\" Which governance document type is this?","options":["Policy","Standard","Procedure","Guideline"],"correctIndex":2,"explanation":"Procedure. Numbered, exact, do-this-then-that steps are a procedure - the how. The tell: policy = the high-level what and why, standard = the mandatory specific requirement, procedure = the step-by-step how, guideline = the recommended-but-optional advice."},
  {"id":"q569","domain":"D5","family":"governance-hierarchy","question":"A governance framework includes one document type that offers recommended best practices staff are encouraged to follow - but compliance is not mandatory. Which document type is this?","options":["Guideline","Policy","Standard","Procedure"],"correctIndex":0,"explanation":"Guideline. Recommended and optional is the guideline's defining trait; everything else in the hierarchy binds. The tell: guideline = should, not must, policy = the mandatory intent, standard = the mandatory specifics, procedure = the mandatory steps."},
  {"id":"q570","domain":"D5","family":"governance-hierarchy","question":"Executives publish a one-page statement declaring that all company data must be protected and that security is every employee's responsibility. It names no technologies and gives no technical specifics. Which document type is this?","options":["Standard","Policy","Guideline","Procedure"],"correctIndex":1,"explanation":"Policy. High-level management intent stating what must happen and why, without technical detail, is a policy. The tell: policy = broad mandatory intent from leadership, standard = the specific required settings beneath it, procedure = the steps, guideline = optional advice."},
  {"id":"q571","domain":"D5","family":"governance-hierarchy","question":"A mandatory rule requires stored passwords to use a defined bcrypt work factor and all disk encryption to use AES-256. This specific, binding document supporting the broader security policy is a:","options":["Guideline","Procedure","Policy","Standard"],"correctIndex":3,"explanation":"Standard. Specific mandatory technical requirements that implement a policy's intent are standards. The tell: standard = exact required specifics (AES-256, work factors), policy = the general mandate above it, procedure = how to carry it out, guideline = optional recommendation."},
  {"id":"q572","domain":"D5","family":"governance-hierarchy","question":"A required specification mandates WPA3 on every wireless access point and a named approved cipher suite for all VPN connections. This binding technical specification supporting the broader security policy is a:","options":["policy","procedure","guideline","standard"],"correctIndex":3,"explanation":"Standard. Exact mandatory technical requirements implementing policy intent are standards. The tell: standard = the required specifics, policy = the high-level mandate, procedure = the step-by-step how, guideline = optional recommendation."},
  {"id":"q573","domain":"D5","family":"governance-hierarchy","question":"A new analyst is handed a numbered document walking through exactly how to enroll a user's hardware token, step by step, so the task comes out identical every time regardless of who performs it. Which document type is this?","options":["procedure","standard","guideline","policy"],"correctIndex":0,"explanation":"Procedure. Sequenced steps producing a repeatable outcome are a procedure. The tell: procedure = ordered how-to steps, standard = what settings are required, policy = why and what at a high level, guideline = advisory best practice."},
  {"id":"q574","domain":"D5","family":"governance-hierarchy","question":"In the governance hierarchy, which document is the high-level, mandatory statement of management intent - what the organization will do and why - deliberately free of specific settings or steps?","options":["guideline","procedure","policy","standard"],"correctIndex":2,"explanation":"Policy. Leadership's binding statement of intent sits at the top; standards and procedures translate it into specifics and steps. The tell: policy = mandatory intent, standard = mandatory specifics, procedure = mandatory steps, guideline = optional advice."},
  {"id":"q575","domain":"D5","family":"policies","question":"A hurricane floods corporate headquarters. One plan keeps order fulfillment, payroll, and customer support running from alternate locations for the weeks the building is unusable. Which plan is this?","options":["Disaster recovery policy","Business continuity policy","Incident response policy","Acceptable use policy"],"correctIndex":1,"explanation":"Business continuity. Keeping the BUSINESS functions operating through disruption is continuity; rebuilding the IT systems is disaster recovery's slice of it. The tell: business continuity = keep operations running, disaster recovery = restore the technology, incident response = handle the security event, acceptable use = rules for users."},
  {"id":"q576","domain":"D5","family":"policies","question":"After a fire destroys the server room, the team executes a documented plan: rebuild servers, restore databases from backup, bring IT systems back online in priority order. Which plan are they following?","options":["Business continuity policy","Change management policy","Disaster recovery policy","Incident response policy"],"correctIndex":2,"explanation":"Disaster recovery. Restoring the technology stack after a catastrophe is DR, the IT-focused subset of continuity planning. The tell: disaster recovery = rebuild and restore systems, business continuity = keep the business functioning meanwhile, incident response = security-event handling, change management = controlled routine changes."},
  {"id":"q577","domain":"D5","family":"policies","question":"An employee is disciplined for running a personal side business from a company laptop. The policy cited defines what staff may and may not do with corporate laptops, email, and internet access. Which policy is it?","options":["Acceptable use policy","Incident response policy","Business continuity policy","SDLC policy"],"correctIndex":0,"explanation":"Acceptable use policy. The AUP is the rulebook for how employees may use company systems, usually signed at onboarding. The tell: AUP = user behavior on company resources, incident response = breach handling phases, business continuity = operating through disruption, SDLC = secure development practices."},
  {"id":"q578","domain":"D5","family":"policies","question":"A policy document defines the exact phases the security team follows once a breach is confirmed: preparation, detection, analysis, containment, eradication, recovery. Which policy is this?","options":["Business continuity policy","Disaster recovery policy","Acceptable use policy","Incident response policy"],"correctIndex":3,"explanation":"Incident response policy. The phased lifecycle for handling security events is the IR policy's content. The tell: incident response = the breach-handling phases, disaster recovery = restoring systems after catastrophe, business continuity = keeping operations alive, acceptable use = user conduct rules."},
  {"id":"q579","domain":"D5","family":"policies","question":"An ice storm closes the main office for a week. Management activates the plan that shifts staff to remote work, reroutes the phone system, and keeps invoicing and shipping moving so customers barely notice. Which policy is this?","options":["disaster recovery","business continuity","incident response","acceptable use policy"],"correctIndex":1,"explanation":"Business continuity. The focus is keeping business FUNCTIONS running through the disruption, not rebuilding technology. The tell: business continuity = operations keep flowing, disaster recovery = the IT rebuild, incident response = security event handling, acceptable use = user conduct."},
  {"id":"q580","domain":"D5","family":"policies","question":"Lightning destroys the storage array. Technicians follow a documented plan concerned solely with rebuilding the affected servers, restoring the network, and recovering data from backups to bring the technology back online. Which policy is this?","options":["business continuity","incident response","change management","disaster recovery"],"correctIndex":3,"explanation":"Disaster recovery. A plan scoped to restoring the technology stack after a catastrophe is DR. The tell: disaster recovery = rebuild the systems, business continuity = keep the business operating meanwhile, incident response = handle security breaches, change management = routine controlled change."},
  {"id":"q581","domain":"D5","family":"policies","question":"Company policy requires every proposed modification to production systems to pass through approval, impact analysis, testing, and a documented backout plan before it may be applied. Which policy governs this?","options":["change management","SDLC","incident response","information security"],"correctIndex":0,"explanation":"Change management. Approval, impact analysis, testing, and backout are the change management gate for production modifications. The tell: change management = controlled changes to live systems, SDLC = how software is built, incident response = breach handling, information security = the umbrella policy."},
  {"id":"q582","domain":"D5","family":"standards-procedures","question":"The SOC maintains a document titled \"Phishing Report Response\" that scripts exactly what to do, in order, whenever a phishing report arrives - who verifies, who blocks the sender, who notifies. This scenario-specific response script is a:","options":["Playbook","Onboarding procedure","Change management procedure","Password standard"],"correctIndex":0,"explanation":"Playbook. A step-by-step response script for one specific scenario type is a playbook, the SOC's per-scenario procedure. The tell: playbook = scenario-specific response steps, onboarding/offboarding = personnel procedures, change management procedure = how changes get approved, password standard = required password specifics."},
  {"id":"q583","domain":"D5","family":"standards-procedures","question":"An employee resigns. HR's notification triggers the procedure that revokes all system access, disables accounts, and collects equipment on the person's last day. This procedure is:","options":["Onboarding","Offboarding","Change management procedure","Access control standard"],"correctIndex":1,"explanation":"Offboarding. The structured exit process - access revoked, accounts disabled, assets returned - is offboarding, and gaps in it create lingering-access risk. The tell: offboarding = the exit process, onboarding = the entry process, change management = system changes, access control standard = the required access rules."},
  {"id":"q584","domain":"D5","family":"standards-procedures","question":"On a new hire's first day, IT runs the defined process: create accounts, add role group memberships, issue equipment, and grant day-one access. This procedure is:","options":["offboarding","onboarding","playbook","change management procedure"],"correctIndex":1,"explanation":"Onboarding. The structured entry process granting a new person accounts and access is onboarding, offboarding's mirror. The tell: onboarding = access granted at entry, offboarding = access removed at exit, playbook = scenario response script, change management procedure = system change steps."},
  {"id":"q585","domain":"D5","family":"standards-procedures","question":"A binding document specifies the exact minimum password length, required character classes, and reuse limits every account in the company must meet. This required specification is a:","options":["encryption standard","playbook","password standard","offboarding procedure"],"correctIndex":2,"explanation":"Password standard. Mandatory password specifics - length, complexity, reuse - form the password standard. The tell: password standard = required password rules, encryption standard = required crypto algorithms, playbook = incident response script, offboarding procedure = exit steps."},
  {"id":"q586","domain":"D5","family":"external-governance","question":"A retailer must comply with PCI DSS because it accepts card payments. The requirement is imposed and enforced by the payment card brands through contracts - no government wrote it. Which external governance source is this?","options":["Regulatory","Industry","Legal","National"],"correctIndex":1,"explanation":"Industry. PCI DSS is the textbook industry requirement: binding through business relationships, not law. The tell: industry = imposed by the sector itself (PCI DSS), regulatory = imposed by a government agency with penalties, legal = statutes and liability, national/local = the jurisdiction level of the rule."},
  {"id":"q587","domain":"D5","family":"external-governance","question":"A government agency issues enforceable cybersecurity rules for the sector it oversees and can levy fines on organizations that fail to comply. Which category of external governance is this?","options":["Industry","Legal","Regulatory","Local"],"correctIndex":2,"explanation":"Regulatory. Rules issued and enforced by a government agency with penalty power are regulatory requirements (HIPAA, GDPR enforcement). The tell: regulatory = agency-enforced rules and fines, industry = sector-imposed standards like PCI DSS, legal = the broader body of law and liability, local = the jurisdiction tier."},
  {"id":"q588","domain":"D5","family":"external-governance","question":"Counsel reminds the board that the company must honor terms written into signed contracts and comply with statutes, since breaching either invites lawsuits and liability. Which category of external governance is this?","options":["regulatory","industry","global","legal"],"correctIndex":3,"explanation":"Legal. Obligations grounded in laws and contracts, enforced through courts and liability, are the legal category. The tell: legal = statutes, contracts, lawsuits, regulatory = agency rules and fines, industry = sector-imposed standards like PCI DSS, global = the worldwide jurisdiction scope."},
  {"id":"q589","domain":"D5","family":"external-governance","question":"A multinational must satisfy the EU's GDPR for European residents' data while simultaneously meeting the differing rules of every other country it operates in, reconciling them all in one program. Governance at this worldwide scope is:","options":["global","national","local/regional","industry"],"correctIndex":0,"explanation":"Global. Cross-country, worldwide obligations define the global governance scope, the hardest tier to reconcile. The tell: global = across countries, national = one country's laws, local/regional = state or municipal rules, industry = sector-imposed requirements."},
  {"id":"q590","domain":"D5","family":"data-roles","question":"A marketing company decides which customer data to collect and exactly what it will be used for, then hires an outside email vendor to execute the campaigns with that data. Under GDPR, the marketing company is the:","options":["Data processor","Data controller","Data custodian","Data owner"],"correctIndex":1,"explanation":"Data controller. Deciding the purposes and means of processing personal data makes it the controller, regardless of who does the hands-on work. The tell: controller = decides why and how, processor = processes on the controller's instructions, custodian = the day-to-day technical caretaker, owner = the internal accountability role for a dataset."},
  {"id":"q591","domain":"D5","family":"data-roles","question":"The email vendor sends campaigns using only the customer data and instructions its client supplies, making zero decisions about why or how the personal data is used. Under GDPR, the vendor is the:","options":["Data processor","Data controller","Data owner","Data custodian"],"correctIndex":0,"explanation":"Data processor. Handling personal data strictly on another party's instructions is processing; the client remains the controller. The tell: processor = acts only on instructions, controller = sets purpose and means, owner = internal accountable executive, custodian = the technical caretaker role."},
  {"id":"q592","domain":"D5","family":"data-roles","question":"One role delivers the hands-on technical protection of data every day - running backups, applying access controls, patching the storage systems - while never deciding the data's classification or purpose. Which role is this?","options":["Data owner","Data controller","Data custodian/steward","Data processor"],"correctIndex":2,"explanation":"Data custodian/steward. The custodian implements protection technically; owners and controllers make the classification and purpose decisions the custodian enforces. The tell: custodian = hands-on caretaker, owner = accountable decision-maker for the dataset, controller = decides purpose under privacy law, processor = external party processing on instructions."},
  {"id":"q593","domain":"D5","family":"data-roles","question":"A senior vice president is formally accountable for the customer dataset: she sets its classification and approves who may access it, while technical staff execute the controls she mandates. Her role is the:","options":["data controller","data owner","data processor","data custodian"],"correctIndex":1,"explanation":"Data owner. Internal accountability for a dataset - setting classification and access rules - is the owner role; the custodians do the hands-on enforcement. The tell: owner = accountable decision-maker inside the org, custodian = technical caretaker, controller/processor = the GDPR pairing about purpose and instructions."},
  {"id":"q594","domain":"D5","family":"data-roles","question":"A payroll bureau calculates and issues paychecks strictly per the data and instructions its client provides, making no independent decisions about why the personal data is used. Under GDPR, the bureau is the:","options":["data controller","data custodian","data processor","data owner"],"correctIndex":2,"explanation":"Data processor. Processing personal data solely on a controller's instructions defines the processor. The tell: processor = executes instructions, controller = decides purpose and means, custodian = internal technical caretaker, owner = internal accountable executive."},
  {"id":"q595","domain":"D5","family":"data-roles","question":"A hospital determines which patient information it collects, why it is processed, and by what means - then engages a cloud analytics vendor to run the computations on its behalf. Under GDPR, the hospital is the:","options":["data processor","data custodian","data owner","data controller"],"correctIndex":3,"explanation":"Data controller. Deciding the purposes and means of processing makes the hospital the controller; the vendor computing on instructions is the processor. The tell: controller = why and how, processor = does the work as told, owner/custodian = internal accountability and caretaking roles."},
  {"id":"q596","domain":"D5","family":"risk-assessment-types","question":"Automated tooling watches the environment around the clock, recalculating risk scores in real time as configurations drift and new vulnerabilities appear. Which risk assessment cadence is this?","options":["Ad hoc","Recurring","Continuous","One-time"],"correctIndex":2,"explanation":"Continuous. Real-time, always-on automated assessment is continuous, catching risk changes the moment they happen. The tell: continuous = constant automated monitoring, recurring = on a fixed schedule (annual, quarterly), ad hoc = triggered by an event, one-time = a single point-in-time exercise."},
  {"id":"q597","domain":"D5","family":"risk-assessment-types","question":"The morning after a direct competitor discloses a major breach, the CISO orders an immediate, unplanned risk assessment prompted specifically by that news. Which assessment type is this?","options":["Ad hoc","Recurring","Continuous","One-time"],"correctIndex":0,"explanation":"Ad hoc. An unscheduled assessment triggered by a specific event or concern is ad hoc. The tell: ad hoc = event-driven, unplanned, recurring = calendar-driven, continuous = automated and constant, one-time = single occasion, such as before an acquisition."},
  {"id":"q598","domain":"D5","family":"risk-assessment-types","question":"Policy requires a full enterprise risk assessment every October, same scope, same date, regardless of whether anything notable happened that year. Which assessment cadence is this?","options":["recurring","ad hoc","one-time","continuous"],"correctIndex":0,"explanation":"Recurring. Fixed-schedule, calendar-driven assessments are recurring. The tell: recurring = on the calendar, ad hoc = triggered by events, continuous = automated and always-on, one-time = a single non-repeating exercise."},
  {"id":"q599","domain":"D5","family":"risk-assessment-types","question":"Before launching an entirely new product line, the firm commissions a single risk assessment scoped to that launch alone, with no intention of repeating it. Which assessment type is this?","options":["recurring","continuous","ad hoc","one-time"],"correctIndex":3,"explanation":"One-time. A single assessment for a specific occasion - a launch, merger, or migration - with no repeat cycle is one-time. The tell: one-time = single planned occasion, ad hoc = unplanned reaction to an event, recurring = scheduled repetition, continuous = constant automated monitoring."},
  {"id":"q600","domain":"D5","family":"qual-quant","question":"An analyst calculates that a server failure costs $40,000 per event and strikes about twice a year, producing an $80,000 expected annual loss to weigh against the cost of controls. Which risk analysis approach is this?","options":["Qualitative","Quantitative","Semi-quantitative","Hybrid"],"correctIndex":1,"explanation":"Quantitative. Hard dollar values and frequency math (SLE x ARO = ALE) are quantitative analysis, built for cost-benefit decisions. The tell: quantitative = numbers and currency, qualitative = High/Medium/Low judgment, semi-quantitative/hybrid = mixtures of the two."},
  {"id":"q601","domain":"D5","family":"qual-quant","question":"A workshop team rates each risk High, Medium, or Low on a likelihood-versus-impact matrix using expert judgment alone - not one monetary figure appears anywhere. Which approach is this?","options":["Qualitative","Quantitative","Hybrid","Semi-quantitative"],"correctIndex":0,"explanation":"Qualitative. Subjective ratings on a matrix, no dollars, is qualitative analysis: faster and easier, less precise. The tell: qualitative = judgment categories, quantitative = calculated currency values, hybrid/semi-quantitative = blends."},
  {"id":"q602","domain":"D5","family":"qual-quant","question":"An auditor asks which risk analysis method relies on subjective ratings and expert opinion rather than objective monetary calculation. Which is it?","options":["Quantitative","Semi-quantitative","Qualitative","Hybrid"],"correctIndex":2,"explanation":"Qualitative. Expert judgment expressed in categories rather than currency defines qualitative analysis. The tell: qualitative = subjective ratings, quantitative = objective dollars and math, semi-quantitative = numeric scales without true currency, hybrid = deliberate mix."},
  {"id":"q603","domain":"D5","family":"qual-quant","question":"An analyst multiplies asset value by an exposure factor, then by an annualized rate of occurrence, arriving at a precise expected yearly loss in dollars to justify a control purchase. Which risk analysis approach is this?","options":["qualitative","quantitative","semi-quantitative","hybrid rating"],"correctIndex":1,"explanation":"Quantitative. The SLE/ARO/ALE arithmetic producing currency figures is quantitative analysis, purpose-built for cost-benefit arguments. The tell: quantitative = formulas and dollars, qualitative = expert judgment in categories, semi-quantitative/hybrid = partial blends."},
  {"id":"q604","domain":"D5","family":"qual-quant","question":"A steering committee assigns each risk a red, amber, or green rating based purely on members' expert judgment - no dollar figure appears in the workbook. Which approach is this?","options":["semi-quantitative","quantitative","qualitative","hybrid analysis"],"correctIndex":2,"explanation":"Qualitative. Judgment-based category ratings without monetary calculation are qualitative. The tell: qualitative = colors and categories from expert opinion, quantitative = computed currency, semi-quantitative = numeric scales standing in for money, hybrid = a deliberate mix."},
  {"id":"q605","domain":"D5","family":"qual-quant","question":"An exam question asks which risk analysis method produces objective, monetary results using formulas such as SLE, ARO, and ALE. Which is it?","options":["quantitative","qualitative","semi-quantitative","subjective scoring"],"correctIndex":0,"explanation":"Quantitative. SLE, ARO, and ALE are the quantitative toolkit: objective, reproducible, expressed in money. The tell: quantitative = the formula family, qualitative = subjective ratings, semi-quantitative = scales without true currency, subjective scoring = qualitative by another name."},
  {"id":"q606","domain":"D5","family":"risk-math","question":"A production database server is valued at $200,000. Fire modeling says a single fire would destroy 25 percent of its value. What is the single loss expectancy (SLE)?","options":["$100,000","$25,000","$200,000","$50,000"],"correctIndex":3,"explanation":"$50,000. SLE = asset value x exposure factor = $200,000 x 0.25. The tell: SLE = cost of ONE event (AV x EF), ALE = cost per YEAR (SLE x ARO), EF = the percentage lost, ARO = events per year."},
  {"id":"q607","domain":"D5","family":"risk-math","question":"A warehouse is valued at $500,000. A flood would destroy 40 percent of it, and floods are expected once every 2 years. What is the annualized loss expectancy (ALE)?","options":["$200,000","$250,000","$1,000,000","$100,000"],"correctIndex":3,"explanation":"$100,000. SLE = $500,000 x 0.40 = $200,000; ARO = once per 2 years = 0.5; ALE = $200,000 x 0.5. The tell: ALE = SLE x ARO, and an every-other-year event has ARO 0.5, not 2."},
  {"id":"q608","domain":"D5","family":"risk-math","question":"A risk register lists a server's single loss expectancy as $40,000 and its annualized loss expectancy as $10,000. How often is the loss event expected to occur?","options":["Once every 4 years","Four times per year","Once every 10 years","Twice per year"],"correctIndex":0,"explanation":"Once every 4 years. ARO = ALE / SLE = 10,000 / 40,000 = 0.25 events per year, i.e., one event per 4 years. The tell: the ALE formula runs both ways - divide ALE by SLE to recover the frequency."},
  {"id":"q609","domain":"D5","family":"risk-math","question":"Hydrology data says a data center flood should occur once every 5 years. What is the annualized rate of occurrence (ARO)?","options":["0.2","5","1","0.5"],"correctIndex":0,"explanation":"0.2. ARO expresses events per single year: 1 event / 5 years = 0.2. The tell: ARO = yearly frequency, so rarer-than-annual events have AROs below 1 - never write 5 for a once-in-5-years event."},
  {"id":"q610","domain":"D5","family":"risk-math","question":"A facility is valued at $1,200,000. Each occurrence of a particular event destroys 15 percent of its value, and the event strikes about 3 times per year. What is the annualized loss expectancy (ALE)?","options":["$180,000","$540,000","$360,000","$60,000"],"correctIndex":1,"explanation":"$540,000. SLE = $1,200,000 x 0.15 = $180,000; ALE = SLE x ARO = $180,000 x 3. The tell: two multiplications, in order - value x EF gives one event's cost, then x ARO annualizes it."},
  {"id":"q611","domain":"D5","family":"risk-math","question":"Company laptops worth $60,000 in total keep walking out the door: each theft incident wipes out 30 percent of that value, and history shows about two incidents per year. What annualized loss expectancy (ALE) should the risk register show?","options":["$18,000","$72,000","$36,000","$9,000"],"correctIndex":2,"explanation":"$36,000. SLE = $60,000 x 0.30 = $18,000; ALE = $18,000 x 2. The tell: $18,000 is the SLE trap answer - stopping one multiplication early is the classic mistake this question punishes."},
  {"id":"q612","domain":"D5","family":"risk-math","question":"A database server is valued at $80,000, and a ransomware event is expected to destroy 45 percent of its value in one occurrence. What is the single loss expectancy (SLE)?","options":["$18,000","$36,000","$44,000","$80,000"],"correctIndex":1,"explanation":"$36,000. SLE = asset value x exposure factor = $80,000 x 0.45. The tell: SLE is one event's damage - value times the loss percentage, nothing about frequency yet."},
  {"id":"q613","domain":"D5","family":"risk-math","question":"A storage array is valued at $250,000. A power surge destroys 20 percent of its value per occurrence and is expected once every 4 years. What is the annualized loss expectancy (ALE)?","options":["$50,000","$62,500","$200,000","$12,500"],"correctIndex":3,"explanation":"$12,500. SLE = $250,000 x 0.20 = $50,000; ARO = 1/4 = 0.25; ALE = $50,000 x 0.25. The tell: $50,000 is the SLE trap - remember to multiply by the fractional ARO for events rarer than yearly."},
  {"id":"q614","domain":"D5","family":"risk-math","question":"A risk report lists a single loss expectancy of $30,000 and an annualized loss expectancy of $90,000. What is the annualized rate of occurrence (ARO)?","options":["0.33","2","3","1.5"],"correctIndex":2,"explanation":"3. ARO = ALE / SLE = 90,000 / 30,000 = 3 events per year. The tell: when ALE exceeds SLE, the event strikes more than once a year - divide to recover the frequency."},
  {"id":"q615","domain":"D5","family":"probability-impact","question":"A risk analysis concludes that IF a breach occurs, the resulting harm - lawsuits, regulatory fines, customer exodus - would be severe. Which dimension of risk does this describe?","options":["Probability","Likelihood","Exposure factor","Impact"],"correctIndex":3,"explanation":"Impact. How bad the consequences would be is impact; how likely it is to happen is probability/likelihood. The tell: impact = severity of the harm, probability/likelihood = chance it occurs, exposure factor = the percentage of asset value lost per event."},
  {"id":"q616","domain":"D5","family":"probability-impact","question":"In a quantitative risk model, one variable expresses the percentage of an asset's value that would be lost in a single event. Which term names it?","options":["Probability","Likelihood","Exposure factor","Impact"],"correctIndex":2,"explanation":"Exposure factor. The per-event loss percentage is the EF, multiplied by asset value to produce SLE. The tell: exposure factor = percent of value lost, impact = the overall severity concept, probability/likelihood = the chance of occurrence."},
  {"id":"q617","domain":"D5","family":"probability-impact","question":"A workshop rates the chance of a successful phishing attack this year as \"high,\" based on the panel's expert judgment rather than any computed statistic. This qualitative expression of chance is the:","options":["probability","likelihood","impact","exposure factor"],"correctIndex":1,"explanation":"Likelihood. In SY0-701 usage, likelihood is the qualitative judgment of chance; probability is its statistically computed counterpart. The tell: likelihood = judged chance (high/medium/low), probability = calculated chance (a number), impact = how bad, exposure factor = percent of value lost."},
  {"id":"q618","domain":"D5","family":"probability-impact","question":"In a quantitative model, the numerically computed, statistical chance that a given event will occur is called the:","options":["probability","likelihood","exposure factor","impact"],"correctIndex":0,"explanation":"Probability. The computed numeric chance is probability; the qualitative judged version is likelihood. The tell: probability = the statistic, likelihood = the judgment, impact = severity of consequences, exposure factor = per-event loss percentage."},
  {"id":"q619","domain":"D5","family":"risk-register","question":"The security team tracks \"number of overdue critical patches\" because when that number climbs, it signals a specific risk is growing before any incident occurs. In risk register terms, this early-warning metric is a:","options":["Key risk indicator (KRI)","Risk owner","Risk threshold","Risk appetite"],"correctIndex":0,"explanation":"Key risk indicator. A measurable metric that warns a risk is rising is a KRI, the register's smoke detector. The tell: KRI = the early-warning metric, risk owner = the accountable person, risk threshold = the trigger line that demands action, risk appetite = how much risk the org wants overall."},
  {"id":"q620","domain":"D5","family":"risk-register","question":"Every entry in the risk register names exactly one accountable manager responsible for monitoring that risk and driving its treatment. That named individual is the:","options":["Key risk indicator (KRI)","Risk threshold","Risk appetite","Risk owner"],"correctIndex":3,"explanation":"Risk owner. Each risk gets one accountable person; without an owner, treatment stalls. The tell: risk owner = the accountable name on the line, KRI = the warning metric, risk threshold = the action trigger, risk appetite = the organization's overall willingness to take risk."},
  {"id":"q621","domain":"D5","family":"risk-register","question":"The register specifies that once unpatched critical systems exceed ten, the risk becomes unacceptable and treatment must begin immediately. This preset level that forces action is the:","options":["key risk indicator","risk owner","risk threshold","risk tolerance"],"correctIndex":2,"explanation":"Risk threshold. The defined line that, once crossed, mandates action is the threshold; the metric being watched is the KRI. The tell: risk threshold = the trigger line, key risk indicator = the metric approaching it, risk owner = the accountable person, risk tolerance = acceptable deviation on the risk."},
  {"id":"q622","domain":"D5","family":"risk-register","question":"An auditor asks which risk register element is a measurable metric providing early warning that a particular risk's level is climbing. Which is it?","options":["risk threshold","risk owner","risk tolerance","key risk indicator"],"correctIndex":3,"explanation":"Key risk indicator. The KRI is the watched metric whose movement warns of rising risk before an incident. The tell: KRI = the early-warning gauge, risk threshold = the line on that gauge that triggers action, risk owner = who must act, risk tolerance = how much drift is acceptable."},
  {"id":"q623","domain":"D5","family":"risk-appetite","question":"A fintech startup's board explicitly embraces significant risk - launching fast, entering unproven markets - because capturing market share quickly matters more than avoiding losses. Which risk appetite posture is this?","options":["Expansionary","Conservative","Neutral","Risk tolerance"],"correctIndex":0,"explanation":"Expansionary. Willingly taking on substantial risk in pursuit of growth is the expansionary appetite. The tell: expansionary = risk-hungry for reward, conservative = risk-averse, neutral = balanced middle, risk tolerance = the acceptable deviation on one specific risk, not the overall posture."},
  {"id":"q624","domain":"D5","family":"risk-appetite","question":"A governance course asks for the term describing the broad, overall amount of risk an organization is willing to pursue or retain in exchange for reward. Which term is it?","options":["Risk tolerance","Risk appetite","Conservative","Neutral"],"correctIndex":1,"explanation":"Risk appetite. Appetite is the organization-wide, strategic quantity of risk leadership wants to take. The tell: risk appetite = the overall willingness, risk tolerance = the per-risk acceptable deviation around it, conservative/neutral/expansionary = the postures appetite can take."},
  {"id":"q625","domain":"D5","family":"risk-appetite","question":"A bank publishes its overall appetite, then adds: no single trading desk may deviate more than 2 percent from its assigned risk limit before mandatory action. That 2 percent boundary is an example of what?","options":["Risk tolerance","Expansionary posture","Risk appetite","Conservative posture"],"correctIndex":0,"explanation":"Risk tolerance. The permissible deviation around a specific limit is tolerance - the operational fine print under the broad appetite. The tell: risk tolerance = acceptable variance on one risk/limit, risk appetite = the overall strategic willingness, postures = the flavor of that appetite."},
  {"id":"q626","domain":"D5","family":"risk-appetite","question":"A regulated pension fund's charter minimizes risk-taking: it accepts only investments with near-certain outcomes, sacrificing returns to protect beneficiaries. Which risk appetite posture is this?","options":["expansionary","conservative","neutral","risk tolerance"],"correctIndex":1,"explanation":"Conservative. Deliberately minimizing risk even at the cost of reward is the conservative posture. The tell: conservative = risk-averse, expansionary = risk-hungry, neutral = balanced, risk tolerance = the acceptable variance on one specific risk, not a posture."},
  {"id":"q627","domain":"D5","family":"risk-appetite","question":"A mid-size firm's strategy balances growth against caution: measured risks where the numbers justify them, no strong lean toward aggression or restraint. Which risk appetite posture fits BEST?","options":["expansionary","risk tolerance","neutral","conservative"],"correctIndex":2,"explanation":"Neutral. A balanced middle posture, taking justified risks without favoring either extreme, is neutral appetite. The tell: neutral = the balanced middle, expansionary = growth-hungry, conservative = protective, risk tolerance = per-risk variance, not the overall posture."},
  {"id":"q628","domain":"D5","family":"risk-appetite","question":"A governance quiz distinguishes two terms: one is the organization's overall willingness to take risk; the other is the acceptable variance around a SPECIFIC risk before action is required. Which term is the second one?","options":["risk appetite","risk tolerance","expansionary appetite","neutral appetite"],"correctIndex":1,"explanation":"Risk tolerance. Tolerance operates per-risk: how far one risk may drift before action. Appetite is the broad strategic willingness. The tell: appetite = the overall meal, tolerance = the wiggle room on each dish."},
  {"id":"q629","domain":"D5","family":"risk-strategies","question":"A company purchases a cyber-insurance policy so that if a data breach lands, the payout comes from the insurer rather than the business's own balance sheet. Which risk strategy is this?","options":["Accept","Mitigate","Transfer","Avoid"],"correctIndex":2,"explanation":"Transfer. Shifting the financial consequences to a third party - insurance being the classic vehicle - is risk transference. The tell: transfer = someone else absorbs the loss, mitigate = reduce it with controls, accept = live with it knowingly, avoid = stop doing the risky thing."},
  {"id":"q630","domain":"D5","family":"risk-strategies","question":"After reviewing fraud models, management cancels the planned overseas instant-payment feature entirely: the exposure is too high at any price, so the activity simply will not happen. Which strategy did they choose?","options":["Avoid","Mitigate","Transfer","Accept"],"correctIndex":0,"explanation":"Avoid. Eliminating the risk by not undertaking the activity at all is avoidance, the only strategy that takes the risk to zero - along with the reward. The tell: avoid = discontinue the activity, mitigate = do it with safeguards, transfer = do it with insurance, accept = do it and absorb the risk."},
  {"id":"q631","domain":"D5","family":"risk-strategies","question":"To cut ransomware risk, a firm deploys EDR, segments its network, and keeps offline immutable backups - and continues operating normally with the risk reduced but not gone. Which strategy is this?","options":["Accept","Avoid","Mitigate","Transfer"],"correctIndex":2,"explanation":"Mitigate. Applying controls to shrink probability or impact while continuing the activity is mitigation, the most common strategy. The tell: mitigate = reduce with safeguards, avoid = stop entirely, transfer = shift the loss, accept = take it as-is."},
  {"id":"q632","domain":"D5","family":"risk-strategies","question":"A low-impact reporting bug would cost $50,000 to fix but could never cause more than $5,000 in harm. Leadership documents the analysis, signs off, and leaves it as-is. Which strategy is this?","options":["Mitigate","Accept","Transfer","Avoid"],"correctIndex":1,"explanation":"Accept. A conscious, documented decision to absorb a risk because treatment costs more than the exposure is acceptance - rational when the math says so. The tell: accept = informed sign-off to live with it, mitigate = spend to reduce it, transfer = pay someone else to hold it, avoid = drop the activity."},
  {"id":"q633","domain":"D5","family":"risk-strategies","question":"A retailer hands all payment card handling to a payment processor, and the contract makes the processor liable for losses from any card-data breach on its platform. Which risk strategy does this represent?","options":["Transfer","Avoid","Accept","Mitigate"],"correctIndex":0,"explanation":"Transfer. Contractually shifting liability to the vendor is transference without insurance - outsourcing the risk along with the function. The tell: transfer = liability moves to a third party by contract or policy, avoid = stop taking cards entirely, mitigate = harden your own handling, accept = keep the liability knowingly."},
  {"id":"q634","domain":"D5","family":"risk-strategies","question":"A study guide defines one strategy as reducing a risk's probability or impact by applying safeguards while the organization continues the activity itself. Which strategy is defined?","options":["Accept","Transfer","Avoid","Mitigate"],"correctIndex":3,"explanation":"Mitigate. Keep doing it, but with controls that shrink the risk - the definition of mitigation. The tell: mitigate = continue with safeguards, avoid = discontinue, transfer = shift the loss, accept = continue with no treatment at all."},
  {"id":"q635","domain":"D5","family":"risk-strategies","question":"A research lab receives permanent, documented approval excusing its entire class of legacy scanners from the encryption-at-rest requirement for as long as those devices remain in service. What is this arrangement best called?","options":["Exception","Accept","Avoid","Exemption"],"correctIndex":3,"explanation":"Exemption. A standing, indefinite excusal of a defined class from a requirement is an exemption; a one-off, time-boxed deviation would be an exception. The tell: exemption = permanent carve-out for a category, exception = temporary one-time deviation, accept/avoid = general risk strategies, not policy-relief mechanisms."},
  {"id":"q636","domain":"D5","family":"risk-strategies","question":"For one migration weekend only, a manager requests and receives documented approval to run a service without the mandatory logging agent, restoring compliance Monday morning. What is this one-off deviation called?","options":["Exemption","Exception","Transfer","Mitigate"],"correctIndex":1,"explanation":"Exception. A temporary, time-boxed, documented deviation from policy is an exception; had it been a permanent carve-out it would be an exemption. The tell: exception = one-time and temporary, exemption = standing and indefinite, transfer/mitigate = risk strategies, not policy relief."},
  {"id":"q637","domain":"D5","family":"risk-strategies","question":"Transferring a risk keeps the activity going while shifting its losses to another party. Which strategy instead eliminates the risk by discontinuing the activity completely?","options":["Accept","Mitigate","Avoid","Transfer"],"correctIndex":2,"explanation":"Avoid. Only avoidance removes the risk outright, because the risky activity itself ends. The tell: avoid = the activity stops, transfer = activity continues, loss moves elsewhere, mitigate = activity continues with controls, accept = activity continues untreated."},
  {"id":"q638","domain":"D5","family":"risk-strategies","question":"Unlike mitigation, which spends effort lowering a risk with controls, which strategy involves consciously deciding to apply no treatment and simply absorb any loss that comes?","options":["Accept","Avoid","Transfer","Mitigate"],"correctIndex":0,"explanation":"Accept. Acceptance is a deliberate, informed decision to carry the risk untreated - legitimate when exposure is small or treatment uneconomical, dangerous when it is just neglect. The tell: accept = knowing inaction, mitigate = active reduction, transfer = shifted loss, avoid = ended activity."},
  {"id":"q639","domain":"D5","family":"risk-strategies","question":"To shrink the damage from stolen laptops, a firm enables full-disk encryption and remote wipe on every device - staff keep working normally, but a theft now costs hardware instead of data. Which risk strategy is this?","options":["mitigate","avoid","accept","transfer"],"correctIndex":0,"explanation":"Mitigate. Controls that reduce the impact while the activity continues are mitigation. The tell: mitigate = reduce with safeguards, avoid = stop issuing laptops, transfer = insure the loss, accept = live with unencrypted risk."},
  {"id":"q640","domain":"D5","family":"risk-strategies","question":"Legal review finds a proposed drone-delivery pilot carries liability the company cannot stomach at any price, so the board kills the program before launch. Which strategy is this?","options":["transfer","mitigate","accept","avoid"],"correctIndex":3,"explanation":"Avoid. Declining to undertake the risky activity at all is avoidance - zero risk, zero reward. The tell: avoid = never start the activity, mitigate = start it with safeguards, transfer = start it insured, accept = start it and absorb the risk."},
  {"id":"q641","domain":"D5","family":"risk-strategies","question":"A small firm negotiates its cloud contract so the provider is contractually liable for losses caused by platform outages. The firm keeps using the platform; the loss just lands elsewhere. Which risk strategy is this?","options":["transfer","mitigate","accept","avoid"],"correctIndex":0,"explanation":"Transfer. Moving the financial consequences to a third party by contract is transference. The tell: transfer = the loss is someone else's bill, mitigate = reduce the loss, accept = pay it yourself, avoid = end the dependency."},
  {"id":"q642","domain":"D5","family":"risk-strategies","question":"Leadership reviews a cosmetic defect in an internal tool, concludes any harm would be trivial, documents the decision, and formally takes no action. Which strategy is this?","options":["transfer","avoid","accept","mitigate"],"correctIndex":2,"explanation":"Accept. A documented, informed decision to tolerate a trivial risk is acceptance done right - the paper trail is what separates it from negligence. The tell: accept = deliberate inaction on record, mitigate = act to reduce, transfer = shift the cost, avoid = eliminate the activity."},
  {"id":"q643","domain":"D5","family":"risk-strategies","question":"A hospital grants its entire fleet of legacy imaging workstations a permanent, standing waiver from the multifactor-login standard for as long as those units remain in service. What is this arrangement?","options":["exception","accept","mitigate","exemption"],"correctIndex":3,"explanation":"Exemption. A standing, indefinite waiver covering a whole class of systems is an exemption. The tell: exemption = permanent carve-out for a category, exception = temporary one-off deviation, accept/mitigate = risk strategies rather than policy-relief instruments."},
  {"id":"q644","domain":"D5","family":"risk-strategies","question":"For one quarterly close only, finance receives documented approval to bypass the dual-approval control on a single report, with the control resuming immediately after. What is this deviation called?","options":["exemption","exception","accept","avoid"],"correctIndex":1,"explanation":"Exception. One-time, time-boxed, documented deviation = exception; permanent class-wide relief would be an exemption. The tell: exception = this once, exemption = from now on, accept/avoid = risk strategies, not policy waivers."},
  {"id":"q645","domain":"D5","family":"risk-strategies","question":"An insurance broker describes a risk strategy that keeps the activity running while a third party - an insurer or outsourcer - absorbs the financial consequences of any loss. Which strategy is it?","options":["accept","transfer","mitigate","avoid"],"correctIndex":1,"explanation":"Transfer. Activity continues, loss lands on the third party: transference via insurance or contract. The tell: transfer = the payout comes from elsewhere, accept = from your own budget, mitigate = made smaller by controls, avoid = never incurred."},
  {"id":"q646","domain":"D5","family":"risk-strategies","question":"A risk workshop asks: which strategy eliminates a risk entirely, accomplished by ceasing the activity that creates it?","options":["mitigate","accept","avoid","transfer"],"correctIndex":2,"explanation":"Avoid. Only stopping the activity removes the risk completely; every other strategy leaves residual risk. The tell: avoid = the risk source is gone, mitigate = shrunk, transfer = relocated, accept = retained."},
  {"id":"q647","domain":"D5","family":"risk-strategies","question":"A vulnerable public service cannot be retired, so rather than leaving it exposed or shutting it down, the team fronts it with a web application firewall and tighter access rules. The service keeps running with less exposure. Which strategy is this?","options":["mitigate","accept","avoid","transfer"],"correctIndex":0,"explanation":"Mitigate. Adding controls to lower exposure while continuing the service is mitigation, the everyday middle path. The tell: mitigate = keep running, better protected, avoid = shut it down, accept = keep running unprotected, transfer = make the loss someone else's."},
  {"id":"q648","domain":"D5","family":"risk-strategies","question":"Actuarial review shows a rare risk whose worst case costs less than either the insurance premium or the fix, so the company simply budgets a reserve to absorb any loss itself. Which strategy is this?","options":["transfer","mitigate","avoid","accept"],"correctIndex":3,"explanation":"Accept. Consciously self-funding a small risk because treatment costs more than exposure is textbook acceptance. The tell: accept = budget for the loss yourself, transfer = pay premiums so another pays the loss, mitigate = pay to shrink it, avoid = walk away from it."},
  {"id":"q649","domain":"D5","family":"bia","question":"The business impact analysis states that after an outage, the payment system must be back online within 2 hours before harm becomes unacceptable. Which metric is that 2-hour target?","options":["RPO","RTO","MTTR","MTBF"],"correctIndex":1,"explanation":"RTO. The recovery time objective is the maximum tolerable downtime - how fast service must return. The tell: RTO = how long you can be DOWN, RPO = how much DATA you can lose, MTTR = average repair time observed, MTBF = average time between failures."},
  {"id":"q650","domain":"D5","family":"bia","question":"A database is backed up every 4 hours because the business declared it can tolerate losing at most 4 hours of transactions in a disaster. Which metric defines that acceptable data-loss window?","options":["RTO","MTBF","RPO","MTTR"],"correctIndex":2,"explanation":"RPO. The recovery point objective is the maximum acceptable data loss measured in time, and it directly dictates backup frequency. The tell: RPO = data-loss window, RTO = downtime window, MTBF = reliability between failures, MTTR = repair duration."},
  {"id":"q651","domain":"D5","family":"bia","question":"A reliability report tracks how long, on average, technicians take to repair a failed component and return it to service. Which metric is this?","options":["MTTR","MTBF","RTO","RPO"],"correctIndex":0,"explanation":"MTTR. Mean time to repair is the observed average fix-and-restore duration. The tell: MTTR = average repair time, MTBF = average uptime between failures, RTO = the downtime target you set, RPO = the data-loss target you set. Objectives are goals; MTTR/MTBF are measurements."},
  {"id":"q652","domain":"D5","family":"bia","question":"For a repairable server, which metric captures the average operating time between one failure and the next, serving as the core indicator of its reliability?","options":["MTTR","RPO","RTO","MTBF"],"correctIndex":3,"explanation":"MTBF. Mean time between failures measures how long the device typically runs before breaking again - bigger is better. The tell: MTBF = time between failures, MTTR = time to fix each one, RTO/RPO = recovery objectives the business sets, not measurements."},
  {"id":"q653","domain":"D5","family":"bia","question":"An e-commerce company engineers its backup pipeline so that after ANY incident, no more than 15 minutes of order data can ever be lost. Which metric does the 15-minute limit define?","options":["RTO","MTTR","MTBF","RPO"],"correctIndex":3,"explanation":"RPO. Maximum tolerable data loss expressed as time is the recovery point objective, and it dictates backup/replication frequency. The tell: RPO = how much data you may lose, RTO = how long you may be down, MTTR = observed repair time, MTBF = observed time between failures."},
  {"id":"q654","domain":"D5","family":"bia","question":"A reliability engineer cites a server model's MTBF in a hardware selection meeting. What does that value actually describe?","options":["target time to restore service","average operating time between failures","maximum tolerable data loss","average time to repair a failure"],"correctIndex":1,"explanation":"MTBF = average run time between failures, the core reliability statistic - higher is better. The tell: MTBF = uptime between breaks, MTTR = time to fix each break, RTO = the restore target you set, RPO = the data-loss target you set."},
  {"id":"q655","domain":"D5","family":"bia","question":"A vendor's datasheet boasts that its appliances average four hours from the moment of failure to being repaired and back in service. Which metric is that four-hour figure?","options":["MTBF","RTO","MTTR","RPO"],"correctIndex":2,"explanation":"MTTR. Average failure-to-fixed duration is mean time to repair, a measured property of the product and support process. The tell: MTTR = the observed repair average, RTO = the recovery target the business demands, MTBF = time between failures, RPO = data-loss tolerance."},
  {"id":"q656","domain":"D5","family":"vendor-assessment","question":"Before signing with a payment vendor, a bank insists the contract include a provision letting the bank inspect the vendor's security controls and records on demand throughout the relationship. Which element is this?","options":["Independent assessment","Right-to-audit clause","Supply chain analysis","Due diligence"],"correctIndex":1,"explanation":"Right-to-audit clause. The contractual right to inspect the vendor yourself, on demand, is the right-to-audit provision. The tell: right-to-audit = you may inspect them, independent assessment = a neutral third party inspects them, supply chain analysis = examining their upstream suppliers, due diligence = the pre-signing investigation."},
  {"id":"q657","domain":"D5","family":"vendor-assessment","question":"A manufacturer maps risk beyond its direct vendor, evaluating the smaller upstream firms that supply that vendor's chips and firmware for hidden compromise or fragility. Which vendor-assessment activity is this?","options":["Supply chain analysis","Right-to-audit clause","Conflict of interest","Penetration testing"],"correctIndex":0,"explanation":"Supply chain analysis. Looking past the direct vendor to the suppliers behind it is supply chain analysis - risk inherits upstream. The tell: supply chain analysis = the vendors behind your vendor, right-to-audit = your contractual inspection right, conflict of interest = competing loyalties, penetration testing = technical attack simulation."},
  {"id":"q658","domain":"D5","family":"vendor-assessment","question":"A bank asks a prospective vendor for a report in which an unaffiliated assessment firm - chosen for having no stake in the outcome - objectively reviewed the vendor's security controls. Which vendor-assessment element is this?","options":["right-to-audit clause","penetration testing","independent assessment","supply chain analysis"],"correctIndex":2,"explanation":"Independent assessment. A neutral third party's objective review (a SOC 2 report, for example) is the independent assessment. The tell: independent assessment = an unaffiliated firm reviews them, right-to-audit = YOU may inspect them by contract, supply chain analysis = reviewing their upstream suppliers, penetration testing = simulated attack."},
  {"id":"q659","domain":"D5","family":"vendor-assessment","question":"During vendor selection, a reviewer discloses that her spouse holds shares in one of the bidding firms - a personal interest that could bias her scoring. Which concern is this?","options":["due diligence","conflict of interest","independent assessment","right-to-audit clause"],"correctIndex":1,"explanation":"Conflict of interest. A personal stake that could compromise professional judgment is a conflict of interest, and disclosure is the required first step. The tell: conflict of interest = competing loyalties, due diligence = the investigation itself, independent assessment = neutral review, right-to-audit = the inspection clause."},
  {"id":"q660","domain":"D5","family":"agreements","question":"A managed hosting contract guarantees 99.95 percent uptime and 30-minute response times, with service credits automatically owed whenever targets are missed. Which agreement is this?","options":["MOU","MSA","BPA","SLA"],"correctIndex":3,"explanation":"SLA. Measurable targets plus penalties for missing them are the service level agreement's signature - numbers with teeth. The tell: SLA = metrics and penalties, MOU = non-binding intent, MSA = master framework terms, BPA = partnership structure."},
  {"id":"q661","domain":"D5","family":"agreements","question":"Two universities sign a document expressing their shared intent to collaborate on research. It is deliberately non-binding: no enforceable obligations, no money, just recorded goodwill. Which agreement is this?","options":["SLA","MOU","SOW","NDA"],"correctIndex":1,"explanation":"MOU. A memorandum of understanding records mutual intent without legal enforceability. The tell: MOU = non-binding intent, MOA = its binding cousin with defined responsibilities, SLA = measurable service targets, SOW = one project's deliverables, NDA = confidentiality only."},
  {"id":"q662","domain":"D5","family":"agreements","question":"A company and a consulting firm negotiate the general legal and commercial terms once - liability, payment, IP ownership - in an overarching contract, so each future project needs only a short add-on. Which agreement is this?","options":["SOW","MOA","MSA","SLA"],"correctIndex":2,"explanation":"MSA. The master service agreement is the framework contract that individual statements of work hang off. The tell: MSA = master framework signed once, SOW = per-project specifics under it, MOA = binding cooperation roles, SLA = service metrics and penalties."},
  {"id":"q663","domain":"D5","family":"agreements","question":"Under an existing master contract, the parties execute a document spelling out exactly one website build: deliverables, timeline, milestones, and price for that project alone. Which agreement is this?","options":["MSA","MOU","SOW","BPA"],"correctIndex":2,"explanation":"SOW. The statement of work defines one specific engagement's deliverables and schedule beneath the MSA's umbrella. The tell: SOW = one project's specifics, MSA = the standing framework above it, MOU = non-binding intent, BPA = partnership terms."},
  {"id":"q664","domain":"D5","family":"agreements","question":"Before granting a contractor access to proprietary source code, a firm requires a signed document legally barring the contractor from disclosing any confidential information encountered. Which agreement is this?","options":["NDA","MOU","SLA","MOA"],"correctIndex":0,"explanation":"NDA. The non-disclosure agreement's single job is enforceable confidentiality. The tell: NDA = secrecy obligations only, MOU = non-binding cooperation intent, SLA = service metrics, MOA = binding roles and responsibilities."},
  {"id":"q665","domain":"D5","family":"agreements","question":"Two firms forming a joint venture sign a document defining each partner's capital contribution, profit split, and decision-making authority in the shared business. Which agreement is this?","options":["MSA","SLA","SOW","BPA"],"correctIndex":3,"explanation":"BPA. The business partnership agreement structures the partnership itself - money in, profits out, who decides. The tell: BPA = partnership economics and governance, MSA = client/vendor master terms, SLA = service targets, SOW = a single project."},
  {"id":"q666","domain":"D5","family":"agreements","question":"Two agencies outgrow their loose understanding and sign a more formal, binding document assigning specific roles and responsibilities to each party - though no money changes hands. Which agreement is this?","options":["MOU","MOA","NDA","SLA"],"correctIndex":1,"explanation":"MOA. The memorandum of agreement is the binding step up from an MOU: defined responsibilities each party must honor. The tell: MOA = binding with assigned roles, MOU = non-binding intent, NDA = confidentiality, SLA = measurable service commitments."},
  {"id":"q667","domain":"D5","family":"agreements","question":"An IT director is asked to review the SLA in a new cloud contract before signature. What does that document primarily establish?","options":["A non-binding statement of mutual intent to cooperate","Overarching master terms that future projects reference","Measurable service targets and penalties for missing them","The contribution and profit terms of a business partnership"],"correctIndex":2,"explanation":"SLA = targets plus consequences. Uptime percentages, response times, and the credits owed when missed. The tell: SLA = the numbers and the penalties, MOU = intent, MSA = the master framework, BPA = partnership economics."},
  {"id":"q668","domain":"D5","family":"agreements","question":"Unlike an MOA, which binds each party to defined roles and responsibilities, which document records only a general, non-binding statement of mutual intent to cooperate?","options":["MOU","SOW","MOA","MSA"],"correctIndex":0,"explanation":"MOU. Understanding versus agreement: the MOU expresses intent without enforceable obligations, while the MOA commits parties to defined duties. The tell: MOU = handshake on paper, MOA = binding responsibilities, SOW = project specifics, MSA = master terms."},
  {"id":"q669","domain":"D5","family":"agreements","question":"A facilities vendor receives a client document authorizing one discrete task: replace the badge readers at a single office by June 30 for a fixed price. Which document is this?","options":["MOU","BPA","SOW","NDA"],"correctIndex":2,"explanation":"SOW. One defined task, one deadline, one price - the statement of work scopes a single engagement. The tell: SOW = the specific job's what/when/how much, MOU = non-binding intent, BPA = partnership terms, NDA = confidentiality."},
  {"id":"q670","domain":"D5","family":"agreements","question":"A cloud storage contract promises 99.99 percent availability, measured monthly, with service credits issued automatically whenever uptime falls short. Which agreement defines these targets and penalties?","options":["MOU","BPA","SLA","MSA"],"correctIndex":2,"explanation":"SLA. Numeric commitments with automatic penalties are the service level agreement's whole identity. The tell: SLA = measurable targets plus consequences, MOU = non-binding intent, MSA = the master framework, BPA = partnership terms."},
  {"id":"q671","domain":"D5","family":"agreements","question":"Two nonprofits sign a short document recording their shared intent to cooperate on a community food drive. It is explicitly non-binding: no enforceable obligations on either side. Which agreement is this?","options":["MOA","SLA","SOW","MOU"],"correctIndex":3,"explanation":"MOU. Non-binding recorded intent is the memorandum of understanding; adding binding assigned duties would make it an MOA. The tell: MOU = goodwill on paper, MOA = binding roles, SLA = measured service promises, SOW = one project's scope."},
  {"id":"q672","domain":"D5","family":"agreements","question":"Two government agencies formalize a shared data-exchange program with a binding document assigning each side specific operational duties - though no money changes hands. Which agreement is this?","options":["MOA","MOU","MSA","NDA"],"correctIndex":0,"explanation":"MOA. Binding, role-assigning cooperation without payment is the memorandum of agreement, the enforceable step past an MOU. The tell: MOA = binding duties, MOU = non-binding intent, MSA = commercial master terms, NDA = confidentiality."},
  {"id":"q673","domain":"D5","family":"agreements","question":"A company and its supplier sign one overarching contract fixing the general legal, payment, and liability terms, so each future project can start with a short scope document instead of months of renegotiation. Which agreement is this?","options":["SOW","MSA","SLA","BPA"],"correctIndex":1,"explanation":"MSA. The master service agreement settles the framework once; statements of work then attach per project. The tell: MSA = negotiate once, reuse forever, SOW = the per-project attachment, SLA = service metrics, BPA = partnership structure."},
  {"id":"q674","domain":"D5","family":"agreements","question":"Beneath an existing master contract, the parties execute a document listing the precise deliverables, milestones, and completion date for one mobile-app development project. Which document is this?","options":["MSA","SLA","SOW","MOU"],"correctIndex":2,"explanation":"SOW. One project's deliverables, dates, and milestones under the master framework is the statement of work. The tell: SOW = the specific job, MSA = the umbrella above it, SLA = ongoing service metrics, MOU = non-binding intent."},
  {"id":"q675","domain":"D5","family":"agreements","question":"Before entering an acquisition due-diligence data room, each investor must sign a document legally forbidding disclosure of anything confidential seen inside. Which agreement is this?","options":["BPA","MOA","SLA","NDA"],"correctIndex":3,"explanation":"NDA. Enforceable confidentiality is the non-disclosure agreement's single purpose. The tell: NDA = keep it secret, BPA = partnership terms, MOA = binding cooperation roles, SLA = service commitments."},
  {"id":"q676","domain":"D5","family":"agreements","question":"Two entrepreneurs launching a shared company sign a document defining ownership percentages, profit sharing, and how deadlocked decisions get resolved. Which agreement is this?","options":["BPA","MOU","MSA","MOA"],"correctIndex":0,"explanation":"BPA. Ownership, profit split, and decision rights are the business partnership agreement's content. The tell: BPA = the partnership's internal rules, MSA = client/vendor master terms, MOU = non-binding intent, MOA = binding cooperation without partnership."},
  {"id":"q677","domain":"D5","family":"agreements","question":"A maintenance firm receives a client document authorizing exactly one task: repaint the lobby of one branch by August 15 for a fixed fee. Which document is this?","options":["work order","MSA","SLA","MOU"],"correctIndex":0,"explanation":"Work order. A single discrete task with a date and price is a work order (the SOW's small sibling for simple jobs). The tell: work order = one bounded task, SOW = a fuller project scope, MSA = the master framework, SLA = ongoing service metrics."},
  {"id":"q678","domain":"D5","family":"agreements","question":"A contracts primer contrasts two documents: one sets measurable targets with penalties; the other records only a general, non-binding statement of mutual intent. Which is the second document?","options":["SLA","MSA","SOW","MOU"],"correctIndex":3,"explanation":"MOU. Non-binding mutual intent is the MOU; the measurable-targets-with-penalties document it is contrasted against is the SLA. The tell: MOU = intent without teeth, SLA = numbers with teeth, MSA = master terms, SOW = project scope."},
  {"id":"q679","domain":"D5","family":"agreements","question":"In a vendor contract stack, which document is the master framework that individual statements of work attach to, rather than the scope of any one specific job?","options":["SOW","MSA","SLA","BPA"],"correctIndex":1,"explanation":"MSA. The master service agreement is the standing framework; each SOW plugs a specific project into it. The tell: MSA = the trunk, SOW = the branches, SLA = performance metrics within either, BPA = partnership structure."},
  {"id":"q680","domain":"D5","family":"compliance","question":"After years of repeated health-data violations, the regulator revokes a hospital lab's authorization to operate at all - the business is legally barred from continuing. Which compliance consequence is this?","options":["Loss of license","Fines","Reputational damage","Sanctions"],"correctIndex":0,"explanation":"Loss of license. Losing the legal authorization to operate is the terminal compliance consequence, beyond any fine. The tell: loss of license = you may no longer operate, fines = monetary penalties, sanctions = imposed restrictions short of closure, reputational damage = the market's punishment."},
  {"id":"q681","domain":"D5","family":"compliance","question":"Following a breach of customer records, the company is legally required to notify the data-protection regulator within 72 hours and inform affected individuals. This obligation is an example of what?","options":["Contractual impacts","Sanctions","External reporting","Internal reporting"],"correctIndex":2,"explanation":"External reporting. Mandatory breach notification to regulators and the public is external reporting - disclosure outside the organization required by law. The tell: external reporting = telling regulators/public, internal reporting = informing your own leadership, sanctions = penalties imposed on you, contractual impacts = consequences under agreements."},
  {"id":"q682","domain":"D5","family":"compliance","question":"After failing its payment-card standard audit, a merchant is ordered to pay a monetary penalty to the card brands and faces higher processing fees. Which compliance consequence is the monetary penalty?","options":["fines","sanctions","reputational damage","loss of license"],"correctIndex":0,"explanation":"Fines. Direct monetary penalties for non-compliance are fines, whether levied by regulators or industry bodies. The tell: fines = pay money, sanctions = imposed restrictions on activity, reputational damage = the market punishes you, loss of license = you may no longer operate."},
  {"id":"q683","domain":"D5","family":"compliance","question":"Weeks of news coverage about a company's badly handled breach send customers to competitors and crater its brand-trust scores, though no regulator has acted. Which consequence is this?","options":["fines","loss of license","reputational damage","contractual impacts"],"correctIndex":2,"explanation":"Reputational damage. The market's verdict - lost customers and trust - is reputational damage, often costlier than any fine and imposed by no authority. The tell: reputational damage = the public's punishment, fines = a regulator's bill, loss of license = forced shutdown, contractual impacts = consequences under agreements."},
  {"id":"q684","domain":"D5","family":"due-diligence-care","question":"Before onboarding a cloud vendor, a firm digs into the vendor's SOC 2 reports, financial stability, and breach history to understand exactly what it would be signing up for. This upfront investigation is best described as what?","options":["Due care","Due diligence","Attestation","Acknowledgement"],"correctIndex":1,"explanation":"Due diligence. The investigation BEFORE the decision - researching what you are getting into - is due diligence. The tell: due diligence = look before you leap, due care = act responsibly on an ongoing basis afterward, attestation = formally affirming something is true, acknowledgement = confirming receipt or awareness."},
  {"id":"q685","domain":"D5","family":"due-diligence-care","question":"After engaging the vendor, the firm keeps doing the responsible things - maintaining access controls, monitoring, patching - to protect the shared data day after day. These ongoing reasonable actions are called what?","options":["Due care","Due diligence","Attestation","Acknowledgement"],"correctIndex":0,"explanation":"Due care. Continuously acting as a reasonable, prudent organization would is due care - the ongoing conduct, where due diligence was the upfront homework. The tell: due care = ongoing responsible action, due diligence = the prior investigation, attestation = signed affirmation, acknowledgement = confirmed awareness."},
  {"id":"q686","domain":"D5","family":"due-diligence-care","question":"A compliance package includes a signed statement in which an executive formally affirms that a specific control is implemented and operating as described. Which term names this formal affirmation?","options":["Due diligence","Due care","Acknowledgement","Attestation"],"correctIndex":3,"explanation":"Attestation. Formally affirming, usually in writing, that a condition or control is true is attestation - it carries accountability for the claim. The tell: attestation = signed affirmation of truth, acknowledgement = confirming you received/are aware, due diligence = investigating first, due care = behaving responsibly ongoing."},
  {"id":"q687","domain":"D5","family":"due-diligence-care","question":"Before approving an acquisition, a board member digs through the target's compliance history, audit reports, and open litigation to know exactly what the company would be buying. Which term names this pre-decision investigation?","options":["due care","attestation","acknowledgement","due diligence"],"correctIndex":3,"explanation":"Due diligence. Investigating before committing is due diligence - the homework phase. The tell: due diligence = research before the decision, due care = responsible conduct after it, attestation = formally affirming a fact, acknowledgement = confirming receipt or awareness."},
  {"id":"q688","domain":"D5","family":"due-diligence-care","question":"After the annual security policy update, every employee signs a form confirming they received and understood the new policy. Which term BEST describes this act?","options":["acknowledgement","attestation","due care","due diligence"],"correctIndex":0,"explanation":"Acknowledgement. Confirming receipt and awareness is acknowledgement; attesting would mean affirming that some control or condition is actually true. The tell: acknowledgement = I received and understood it, attestation = I affirm it is true, due diligence/due care = investigation and ongoing prudence."},
  {"id":"q689","domain":"D5","family":"due-diligence-care","question":"A liability seminar contrasts two duties: the upfront investigation before an engagement, and the ongoing reasonable actions taken to protect assets after it begins. Which term names the ongoing duty?","options":["due diligence","attestation","due care","acknowledgement"],"correctIndex":2,"explanation":"Due care. The continuing duty to act as a reasonable, prudent organization is due care; due diligence was the investigation that preceded it. The tell: diligence = before (investigate), care = after (act responsibly, continuously)."},
  {"id":"q690","domain":"D5","family":"privacy","question":"A customer emails a formal request demanding the company erase every piece of personal data it holds about her, as privacy law entitles her to do. Which privacy right is she exercising?","options":["Data inventory","Right to be forgotten","Data retention","Data subject"],"correctIndex":1,"explanation":"Right to be forgotten. The enforceable demand for erasure of one's personal data is the right to be forgotten (right to erasure). The tell: right to be forgotten = delete my data, data subject = the person the data is about, data inventory = the org's map of what it holds, data retention = how long data is kept."},
  {"id":"q691","domain":"D5","family":"privacy","question":"In privacy law, which term names the individual human being that a set of personal data actually describes?","options":["Data subject","Data controller","Data processor","Data custodian"],"correctIndex":0,"explanation":"Data subject. The person the data is about is the data subject - the one privacy rights belong to. The tell: data subject = the individual described, data controller = decides purpose and means, data processor = handles data on instructions, data custodian = the technical caretaker."},
  {"id":"q692","domain":"D5","family":"privacy","question":"To comply with privacy law, a company builds a catalog of exactly what personal data it holds, which systems store it, and the purpose for each collection. Which practice is this?","options":["data inventory","right to be forgotten","retention","data subject"],"correctIndex":0,"explanation":"Data inventory. The catalog of what personal data exists, where, and why is the data inventory - the prerequisite for honoring any privacy right. The tell: data inventory = the map of held data, right to be forgotten = the erasure demand, retention = how long data is kept, data subject = the person described."},
  {"id":"q693","domain":"D5","family":"privacy","question":"A privacy policy commits to keeping customer records for seven years and deleting them afterward. Which concept does the seven-year period define?","options":["data inventory","retention","right to be forgotten","ownership"],"correctIndex":1,"explanation":"Retention. The defined keep-then-delete period is the retention schedule, balancing legal requirements against data-minimization. The tell: retention = how long data lives, data inventory = what data exists, right to be forgotten = deletion on the subject's demand, ownership = accountability for the data."},
  {"id":"q694","domain":"D5","family":"audits","question":"A department scores its own controls against a checklist and reports results up to its own manager - no reviewer from outside the team is involved. Which audit type is this?","options":["Independent third-party audit","External audit","Regulatory examination","Self-assessment"],"correctIndex":3,"explanation":"Self-assessment. Reviewing your own controls yourself is a self-assessment: cheap, fast, and least convincing to outsiders. The tell: self-assessment = graded your own homework, internal audit = the org's audit function reviews, external/third-party = unaffiliated outsiders review, regulatory examination = the regulator itself inspects."},
  {"id":"q695","domain":"D5","family":"audits","question":"To satisfy investors who distrust in-house reviews, a company engages an unaffiliated auditing firm with no financial stake in the outcome to examine its controls objectively. Which audit type is this?","options":["Self-assessment","Internal audit","Attestation","Independent third-party audit"],"correctIndex":3,"explanation":"Independent third-party audit. An unaffiliated outside firm with no stake delivers the objectivity internal reviews cannot. The tell: independent third-party = unaffiliated outsiders, internal audit = the company's own audit staff, self-assessment = the team itself, attestation = the signed conclusion an audit may produce."},
  {"id":"q696","domain":"D5","family":"audits","question":"A company's audit committee has in-house staff review control effectiveness across departments and report the findings to the board - no outside firm is engaged. Which audit type is this?","options":["external audit","internal audit","independent third-party","attestation"],"correctIndex":1,"explanation":"Internal audit. The organization's own audit function reviewing controls and reporting to the board is an internal audit - more rigorous than a self-assessment, less independent than an outside review. The tell: internal audit = your audit staff, self-assessment = the team grading itself, external/third-party = outsiders, attestation = the resulting signed affirmation."},
  {"id":"q697","domain":"D5","family":"audits","question":"A banking regulator's examiners arrive to formally inspect a bank's controls and records, confirming compliance with the law the regulator enforces. Which audit type is this?","options":["self-assessment","internal audit","external audit","attestation"],"correctIndex":2,"explanation":"External audit. An outside authority - here the regulator itself - examining the organization is an external audit (a regulatory examination). The tell: external = conducted from outside the organization, internal = your own audit staff, self-assessment = the team itself, attestation = the signed conclusion."},
  {"id":"q698","domain":"D5","family":"pentest-types","question":"A penetration tester is hired with zero inside help: no documentation, no credentials, no network diagrams. Everything must be discovered exactly as a real external attacker would. Which engagement type is this?","options":["Known environment","Partially known environment","Unknown environment","Integrated"],"correctIndex":2,"explanation":"Unknown environment. No prior knowledge is the unknown-environment test (the SY0-701 term for the retired color-box naming), maximizing realism at the cost of time. The tell: unknown = no information, known = full documentation and access, partially known = some but not all, integrated = combined testing approach."},
  {"id":"q699","domain":"D5","family":"pentest-types","question":"In early reconnaissance, an analyst mines public records, search engines, DNS registries, and social media - and never sends a single packet toward the target's systems. Which activity is this?","options":["Passive reconnaissance","Active reconnaissance","Known environment","Defensive testing"],"correctIndex":0,"explanation":"Passive reconnaissance. Gathering intelligence without touching the target is passive; the moment you probe their systems - scans, pings - it becomes active. The tell: passive = they cannot detect you looking, active = your packets hit their infrastructure, known environment = an engagement type, not a recon method."},
  {"id":"q700","domain":"D5","family":"pentest-types","question":"A scoping document grants the penetration tester the network diagram and a standard user account, but withholds admin credentials and application source code. Which testing approach is this?","options":["Known environment","Unknown environment","Active reconnaissance","Partially known environment"],"correctIndex":3,"explanation":"Partially known environment. Some inside knowledge but not all is the partially known test, balancing realism against efficiency. The tell: partially known = some information provided, known = everything provided, unknown = nothing provided, active reconnaissance = a probing technique, not an engagement type."},
  {"id":"q701","domain":"D5","family":"pentest-types","question":"A penetration tester begins the engagement holding full network diagrams, application source code, and administrative credentials - total inside knowledge from day one. Which engagement type is this?","options":["unknown environment","partially known environment","passive reconnaissance","known environment"],"correctIndex":3,"explanation":"Known environment. Full documentation and access is the known-environment test: maximum coverage per hour, minimum realism. The tell: known = everything shared, unknown = nothing shared, partially known = something shared, passive reconnaissance = a recon technique, not an engagement type."},
  {"id":"q702","domain":"D5","family":"pentest-types","question":"An analyst runs port scans and fires crafted packets directly at the target to map live services - actions the target's sensors could log and alert on. Which reconnaissance type is this?","options":["passive reconnaissance","active reconnaissance","unknown environment","known environment"],"correctIndex":1,"explanation":"Active reconnaissance. Probing the target directly - scans, crafted packets - is active recon, detectable by the defender. The tell: active = your traffic touches their systems, passive = you only consult public sources, known/unknown environment = engagement scoping, not recon methods."},
  {"id":"q703","domain":"D5","family":"pentest-types","question":"An engagement's scoping document gives the tester the network diagrams but no credentials or source code - partial inside knowledge before the probing begins. Which engagement type is this?","options":["known environment","unknown environment","partially known environment","passive reconnaissance"],"correctIndex":2,"explanation":"Partially known environment. Some but not all inside information defines the partially known test, trading a little realism for efficiency. The tell: partially known = a slice of knowledge, known = the whole picture, unknown = none, passive reconnaissance = public-source information gathering."},
  {"id":"q704","domain":"D5","family":"awareness","question":"Each quarter, the security team sends employees realistic fake phishing emails, tracks who clicks and who reports, and tailors follow-up training to the results. What is this exercise called?","options":["Recurring reporting","Risky behavior","Initial reporting","Phishing campaign"],"correctIndex":3,"explanation":"Phishing campaign. Simulated phishing to measure and improve user response is an internal phishing campaign, the awareness program's live-fire drill. The tell: phishing campaign = the simulation exercise, recurring/initial reporting = how program results get reported, risky behavior = a category the campaign measures."},
  {"id":"q705","domain":"D5","family":"awareness","question":"An employee accidentally emails a spreadsheet of customer records to the wrong recipient - pure mistake, no ill intent, promptly self-reported. Which category of anomalous behavior is this?","options":["Risky behavior","Unexpected behavior","Unintentional behavior","Recurring reporting"],"correctIndex":2,"explanation":"Unintentional behavior. An honest mistake without intent is unintentional - the answer is training and guardrails, not discipline. The tell: unintentional = accident, risky = knowingly cutting corners (password sharing, policy bypass), unexpected = out-of-pattern activity that needs investigating, recurring reporting = a program metric."},
  {"id":"q706","domain":"D5","family":"awareness","question":"An employee knowingly disables the endpoint protection agent to install an unapproved application, fully aware this violates policy. Which category of anomalous behavior is this?","options":["risky behavior","unexpected behavior","unintentional behavior","recurring reporting"],"correctIndex":0,"explanation":"Risky behavior. Knowingly bypassing controls or policy is risky behavior - deliberate corner-cutting, distinct from an honest mistake. The tell: risky = knew better and did it anyway, unintentional = genuine accident, unexpected = out-of-pattern activity needing investigation, recurring reporting = a program metric."},
  {"id":"q707","domain":"D5","family":"awareness","question":"A security awareness program sends staff refreshers every quarter and publishes its metrics to leadership on the same fixed cadence all year. Which reporting type is this?","options":["initial reporting","recurring reporting","risky behavior","phishing campaign"],"correctIndex":1,"explanation":"Recurring reporting. Fixed-cadence, repeated reporting of awareness activity and metrics is recurring reporting; the program's kickoff numbers were initial reporting. The tell: recurring = on a schedule forever, initial = the first baseline report, phishing campaign = the simulation exercise, risky behavior = a category being reported on."}
];
